  /// <summary> К какому типу относится текущее окно </summary>
  /// <param name="docType"></param>
  /// <returns></returns>
  public static Vedomost_VB_Static.VB_Window Get_TypeWindow(int docType)
  {
    Vedomost_VB_Static.VB_Window typeWindow = Vedomost_VB_Static.VB_Window.Undefined;
    if (MetaDataHelper.IsObjectTypeChildOf(docType, AvsIDCache.ObjType_Specification))
      typeWindow = Vedomost_VB_Static.VB_Window.Specification;
    else if (MetaDataHelper.IsObjectTypeChildOf(docType, AvsIDCache.ObjType_Vedomost))
      typeWindow = Vedomost_VB_Static.VB_Window.Ved;
    else if (MetaDataHelper.IsObjectTypeChildOf(docType, AvsIDCache.ObjType_ConstrTabl))
      typeWindow = Vedomost_VB_Static.VB_Window.Tabl;
    else if (MetaDataHelper.IsObjectTypeChildOf(docType, AvsIDCache.ObjType_Espd))
      typeWindow = Vedomost_VB_Static.VB_Window.Espd;
    else if (MetaDataHelper.IsObjectTypeChildOf(docType, AvsIDCache.ObjType_EspdLU))
      typeWindow = Vedomost_VB_Static.VB_Window.EspdLU;
    else if (MetaDataHelper.IsObjectTypeChildOf(docType, AvsIDCache.ObjType_VedomostDocumentTemplate))
      typeWindow = Vedomost_VB_Static.VB_Window.VedTemplate;
    else if (MetaDataHelper.IsObjectTypeChildOf(docType, AvsIDCache.ObjType_ConstrTablTemplate))
      typeWindow = Vedomost_VB_Static.VB_Window.TablTemplate;
    else if (MetaDataHelper.IsObjectTypeChildOf(docType, AvsIDCache.ObjType_DocumsExpluat))
      typeWindow = Vedomost_VB_Static.VB_Window.Ved;
    else if (MetaDataHelper.IsObjectTypeChildOf(docType, AvsIDCache.ObjType_DocumsProg))
      typeWindow = Vedomost_VB_Static.VB_Window.Ved;
    return typeWindow;
  }

  public static void Check_For_VB()
  {
    if (Vedomost_VB_Static.Is_Check_For_VB)
      return;
    if (MetaDataHelper.GetAttributeTypeID(Vedomost_VB_Static.GuidNastrVed_Main) == -10000)
    {
      Vedomost_VB_Static.Is_Check_For_VB = false;
    }
    else
    {
      using (SessionKeeper sessionKeeper = new SessionKeeper())
      {
        Vedomost_VB_Static.IsConstrVed = sessionKeeper.Session.GetObject(Vedomost_VB_Static.GuidTemplateVS, false) != null;
        Vedomost_VB_Static.IsConstrTabl = sessionKeeper.Session.GetObject(Vedomost_VB_Static.GuidTemplateTablSoed, false) != null;
        Vedomost_VB_Static.isComputerName_Victor = sessionKeeper.Session.ComputerName == "VICTOR";
      }
      Vedomost_VB_Static.IsAvs6ToIps = MetaDataHelper.GetAttributeTypeID(Vedomost_VB_Static.Guid_Accord_Avs6_IpsAttr) != -10000;
      if (Vedomost_VB_Static.IsUse_New_System_ByOneNastrMain || Vedomost_VB_Static.isComputerName_Victor)
        Vedomost_VB_Static.Get_List_QuickObjectInfo_From_Base(true);
      Vedomost_VB_Static.Begin_For_Ved();
      Vedomost_VB_Static.Begin_For_Tabl();
      if (Vedomost_VB_Static.Is_Create_Confirmity)
        Vedomost_VB_Static.Get_List_QuickObjectInfo_From_Base(false);
      Vedomost_VB_Static.Is_Check_For_VB = true;
    }
  }

  /// <summary> Создание всех списков для работы с ведомостями </summary>
  public static void Begin_For_Ved()
  {
    if (Vedomost_VB_Static.isBegin_For_Ved)
      return;
    string ipsVersion = Vedomost_VB_Static.AssemblyAttributes.IPSVersion;
    if (ipsVersion.StartsWith("8") || ipsVersion.StartsWith("9") || AvsIDCache.Attr_IsOnEspd > 1)
      Vedomost_VB_Static.isOnEspd = true;
    Vedomost_VB_Static.List_TemplateVed_Guids_Create();
    Vedomost_VB_Static.GuidTemplateESPD = Vedomost_VB_Static.Get_GuidTemplateVedomosy_ByGuidTypeVed(Vedomost_VB_Static.GuidSPESPD);
    Vedomost_VB_Static.GuidTemplateESPDLU = Vedomost_VB_Static.Get_GuidTemplateVedomosy_ByGuidTypeVed(Vedomost_VB_Static.GuidLUESPD);
    Vedomost_VB_Static.List_TemplateVed_QuickObjectInfo_Create();
    Vedomost_VB_Static.List_TypeVed_Systems_withIni_Create();
    Vedomost_VB_Static.List_Ved_imsObjectType_Filled(false);
    Vedomost_VB_Static.List_Ved_Arbeit_ImsObjectType_With_One_Ved_Nastr_Filled(false);
    Vedomost_VB_Static.List_Ved_OpisanieVed_Create();
    if (Vedomost_VB_Static.IsUse_New_System_ByOneNastrMain && Vedomost_VB_Static.is_Status_New_Nastr_Vetka == 1 && Vedomost_VB_Static._list_Ved_Arbeit_ImsObjectType_With_One_Ved_Nastr != null && Vedomost_VB_Static._list_Ved_Arbeit_ImsObjectType_With_One_Ved_Nastr.Count > 0 && Vedomost_VB_Static.List_Conformity_Template_Nastr_Ved.Count < 2)
      Vedomost_VB_Static.List_Conformity_Template_Nastr_Filled(Vedomost_VB_Static._list_Ved_Arbeit_ImsObjectType_With_One_Ved_Nastr, Vedomost_VB_Static.List_Conformity_Template_Nastr_Ved, Vedomost_VB.TypeDoc.Ved);
    else if (Vedomost_VB_Static.IsUse_New_System_ByOneNastr)
    {
      Vedomost_VB_Static.List_Conformity_Template_Nastr_Control_CA(Vedomost_VB_Static._list_Ved_Arbeit_ImsObjectType_With_One_Ved_Nastr, Vedomost_VB_Static.List_Conformity_Template_Nastr_Ved, Vedomost_VB.TypeDoc.Ved);
      Vedomost_VB_Static.List_Conformity_Template_Nastr_Control_AC(Vedomost_VB_Static._list_Ved_Arbeit_ImsObjectType_With_One_Ved_Nastr, Vedomost_VB_Static.List_Conformity_Template_Nastr_Ved, Vedomost_VB.TypeDoc.Ved);
      Vedomost_VB_Static.Check_One_Ved_Nastr_ByBase(Vedomost_VB_Static.List_Conformity_Template_Nastr_Ved, Vedomost_VB.TypeDoc.Ved);
    }
    Vedomost_VB_Static._specificationSectionInfos = AVSPlugin.GetSpecificationSections();
    for (int index = 0; index < Vedomost_VB_Static._specificationSectionInfos.Count; ++index)
    {
      SpecificationSectionInfo specificationSectionInfo = Vedomost_VB_Static._specificationSectionInfos[index];
    }
    Vedomost_VB_Static.Check_User();
    Vedomost_VB_Static.Checking_FOLDER_ForDump();
    Vedomost_VB_Static.Checking_Auto_Dump();
    Vedomost_VB_Static.xmlProtocol_Last = (XmlDocument) null;
    Vedomost_VB_Static.xml_SborMainVed_Dump_Last = (XmlDocument) null;
    Vedomost_VB_Static.xml_SborVed_Dump_Last = (XmlDocument) null;
    Vedomost_VB_Static.imDocument = (ImDocument) null;
    Vedomost_VB_Static.isBegin_For_Ved = true;
  }

  /// <summary> Создание всех списков для работы с Конструкторскими таблицами </summary>
  public static void Begin_For_Tabl()
  {
    if (Vedomost_VB_Static.isBegin_For_Tabl)
      return;
    Vedomost_VB_Static.List_TemplateTabl_Guids_Create();
    Vedomost_VB_Static.List_TemplateTabl_QuickObjectInfo_Create();
    Vedomost_VB_Static.List_TypeTabl_Systems_withIni_Create();
    Vedomost_VB_Static.List_Tabl_imsObjectType_Filled(false);
    Vedomost_VB_Static.List_Tabl_Arbeit_ImsObjectType_With_One_Ved_Nastr_Filled(false);
    Vedomost_VB_Static.List_Tabl_OpisanieTabl_Create();
    Vedomost_VB_Static.List_Tabl_OpisanieVed_AnalizCorrect();
    if (Vedomost_VB_Static.IsUse_New_System_ByOneNastrMain && Vedomost_VB_Static.is_Status_New_Nastr_Vetka == 1 && Vedomost_VB_Static._list_Tabl_Arbeit_ImsObjectType_With_One_Ved_Nastr != null && Vedomost_VB_Static._list_Tabl_Arbeit_ImsObjectType_With_One_Ved_Nastr.Count > 0 && Vedomost_VB_Static.List_Conformity_Template_Nastr_Tabl.Count < 2)
      Vedomost_VB_Static.List_Conformity_Template_Nastr_Filled(Vedomost_VB_Static._list_Tabl_Arbeit_ImsObjectType_With_One_Ved_Nastr, Vedomost_VB_Static.List_Conformity_Template_Nastr_Tabl, Vedomost_VB.TypeDoc.Tabl);
    else if (Vedomost_VB_Static.IsUse_New_System_ByOneNastr)
    {
      Vedomost_VB_Static.List_Conformity_Template_Nastr_Control_CA(Vedomost_VB_Static._list_Tabl_Arbeit_ImsObjectType_With_One_Ved_Nastr, Vedomost_VB_Static.List_Conformity_Template_Nastr_Tabl, Vedomost_VB.TypeDoc.Tabl);
      Vedomost_VB_Static.List_Conformity_Template_Nastr_Control_AC(Vedomost_VB_Static._list_Tabl_Arbeit_ImsObjectType_With_One_Ved_Nastr, Vedomost_VB_Static.List_Conformity_Template_Nastr_Tabl, Vedomost_VB.TypeDoc.Tabl);
      Vedomost_VB_Static.Check_One_Ved_Nastr_ByBase(Vedomost_VB_Static.List_Conformity_Template_Nastr_Tabl, Vedomost_VB.TypeDoc.Tabl);
    }
    Vedomost_VB_Static.Check_User();
    Vedomost_VB_Static.Checking_FOLDER_ForDump();
    Vedomost_VB_Static.Checking_Auto_Dump();
    Vedomost_VB_Static.xmlProtocol_Last = (XmlDocument) null;
    Vedomost_VB_Static.xml_SborMainVed_Dump_Last = (XmlDocument) null;
    Vedomost_VB_Static.xml_SborVed_Dump_Last = (XmlDocument) null;
    Vedomost_VB_Static.imDocument = (ImDocument) null;
    Vedomost_VB_Static.isBegin_For_Tabl = true;
  }

  /// <summary> Проверка и связь с AVS6 </summary>
  public static void Begin_For_Avs6()
  {
    if (AVS6_From_Avs6Main._list_ElDocList != null && AVS6_From_Avs6Main._list_ElDocList.Count != 0)
      return;
    if (AVS6_From_Avs6Main.Check_Avs6())
      List_Element_Accord_Avs6_Ips.isAvs6 = 1;
    if (List_Element_Accord_Avs6_Ips.isAvs6 == 0 || List_Element_Accord_Avs6_Ips.isAvs6 == 1)
      AVS6_From_Avs6Main.Read();
    if (List_Element_Accord_Avs6_Ips.isAvs6 == 2)
      AVS6_From_Avs6Main.Read_Avs6Main(List_Element_Accord_Avs6_Ips.fileIni6);
    if (List_Element_Accord_Avs6_Ips.isAvs6 != 3)
      return;
    AVS6_From_Avs6Main.Read_Avs6Main("Default");
  }

  /// <summary> Определяет папку для DUMP  и очищает ее</summary>
  public static void Checking_FOLDER_ForDump()
  {
    Vedomost_VB_Static.DirectoryDump = "%IPS_VED_DUMP%";
    Vedomost_VB_Static.DirectoryDump = Environment.ExpandEnvironmentVariables(Vedomost_VB_Static.DirectoryDump);
    if (!Directory.Exists(Vedomost_VB_Static.DirectoryDump))
      Vedomost_VB_Static.DirectoryDump = (string) null;
    if (string.IsNullOrEmpty(Vedomost_VB_Static.DirectoryDump))
    {
      Vedomost_VB_Static.DirectoryDump = "%temp%\\IMClient.Debug";
      Vedomost_VB_Static.DirectoryDump = Environment.ExpandEnvironmentVariables(Vedomost_VB_Static.DirectoryDump);
      if (!Directory.Exists(Vedomost_VB_Static.DirectoryDump))
        Directory.CreateDirectory(Vedomost_VB_Static.DirectoryDump);
      Vedomost_VB_Static.DirectoryDump += "\\VEDOMOST";
      if (!Directory.Exists(Vedomost_VB_Static.DirectoryDump))
        Directory.CreateDirectory(Vedomost_VB_Static.DirectoryDump);
      Vedomost_VB_Static.CleaningDirectoryDumpVed();
    }
    else
      Vedomost_VB_Static.CleaningDirectoryDumpVed();
  }

  /// <summary> В системных переменных смотрим Создавать ли DUMP автоматически </summary>
  public static void Checking_Auto_Dump()
  {
    if (!string.IsNullOrEmpty(Vedomost_VB_Static.DirectoryDump) && Directory.Exists(Vedomost_VB_Static.DirectoryDump))
    {
