  /// <summary> Очистка папки Dump </summary>
  public static void CleaningDirectoryDumpVed()
  {
    if (string.IsNullOrEmpty(Vedomost_VB_Static.DirectoryDump))
      return;
    if (!Directory.Exists(Vedomost_VB_Static.DirectoryDump))
      return;
    try
    {
      foreach (string file in Directory.GetFiles(Vedomost_VB_Static.DirectoryDump))
        File.Delete(file);
    }
    catch (Exception ex)
    {
    }
    foreach (string directory in Directory.GetDirectories(Vedomost_VB_Static.DirectoryDump))
      Directory.Delete(directory, true);
  }

