  /// <summary> Получение шаблона по templateGuid </summary>
  /// <param name="templateGuid"></param>
  /// <returns></returns>
  public static ImDocument GetTemplate_By_TemplateGuid(Guid templateGuid)
  {
    if (templateGuid == Guid.Empty)
      return (ImDocument) null;
    long templateID = 0;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      IDBObject dbObject = sessionKeeper.Session.GetObject(templateGuid, false);
      if (dbObject == null)
        return (ImDocument) null;
      templateID = dbObject.ObjectID;
    }
    return Vedomost_VB_Static.GetTemplate_By_TemplateID(templateID);
  }

  /// <summary> Получение шаблона по templateID </summary>
  /// <param name="templateID"></param>
  /// <returns></returns>
  public static ImDocument GetTemplate_By_TemplateID(long templateID)
  {
    return templateID == 0L || templateID == -1L ? (ImDocument) null : DocumentEditorPlugin.LoadDocumentFromDBObject(templateID);
  }

