    {
      IDBObject dbObject = sessionKeeper.Session.GetObject(guid_xmlDocument, false);
      if (dbObject == null)
        return (XmlDocument) null;
      objectId = dbObject.ObjectID;
      if (dbObject.GetAttributeByID(attributeTypeId) == null)
        return (XmlDocument) null;
    }
    MemoryStream memoryStream = new MemoryStream();
    try
    {
      new BlobProcReader(objectId, AttributableElements.Object, attributeTypeId, 0, 0, (Stream) memoryStream, (BlobProcCustomClass.ProgressEventHandler) null, (BlobProcCustomClass.ThreadFinishEventHandler) null).ReadData();
      memoryStream.Position = 0L;
      xmlDocument = new XmlDocument();
      if (memoryStream.Length != 0L)
        xmlDocument.Load((Stream) memoryStream);
    }
    finally
    {
      memoryStream.Close();
    }
    return xmlDocument;
  }

