  /// <summary> REDRAWING </summary>
  /// <param name="commandState"></param>
  /// <returns></returns>
  public static bool AVSPluginExecuteCommand_ReDrawing(ICommandState commandState)
  {
    if (AVSPlugin.Instance.ActiveImDocumentEditorForm != null)
    {
      string formagroup = "Ed";
      ImDocument document = AVSPlugin.Instance.ActiveImDocumentEditorForm.Document;
      if (MetaDataHelper.GetObjectTypeGuid(AVSPlugin.Instance.ActiveImDocumentEditorForm.DocumentType) == Guid.Empty)
        return false;
      string attributeValue = document.GetAttributeValue("GroupForm", true);
      if (!string.IsNullOrEmpty(attributeValue))
        formagroup = attributeValue;
      Guid vedomostyByObjTypeVed = Vedomost_VB_Static.Get_GuidTemplateVedomosty_ByObjTypeVed(AVSPlugin.Instance.ActiveImDocumentEditorForm.DocumentType, formagroup);
      if (vedomostyByObjTypeVed == Guid.Empty)
        return false;
      ImDocument imDocument = (ImDocument) null;
      long objectId;
      using (SessionKeeper sessionKeeper = new SessionKeeper())
      {
        IDBObject dbObject = sessionKeeper.Session.GetObject(vedomostyByObjTypeVed, false);
        objectId = dbObject == null ? -1L : dbObject.ObjectID;
      }
      if (objectId != 0L && objectId != -1L)
        imDocument = Vedomost_VB_Static.LoadTemplateFromObject(objectId);
      document.AssignDocumentTemplate((ImDocumentData) imDocument, true, false, false);
      document.ApplyTemplateProperties(false, false);
      document.UpdateLayout(true);
    }
    return true;
  }

  /// <summary> Читать ШАБЛОН для объекта </summary>
  /// <param name="objectId"></param>
  /// <returns></returns>
  public static ImDocument LoadTemplateFromObject(long objectId)
  {
    ImDocument imDocument = (ImDocument) null;
    MemoryStream aDestStream = new MemoryStream();
    try
    {
      new BlobProcReader(objectId, AttributableElements.Object, Vedomost_VB_Static.fileAttrId, 0, 0, (Stream) aDestStream, (BlobProcCustomClass.ProgressEventHandler) null, (BlobProcCustomClass.ThreadFinishEventHandler) null).ReadData();
      aDestStream.Position = 0L;
      if (aDestStream.Length != 0L)
      {
        imDocument = ImDocument.LoadFromStream((Stream) aDestStream, true, false, true);
      }
      else
      {
        imDocument = new ImDocument(true);
        imDocument.Modified = false;
      }
    }
    finally
    {
      aDestStream.Close();
    }
    return imDocument;
  }

  /// <summary> Пересоздание ведомости </summary>
  /// <param name="commandState"></param>
