  public static bool AVSPluginExecuteCommand_ReCreate(ICommandState commandState)
  {
    if (AVSPlugin.Instance.ActiveImDocumentEditorForm == null)
      return false;
    ImDocument document = AVSPlugin.Instance.ActiveImDocumentEditorForm.Document;
    if (!document.GetAttributeValue("metodCreate", true).StartsWith("Auto"))
    {
      int num = (int) MessageBox.Show("Ведомость не содержит данных о головной спецификации" + "\r\n( Эти данные имеются только если ведомость создана автоматически, начиная с версии IPS 6.3)" + "\r\n\r\nПересоздание невозможно" + "\r\n\r\nВыполнить команду создания ведомости можно непосредственно из спецификации", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
      return false;
    }
    Vedomost_VB vedomostVb = new Vedomost_VB();
    string attributeValue1 = document.GetAttributeValue("_guidTypeDoc", true);
    if (attributeValue1 != "" && attributeValue1 != "0")
    {
      vedomostVb._guidTypeDoc = new Guid(attributeValue1);
      string attributeValue2 = document.GetAttributeValue("guidTemplate", true);
      Guid guidTemplate = new Guid(attributeValue2);
      if (attributeValue2 != "" && attributeValue2 != "0")
      {
        vedomostVb._guidTemplateDoc = Vedomost_VB_Static.Get_GuidTemplateVedomosy_ByGuidTypeVed(vedomostVb._guidTypeDoc);
        if (vedomostVb._guidTemplateDoc == Guid.Empty)
          vedomostVb._guidTemplateDoc = new Guid(attributeValue2);
        vedomostVb._imsObjectType_RazrabatyvaemoiVed = Vedomost_VB_Static.Get_IMSObjectType_ByTemplateGuid(vedomostVb._guidTemplateDoc, Vedomost_VB_Static._list_Ved_Arbeit_ImsObjectType_With_One_Ved_Nastr);
        if (vedomostVb._imsObjectType_RazrabatyvaemoiVed == null)
          vedomostVb._imsObjectType_RazrabatyvaemoiVed = Vedomost_VB_Static.Get_IMSObjectType_ByTemplateGuid(guidTemplate, Vedomost_VB_Static._list_Ved_Arbeit_ImsObjectType_With_One_Ved_Nastr);
        if (vedomostVb._imsObjectType_RazrabatyvaemoiVed == null)
        {
          int num = (int) MessageBox.Show("Для текущей ведомости не найден\r\n\r\nimsObjectType\r\n\r\nПересоздание невозможно", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
          return false;
        }
        vedomostVb._groupForm = Vedomost_VB.FormaGroup.Ed;
        string attributeValue3 = document.GetAttributeValue("GroupForm", true);
        vedomostVb._isGroupVed = false;
        switch (attributeValue3)
        {
          case "A":
            vedomostVb._groupForm = Vedomost_VB.FormaGroup.A;
            vedomostVb._isGroupVed = true;
            break;
          case "B":
            vedomostVb._groupForm = Vedomost_VB.FormaGroup.B;
            vedomostVb._isGroupVed = true;
            break;
        }
        vedomostVb._i_vybranogo_Ispolnenia = 0;
        string attributeValue4 = document.GetAttributeValue("_i_vybranogo_Ispolnenia", true);
        if (attributeValue4 != "" && attributeValue4 != "0")
          vedomostVb._i_vybranogo_Ispolnenia = int.Parse(attributeValue4);
        string attributeValue5 = document.GetAttributeValue("iDSP", true);
        if (attributeValue5 != "" && attributeValue5 != "0")
        {
          long ObjectIdMainSP = (long) int.Parse(attributeValue5);
          vedomostVb._metodCreate = "AutoReCreate";
          vedomostVb._metodFrom = "vedomostEditor_ReCreate";
          vedomostVb._iDSP = ObjectIdMainSP;
          string attributeValue6 = document.GetAttributeValue("prodInfo_Id", true);
          if (attributeValue6 != "" && attributeValue6 != "0")
          {
            ProductInfo productInfo = new ProductInfo();
            productInfo.Id = long.Parse(attributeValue6);
            string attributeValue7 = document.GetAttributeValue("prodInfo_ObjectType", true);
            if (attributeValue7 != "" && attributeValue7 != "0")
              productInfo.ObjectType = int.Parse(attributeValue7);
            string attributeValue8 = document.GetAttributeValue("_nameArticle", true);
            if (attributeValue8 != "" && attributeValue8 != "0")
              productInfo.Designation = attributeValue8;
            vedomostVb._prodInfo = productInfo;
          }
          vedomostVb._designationArticle = document.GetAttributeValue("_designationArticle", true);
          vedomostVb._designationDoc = document.GetAttributeValue("_designationDocLU", true);
          vedomostVb._nameArticle = document.GetAttributeValue("_nameArticle", true);
          vedomostVb.CreateVedomost(ObjectIdMainSP, true);
          return true;
        }
        int num1 = (int) MessageBox.Show("В текущей ведомости не найден\r\n\r\n_iDSP\r\n\r\nПересоздание невозможно", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
        return false;
      }
      int num2 = (int) MessageBox.Show("В текущей ведомости не найден\r\n\r\nguidTemplate\r\n\r\nПересоздание невозможно", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
      return false;
    }
    int num3 = (int) MessageBox.Show("В текущей ведомости не найден\r\n\r\nguidTypeVed\r\n\r\nПересоздание невозможно", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
    return false;
  }

  /// <summary> Изменить Тип документа </summary>
  /// <param name="commandState"></param>
  /// <returns></returns>
  public static bool AVSPluginExecuteCommand_ChangeTyp(ICommandState commandState)
  {
    if (AVSPlugin.Instance.ActiveImDocumentEditorForm != null)
    {
      VedomostEditorWindow documentEditorForm = (VedomostEditorWindow) AVSPlugin.Instance.ActiveImDocumentEditorForm;
      ImDocument document = AVSPlugin.Instance.ActiveImDocumentEditorForm.Document;
      Vedomost_VB.TypeDoc typeDoc = documentEditorForm._typeDoc;
      List<One_ImsObjectType_With_One_Ved_Nastr> listImsOfThisType = documentEditorForm.list_Ims_of_this_type;
      VyborVedomosti vyborVedomosti = new VyborVedomosti();
      vyborVedomosti._typeDoc = typeDoc;
      vyborVedomosti._list_ImsObjectType_With_One_Ved_Nastrs = listImsOfThisType;
      vyborVedomosti.Text = "Выбор типа ведомости";
      if (vyborVedomosti.ShowDialog() != DialogResult.OK)
        return false;
      string str1 = "";
      if (documentEditorForm.is_TitList_In_Document)
        str1 = "В документе есть Титульный лист\r\nон будет потерян";
      if (documentEditorForm.is_LIZM_In_Document)
      {
        if (str1 != "")
          str1 += "\r\n\r\n";
        str1 += "В документе есть Лист регистрации изменений\r\nон будет потерян";
      }
      if (str1 != "" && MessageBox.Show(str1 + "\r\n\r\n" + "Продолжить выполнение команды преобразования типа?", "Внимание!", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
        return false;
      Guid guidTypeVed = vyborVedomosti._one_Ved_Nastr_Result._guidTypeVed;
      Guid guid1 = vyborVedomosti._one_Ved_Nastr_Result._vedomostTemplateObjectGuid;
      if (document.GetAttributeValue("GroupForm", false) == "B")
      {
        Guid guid2 = Vedomost_VB_Static.Association_A_B(guid1);
        if (guid2 == Guid.Empty)
        {
          int num = (int) MessageBox.Show("В выбранном типе отсутствует шаблон групповой формы Б", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
          return false;
        }
        guid1 = guid2;
      }
      Vedomost_VB vedomostVb = Vedomost_VB_Static.ReBuilding_vedomost_VB(document, guid1, guidTypeVed, false, true);
      if (vedomostVb == null)
        return false;
      string nameTypeDoc = vedomostVb.NameTypeDoc;
      vedomostVb.NameTypeDoc = vyborVedomosti._one_Ved_Nastr_Result._nameVed;
      vedomostVb._one_Ved_Nastr_RazrabatyvaemoiVed = Vedomost_VB_Static.Read_One_Ved_Nastr_byDocTemplateGuid(guid1, guidTypeVed, typeDoc);
      if (vedomostVb._one_Ved_Nastr_RazrabatyvaemoiVed == null)
      {
        int num = (int) MessageBox.Show("Для данного типа документа отсутствуют настройки", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
        return false;
      }
      if (vedomostVb._one_Ved_Nastr_RazrabatyvaemoiVed._algorithmToPrint == null || vedomostVb._one_Ved_Nastr_RazrabatyvaemoiVed._algorithmToPrint._list_OneRazdelToPrint == null && vedomostVb._one_Ved_Nastr_RazrabatyvaemoiVed._algorithmToPrint._oneRecordToPrint_Info == null)
      {
        int num = (int) MessageBox.Show("Для данного типа документа отсутствуют настройки вывода", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
        return false;
      }
      ChangeDocumentType changeDocumentType = new ChangeDocumentType();
      string str2 = document.GetAttributeValue("_nameTypeDoc", true);
      if (str2 == "")
        str2 = "Неопределенный";
      changeDocumentType._typeVedCurr = str2;
      changeDocumentType._typeVedNew = vyborVedomosti._one_Ved_Nastr_Result._nameVed;
      changeDocumentType._designationDocCurr = document.Designation;
      if (changeDocumentType.ShowDialog() != DialogResult.OK)
        return false;
      if (changeDocumentType.radioButton_NewDoc.Checked)
        vedomostVb._designationDoc = changeDocumentType.textBoxDesignationNew.Text;
      bool quietMode = changeDocumentType.quietMode;
      vedomostVb._metodCreate = "ChangeType";
      vedomostVb._metodFrom = document.Designation;
      vedomostVb.CreateAndOpenNewDocument(true, quietMode, true);
      if (vedomostVb.sborVedTask != null)
        vedomostVb.sborVedTask.Dispose();
    }
    return true;
  }

