  /// <summary> Сравнение двух строк с учетом чисел в нем </summary>
  /// <param name="strX"></param>
  /// <param name="strY"></param>
  /// <returns></returns>
  public static int StringCompareWithNumber(string strX, string strY)
  {
    if (string.IsNullOrEmpty(strX) && string.IsNullOrEmpty(strY))
      return 0;
    if (!string.IsNullOrEmpty(strX) && string.IsNullOrEmpty(strY))
      return 1;
    if (string.IsNullOrEmpty(strX) && !string.IsNullOrEmpty(strY))
      return -1;
    if (strX == strY)
      return 0;
    int startIndex1 = 0;
    int startIndex2 = 0;
    int numberLength1 = 0;
    int numberLength2 = 0;
    int numberBegin1 = 0;
    int numberBegin2 = 0;
    double num1 = 0.0;
    double num2 = 0.0;
    NumberFormatInfo currentInfo = NumberFormatInfo.CurrentInfo;
    ParserOptions options = ParserOptions.LEADINGWHITE | ParserOptions.TRAILINGWHITE | ParserOptions.DECIMAL | ParserOptions.THOUSANDS | ParserOptions.SCIENTIFIC | ParserOptions.PERCENT | ParserOptions.IgnoreTrailingText | ParserOptions.SkipLeadingText;
    int num3;
    int num4;
    int num5;
    while (true)
    {
      ParsedNumberData number1 = new ParsedNumberData();
      int num6 = NumberParserAdvanced.ParseNumber(strX, startIndex1, options, number1, currentInfo, out numberBegin1, out numberLength1) ? 1 : 0;
      ParsedNumberData number2 = new ParsedNumberData();
      int num7 = NumberParserAdvanced.ParseNumber(strY, startIndex2, options, number2, currentInfo, out numberBegin2, out numberLength2) ? 1 : 0;
      if ((num6 & num7) != 0)
      {
        if (numberBegin1 != 0 || numberBegin2 <= 0)
        {
          if (numberBegin2 != 0 || numberBegin1 <= 0)
          {
            int length = Math.Min(Math.Min(Math.Max(numberBegin1 - startIndex1, numberBegin2 - startIndex2), strX.Length - startIndex1), strY.Length - startIndex2);
            num3 = string.Compare(strX.Substring(startIndex1, length), strY.Substring(startIndex2, length));
            if (num3 == 0)
            {
              NumberParserAdvanced.NumberToDouble(number1, out num1);
              NumberParserAdvanced.NumberToDouble(number2, out num2);
              num4 = num1.CompareTo(num2);
              if (num4 == 0)
              {
                num5 = string.Compare(strX.Substring(startIndex1, numberBegin1 - startIndex1 + numberLength1), strY.Substring(startIndex2, numberBegin2 - startIndex2 + numberLength2));
                if (num5 == 0)
                {
                  startIndex1 = numberBegin1 + numberLength1;
                  startIndex2 = numberBegin2 + numberLength2;
                }
                else
                  goto label_19;
              }
              else
                goto label_17;
            }
            else
              goto label_15;
          }
          else
            goto label_13;
        }
        else
          break;
      }
      else
        goto label_21;
    }
    return -1;
label_13:
    return 1;
label_15:
    return num3;
label_17:
    return num4;
label_19:
    return num5;
label_21:
    return string.Compare(strX.Substring(startIndex1), strY.Substring(startIndex2));
  }

  /// <summary> Проверка строки количества </summary>
  /// <param name="countS"></param>
  /// <param name="designation"></param>
  /// <param name="name"></param>
  /// <param name="objId"></param>
  /// <param name="sMessage"></param>
  /// <returns></returns>
  public static bool CheckKol(
    string countS,
    string designation,
    string name,
    long objId,
    out string sMessage)
  {
    sMessage = "";
    switch (countS)
    {
      case null:
        sMessage = $"Спецификация {designation} {name}[{Convert.ToString(objId)}]:null";
        return false;
      case "":
      case " ":
        sMessage = $"Спецификация {designation} {name}[{Convert.ToString(objId)}]:Количество пустое";
        return false;
      default:
        float result = 0.0f;
        int length = countS.IndexOf(" ");
        if (float.TryParse(length <= -1 ? countS : countS.Substring(0, length), out result))
          return true;
        sMessage = $"Спецификация {designation} {name}[{Convert.ToString(objId)}]:Количество не число";
        return false;
    }
  }

  /// <summary> Добавить новый лист для блока исполнений формы Б </summary>
  /// <param name="document"></param>
  /// <param name="firstProductIndexOnPage"></param>
  /// <returns></returns>
  internal static PageData AddNewPageForFormB(
    ImDocument document,
    string nextPageTemplateID,
    int firstProductIndexOnPage)
  {
    if (!(document.Template.FindNode(nextPageTemplateID) is PageData node))
      return (PageData) null;
    PageData pageData = (PageData) node.CloneFromTemplate(true, true);
    if (pageData == null)
      return (PageData) null;
    document.AddChildNode((DocumentTreeNode) pageData, false, false);
    Vedomost_VB_Static.SetFirstProductIndex(pageData, firstProductIndexOnPage);
    return pageData;
  }

  /// <summary>Получить индекс первого исполнения на странице. Для групповой формы Б</summary>
  /// <param name="page">Страница</param>
  /// <returns></returns>
  public static int GetFirstProductIndex(PageData page)
  {
    string s = page != null ? page.FindFirstPage().GetAttributeValue(AVSRow.DocAttr_ProductIndex, true) : throw new ArgumentNullException(nameof (page));
    int result;
    if (s == "" || !int.TryParse(s, out result))
      result = 0;
    return result;
  }

  /// <summary>Сохранить индекс первого исполнения на странице. Для групповой формы Б</summary>
  /// <param name="page">Страница</param>
  /// <returns></returns>
  public static void SetFirstProductIndex(PageData page, int productIndex)
  {
    if (page == null)
      throw new ArgumentNullException(nameof (page));
    page.FindFirstPage().SetAttributeValue(AVSRow.DocAttr_ProductIndex, productIndex.ToString());
  }

