  /// <summary> ПЕРЕСОЗДАНИЕ Vedomost_VB (ОСНОВНЫХ ДАННЫХ ДОКУМЕНТА) на основании данных, прочитанных из Document </summary>
  /// <param name="document"></param>
  /// <param name="documentTemplateGuid"></param>
  /// <returns></returns>
  public static Vedomost_VB ReBuilding_vedomost_VB(
    ImDocument document,
    Guid documentTemplateGuid,
    Guid guidTypeDoc,
    bool isConvert_A_B,
    bool isChangeTyp)
  {
    if (document == null)
      return (Vedomost_VB) null;
    if (documentTemplateGuid == Guid.Empty)
      return (Vedomost_VB) null;
    Vedomost_VB vedomost_VB = new Vedomost_VB();
    Vedomost_VB.Variables_Coordination variables_Coordination = (Vedomost_VB.Variables_Coordination) null;
    string attributeValue = document.GetAttributeValue("GroupForm", false);
    Vedomost_VB.FormaGroup formaGroup = Vedomost_VB.FormaGroup.Ed;
    if (attributeValue == "" || attributeValue == "Ed")
      formaGroup = Vedomost_VB.FormaGroup.Ed;
    if (attributeValue == "A")
    {
      formaGroup = Vedomost_VB.FormaGroup.A;
      Vedomost_VB_Static.Create_Variables_Coordination_From_Document(document, out variables_Coordination);
      if (variables_Coordination == null)
        return (Vedomost_VB) null;
      vedomost_VB._variables_Coordination = variables_Coordination;
    }
    if (attributeValue == "B")
    {
      formaGroup = Vedomost_VB.FormaGroup.B;
      Vedomost_VB_Static.Create_Variables_Coordination_From_Document(document, out variables_Coordination);
      if (variables_Coordination == null)
        return (Vedomost_VB) null;
      vedomost_VB._variables_Coordination = variables_Coordination;
    }
    vedomost_VB._groupForm = formaGroup;
    Dictionary<string, object> attributes = new Dictionary<string, object>();
    document.GetAttributes((IDictionary) attributes, false);
    Vedomost_VB_Static.ReBuilding_PasportAttributes(document, vedomost_VB);
    if (!Vedomost_VB_Static.ReBuilding_listRecordsVed_New(document, documentTemplateGuid, guidTypeDoc, vedomost_VB, isConvert_A_B))
      return (Vedomost_VB) null;
    if (vedomost_VB._variables_Coordination == null)
      vedomost_VB._variables_Coordination = new Vedomost_VB.Variables_Coordination();
    vedomost_VB.List_For_Rebuilding_From_Attributes = new List<Vedomost_VB.One_Attribute>();
    foreach (KeyValuePair<string, object> keyValuePair in attributes)
    {
      string key = keyValuePair.Key;
      string str = Convert.ToString(keyValuePair.Value);
      Vedomost_VB.One_Attribute oneAttribute = new Vedomost_VB.One_Attribute();
      oneAttribute.name_Attribute = keyValuePair.Key;
      oneAttribute.text_Attribute = Convert.ToString(keyValuePair.Value);
      string nameTypeDoc;
      if (isChangeTyp)
      {
        switch (key)
        {
          case "templateID":
            continue;
          case "_nameTypeDoc":
            vedomost_VB._nameTypeDoc = vedomost_VB._one_Ved_Nastr_RazrabatyvaemoiVed._imsObjectType.ObjectTypeName.ToString();
            oneAttribute.text_Attribute = vedomost_VB._nameTypeDoc;
            nameTypeDoc = vedomost_VB._nameTypeDoc;
            continue;
          case "_guidTypeDoc":
            vedomost_VB._guidTypeDoc = guidTypeDoc;
            oneAttribute.text_Attribute = guidTypeDoc.ToString();
            nameTypeDoc = vedomost_VB._nameTypeDoc;
            continue;
        }
      }
      vedomost_VB.List_For_Rebuilding_From_Attributes.Add(oneAttribute);
      switch (key)
      {
        case "_designationArticle":
          vedomost_VB.DesignationArticle = str;
          continue;
        case "_designationDocLU":
          vedomost_VB.DesignationDoc = str;
          continue;
        case "_kodDoc":
          vedomost_VB.KodDoc = str;
          continue;
        case "_nameArticle":
          vedomost_VB.NameArticle = str;
          continue;
        case "_nameTypeDoc":
          vedomost_VB.NameTypeDoc = str;
          continue;
        default:
          continue;
      }
    }
    return vedomost_VB;
  }

  /// <summary> Создание variables_Coordination из ДОКУМЕНТА </summary>
  /// <param name="document"></param>
  /// <param name="variables_Coordination"></param>
  /// <returns></returns>
  public static bool Create_Variables_Coordination_From_Document(
    ImDocument document,
    out Vedomost_VB.Variables_Coordination variables_Coordination)
  {
    variables_Coordination = new Vedomost_VB.Variables_Coordination();
    if (document == null)
      return false;
    string attributeValue1 = document.GetAttributeValue("VariablesCount", true);
    if (string.IsNullOrEmpty(attributeValue1))
      return false;
    int num1 = int.Parse(attributeValue1);
    for (int index = 0; index < num1; ++index)
    {
      string attributeName1 = "Variable_" + index.ToString();
      string attributeValue2 = document.GetAttributeValue(attributeName1, true);
      string attributeName2 = "Caption_" + index.ToString();
      string caption = document.GetAttributeValue(attributeName2, true);
      if (!string.IsNullOrEmpty(attributeValue2))
      {
        if (string.IsNullOrEmpty(caption))
        {
          int num2 = attributeValue2.LastIndexOf("-");
          if (num2 > 0)
          {
            int length = attributeValue2.Length;
            caption = attributeValue2.Substring(num2 + 1, length - num2 - 1);
            caption.Trim();
          }
          else
            caption = "-";
        }
        variables_Coordination.Add_Variable_WithCaption(attributeValue2, caption);
      }
    }
    return true;
  }

