  /// <param name="vedomost_VB"></param>
  /// <param name="variables_Coordination"></param>
  /// <returns></returns>
  public static bool Create_Variables_Coordination_From_Vedomost(
    Vedomost_VB vedomost_VB,
    out Vedomost_VB.Variables_Coordination variables_Coordination)
  {
    variables_Coordination = new Vedomost_VB.Variables_Coordination();
    return true;
  }

  /// <summary> Создание Vedomost_VB.listRecordsVed_New на основании данных, прочитанных из ГРАФ Document. это при ПЕРЕРИСОВКЕ ведомости </summary>
  /// <param name="document"></param>
  /// <param name="documentTemplateGuid"></param>
  /// <param name="vedomost_VB"></param>
  /// <returns></returns>
  public static bool ReBuilding_listRecordsVed_New(
    ImDocument document,
    Guid documentTemplateGuid,
    Guid guidTypeDoc,
    Vedomost_VB vedomost_VB,
    bool isConvert_A_B = false)
  {
    if (document == null || documentTemplateGuid == Guid.Empty || vedomost_VB == null)
      return false;
    One_Ved_Nastr oneVedNastr = Vedomost_VB_Static.Read_One_Ved_Nastr_byDocTemplateGuid(documentTemplateGuid, guidTypeDoc, Vedomost_VB.TypeDoc.Ved);
    if (oneVedNastr == null)
      return false;
    if (oneVedNastr._algorithmToPrint == null || oneVedNastr._algorithmToPrint._list_OneRazdelToPrint == null && oneVedNastr._algorithmToPrint._oneRecordToPrint_Info == null)
    {
      int num = (int) MessageBox.Show("Для данного типа документа отсутствуют настройки вывода", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
      return false;
    }
    IMSObjectType objectType = MetaDataHelper.GetObjectType(guidTypeDoc);
    vedomost_VB.Read_One_Ved_Nastr2(objectType);
    if (vedomost_VB._groupForm == Vedomost_VB.FormaGroup.B)
    {
      Math.Ceiling((double) vedomost_VB._variables_Coordination.list_Variables.Count / (double) oneVedNastr._algorithmToPrint_B._kolGraf);
      Vedomost_VB_Static.list_onePage_VariablesB_Create(document, vedomost_VB, oneVedNastr);
    }
    vedomost_VB._listRecordsVed_New = new List<Vedomost_VB.RecordForVed_New>();
    vedomost_VB._isReDraw = true;
    bool flag = false;
    for (int index1 = 0; index1 < document.NodesCount; ++index1)
