  /// <summary> Перенос в recordForVed_Vtor ВСЕХ Атрибутов и ГРАФ </summary>
  /// <param name="docRow"></param>
  /// <returns></returns>
  public static Vedomost_VB.RecordForVed_Vtor Create_RecordForVed_Vtor_for_Fields(TableData docRow)
  {
    if (docRow == null)
      return (Vedomost_VB.RecordForVed_Vtor) null;
    Vedomost_VB.RecordForVed_Vtor recordForVed_Vtor = new Vedomost_VB.RecordForVed_Vtor();
    recordForVed_Vtor.List_For_Rebuilding_From_Attributes = Vedomost_VB_Static.Create_List_For_Rebuilding_From_Attributes(docRow, recordForVed_Vtor);
    recordForVed_Vtor.List_For_Rebuilding_From_Graf = Vedomost_VB_Static.Create_List_For_Rebuilding_From_Graf(docRow, recordForVed_Vtor);
    return recordForVed_Vtor;
  }

  /// <summary> Перенос в recordForVed_Vtor ВСЕХ Атрибутов </summary>
  /// <param name="docRow"></param>
  /// <param name="recordForVed_Vtor"></param>
  /// <returns></returns>
  public static List<Vedomost_VB.One_Attribute> Create_List_For_Rebuilding_From_Attributes(
    TableData docRow,
    Vedomost_VB.RecordForVed_Vtor recordForVed_Vtor)
  {
    List<Vedomost_VB.One_Attribute> rebuildingFromAttributes = new List<Vedomost_VB.One_Attribute>();
    if (docRow == null)
      return rebuildingFromAttributes;
    Dictionary<string, object> attributes = new Dictionary<string, object>();
    docRow.GetAttributes((IDictionary) attributes, false);
    foreach (KeyValuePair<string, object> keyValuePair in attributes)
    {
      if (!string.IsNullOrEmpty(Convert.ToString(keyValuePair.Value)))
        rebuildingFromAttributes.Add(new Vedomost_VB.One_Attribute()
        {
          name_Attribute = keyValuePair.Key,
          text_Attribute = Convert.ToString(keyValuePair.Value)
        });
    }
    return rebuildingFromAttributes;
  }

  /// <summary> Перенос в recordForVed_Vtor ВСЕХ ГРАФ </summary>
  /// <param name="docRow"></param>
  /// <param name="recordForVed_Vtor"></param>
  /// <returns></returns>
  public static List<Vedomost_VB.One_Grafa> Create_List_For_Rebuilding_From_Graf(
    TableData docRow,
    Vedomost_VB.RecordForVed_Vtor recordForVed_Vtor)
  {
    List<Vedomost_VB.One_Grafa> rebuildingFromGraf = new List<Vedomost_VB.One_Grafa>();
    if (docRow == null)
      return rebuildingFromGraf;
    for (int index = 0; index < docRow.NodesCount; ++index)
    {
      DocumentTreeNode node = docRow.Nodes[index];
      if (node.NodeClass == "TextBoxElement")
      {
        TextData textData = (TextData) node;
        if (textData != null && textData.Text != "")
          rebuildingFromGraf.Add(new Vedomost_VB.One_Grafa()
          {
            templateId = textData.TemplateId,
            text = textData.Text
          });
      }
      else if (node.NodeClass == "TableElement" && node.Name == "Подтаблица 'всего'")
      {
        TextData textData = (TextData) node.FindFirstNodeByName("Кол итого") ?? (TextData) node.FindNode("Кол итого");
        if (textData != null && textData.Text != "")
          rebuildingFromGraf.Add(new Vedomost_VB.One_Grafa()
          {
            templateId = textData.TemplateId,
            text = textData.Text
          });
      }
    }
    return rebuildingFromGraf;
  }

  public static Vedomost_VB.RecordForVed_Vtor Create_RecordForVed_Itogo_From_Graf(
    TableData stroka_Itogo,
    Vedomost_VB.RecordForVed_New recordForVed_New)
  {
    if (stroka_Itogo == null)
      return (Vedomost_VB.RecordForVed_Vtor) null;
    Vedomost_VB.RecordForVed_Vtor vedItogoFromGraf = new Vedomost_VB.RecordForVed_Vtor();
    for (int index = 0; index < stroka_Itogo.NodesCount; ++index)
    {
      DocumentTreeNode node = stroka_Itogo.Nodes[index];
      if (node.NodeClass == "TextBoxElement")
      {
        TextData textData = (TextData) node;
        if (textData != null && textData.Text != "")
        {
          Vedomost_VB.One_Grafa oneGrafa = new Vedomost_VB.One_Grafa()
          {
            templateId = textData.TemplateId,
            text = textData.Text
          };
          if (vedItogoFromGraf.List_For_Rebuilding_From_Graf == null)
            vedItogoFromGraf.List_For_Rebuilding_From_Graf = new List<Vedomost_VB.One_Grafa>();
          vedItogoFromGraf.List_For_Rebuilding_From_Graf.Add(new Vedomost_VB.One_Grafa()
          {
            templateId = textData.TemplateId,
            text = textData.Text
          });
        }
      }
      else if (node.NodeClass == "TableElement")
      {
        if (!(node.FindFirstNodeByName("Кол итого") is TextData textData))
          textData = node.FindNode("Кол итого") as TextData;
        if (textData != null && textData.Text != "")
        {
          Vedomost_VB.One_Grafa oneGrafa1 = new Vedomost_VB.One_Grafa()
          {
            templateId = textData.TemplateId,
            text = textData.Text
          };
          if (vedItogoFromGraf.List_For_Rebuilding_From_Graf == null)
            vedItogoFromGraf.List_For_Rebuilding_From_Graf = new List<Vedomost_VB.One_Grafa>();
          Vedomost_VB.One_Grafa oneGrafa2 = new Vedomost_VB.One_Grafa();
          oneGrafa2.templateId = textData.TemplateId;
          oneGrafa2.text = textData.Text;
          vedItogoFromGraf.List_For_Rebuilding_From_Graf.Add(oneGrafa2);
          recordForVed_New.Count_Summ = float.Parse(oneGrafa2.text);
          break;
        }
      }
    }
    return vedItogoFromGraf;
  }

  /// <summary> Получение текста из граф </summary>
  /// <param name="list_For_Rebuilding_From_Graf"></param>
  /// <param name="name"></param>
  /// <returns></returns>
  public static string Text_From_List_For_Rebuilding_From_Graf(
    List<Vedomost_VB.One_Grafa> list_For_Rebuilding_From_Graf,
    string name)
  {
    if (list_For_Rebuilding_From_Graf == null || string.IsNullOrEmpty(name))
      return "";
    string str = "";
    for (int index = 0; index < list_For_Rebuilding_From_Graf.Count; ++index)
    {
      Vedomost_VB.One_Grafa oneGrafa = list_For_Rebuilding_From_Graf[index];
      if (oneGrafa.templateId == name)
      {
        str = oneGrafa.text;
        break;
      }
    }
    return str;
  }

  /// <summary> Ищем все нижележащие записи с таким же guid_RecB </summary>
  /// <param name="Guid_RecB"></param>
  /// <param name="Document"></param>
  /// <param name="One_Ved_Nastr_RazrabatyvaemoiVed"></param>
  /// <param name="Variables_Coordination"></param>
  /// <param name="DocRow_Curr"></param>
  /// <param name="IPage_From"></param>
  /// <param name="Cikl_From"></param>
  /// <returns></returns>
  public static List<TableData> TablesData_Create(
    Guid guid_RecB,
    ImDocument Document,
    One_Ved_Nastr One_Ved_Nastr_RazrabatyvaemoiVed,
    Vedomost_VB.Variables_Coordination Variables_Coordination,
    TableData DocRow_Curr,
    int IPage_From,
    int Cikl_From)
  {
    List<TableData> tableDataList = new List<TableData>();
    if (Document == null || guid_RecB == Guid.Empty)
      return tableDataList;
    string str = guid_RecB.ToString();
    bool flag = false;
    for (int index = 0; index < Cikl_From; ++index)
      tableDataList.Add((TableData) null);
    int num1 = Cikl_From + 1;
    int num2 = -1;
    for (int index = 0; index < Document.NodesCount; ++index)
    {
      DocumentTreeNode node = Document.Nodes[index];
      if (!(node.NodeClass != "Page"))
      {
        if (node.Id == "LRI" || node.Id == "Лист регистрации изменений")
        {
          num2 = index - 1;
          break;
        }
        if (index == Document.NodesCount - 1)
        {
          num2 = index;
          break;
        }
      }
    }
    for (int index1 = IPage_From; index1 <= num2; ++index1)
    {
      DocumentTreeNode node1 = Document.Nodes[index1];
      string nodeClass = node1.NodeClass;
      if (index1 == IPage_From)
        tableDataList.Add(DocRow_Curr);
      else if (!(nodeClass != "Page") && !(node1.Id == "LRI") && !(node1.Id == "Лист регистрации изменений"))
      {
        int num3 = Vedomost_VB_Static.I_CiklB_By_Page((PageData) node1, Variables_Coordination, One_Ved_Nastr_RazrabatyvaemoiVed);
        if (num3 >= num1)
        {
          if (num3 > num1)
          {
            if (!flag)
            {
              for (int index2 = 0; index2 < num3 - num1; ++index2)
                tableDataList.Add((TableData) null);
            }
            num1 = num3;
          }
          flag = false;
          string tableName = One_Ved_Nastr_RazrabatyvaemoiVed._algorithmToPrint._tableName;
          if (index1 > 0)
            tableName += " 2";
          if (node1.FindFirstNodeFromTemplate_Recursive(tableName) is TableData templateRecursive)
          {
            for (int index3 = 0; index3 < templateRecursive.NodesCount; ++index3)
            {
              if (!(templateRecursive.Nodes[index3].NodeClass != "TableElement"))
              {
                TableData node2 = (TableData) templateRecursive.Nodes[index3];
                if (string.IsNullOrEmpty(node2.GetAttributeValue("Ready", true)))
                {
                  string typeRowS = Vedomost_VB_Static.GetTypeRowS(node2);
                  if (!string.IsNullOrEmpty(typeRowS) && !(typeRowS == "Undefined") && !(typeRowS == "MainTab") && !(typeRowS == "LRI") && !(typeRowS == "Main") && !(typeRowS == "TitleVar") && !(typeRowS == "Empty"))
                  {
                    string attributeValue = node2.GetAttributeValue(nameof (guid_RecB), true);
                    if (!string.IsNullOrEmpty(attributeValue) && attributeValue == str)
                    {
                      node2.SetAttributeValue("Ready", "Yes", false, false, false);
                      tableDataList.Add(node2);
                      flag = true;
                    }
                  }
                }
              }
            }
            if (!flag && index1 == num2)
              tableDataList.Add((TableData) null);
          }
        }
      }
    }
    return tableDataList;
  }

  /// <summary> Создание RecordForVed_Vtor (вторичной записи на основании аттрибутов), прочитанных из Document </summary>
  /// <param name="attributes"></param>
  /// <returns></returns>
  public static Vedomost_VB.RecordForVed_Vtor Create_RecordForVed_Vtor_New_for_attributes(
    Dictionary<string, string> attributes)
  {
    if (attributes.Count < 1)
      return (Vedomost_VB.RecordForVed_Vtor) null;
    Vedomost_VB.RecordForVed_Vtor newForAttributes = new Vedomost_VB.RecordForVed_Vtor();
    foreach (KeyValuePair<string, string> attribute in attributes)
    {
      string key = attribute.Key;
      string s = attribute.Value;
      if (key.IndexOf("OneDataVed") < 0)
      {
        switch (key)
        {
          case "CountF_samOi_sp":
            newForAttributes.CountF_samOi_sp = float.Parse(s);
            continue;
          case "Count_Vsego":
            newForAttributes.Count_Vsego = float.Parse(s);
            continue;
          case "Count_in_Izdelie":
            newForAttributes.Count_in_Izdelie = float.Parse(s);
            continue;
          case "Count_in_Sp":
            newForAttributes.Count_in_Sp = float.Parse(s);
            continue;
          case "Count_in_SpKompl":
            newForAttributes.Count_in_SpKompl = float.Parse(s);
            continue;
          case "Count_in_SpKompl_S":
            newForAttributes.Count_in_SpKompl_S = s;
            continue;
          case "Count_in_SpRegulir":
            newForAttributes.Count_in_SpRegulir = float.Parse(s);
            continue;
          case "Count_in_SpRegulir_S":
            newForAttributes.Count_in_SpRegulir_S = s;
            continue;
          case "KudaDesignation":
            newForAttributes.KudaDesignation = s;
            continue;
          default:
            continue;
        }
      }
      else
      {
        int length1 = s.IndexOf("=");
        if (length1 > 0)
        {
          int int32 = Convert.ToInt32(s.Substring(0, length1));
          int length2 = s.Length - length1 - 1;
          string data = s.Substring(length1 + 1, length2);
          Vedomost_VB.OneDataVed oneDataVed = new Vedomost_VB.OneDataVed(Vedomost_VB.TypeDataSel.String, AttributeSourceTypes.Object, int32, (object) data);
          newForAttributes.List_OneDataVed.Add(oneDataVed);
        }
      }
    }
    return newForAttributes;
  }

