  /// <summary> Выбор из Imbase </summary>
  /// <returns></returns>
  public static long VyborFromImbase(long ObjId_Current, List<QuickObjectInfo> list_QuickObjectInfo)
  {
    List<object> catalogId = new List<object>();
    long contextObjsID = ObjId_Current;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      if (list_QuickObjectInfo != null && list_QuickObjectInfo.Count > 0)
      {
        for (int index = 0; index < list_QuickObjectInfo.Count; ++index)
        {
          QuickObjectInfo quickObjectInfo = list_QuickObjectInfo[index];
          if (quickObjectInfo.VersionGuid != Guid.Empty)
          {
            IDBObject dbObject = sessionKeeper.Session.GetObject(quickObjectInfo.VersionGuid, false);
            if (dbObject != null)
              catalogId.Add((object) dbObject.ObjectID);
          }
        }
      }
      else
      {
        IDBObject dbObject1 = sessionKeeper.Session.GetObject(Vedomost_VB_Static.GuidImbaseConctructorsky, false);
        if (dbObject1 != null)
          catalogId.Add((object) dbObject1.ObjectID);
        IDBObject dbObject2 = sessionKeeper.Session.GetObject(Vedomost_VB_Static.GuidImbaseMaterialy, false);
        if (dbObject2 != null)
          catalogId.Add((object) dbObject2.ObjectID);
      }
    }
    long num = AVSPlugin.ImbaseSelector.SelectFromCatalog("Выберите изделие", "Выберите изделие, которое необходимо добавить в документ", (object) catalogId, false, true, (int[]) null, -1, contextObjsID);
    if (num != -1L)
      ;
    return num;
  }

