    if (intList2.Count > 0)
    {
      ObjectTypesDescriptor objectTypesDescriptor = new ObjectTypesDescriptor(intList2.ToArray(), caption);
      descriptors.Add((IDescriptor) objectTypesDescriptor);
    }
    object[] objArray = SelectionWindow.Select("Выберите объект", (IDescriptor) new Intermech.Navigator.CustomNode.Descriptor("Варианты выбора объектов", descriptors), typeof (IDBTypedObjectID), (SelectionOptions) (8589938944L /*0x0200001100*/ | (!multiSelect ? 16777216L /*0x01000000*/ : 0L)));
    if (objArray == null)
      return (ArrayList) null;
    ArrayList arrayList = (ArrayList) null;
    if (objArray.Length != 0)
    {
      arrayList = new ArrayList();
      for (int index = objArray.Length - 1; index > -1; --index)
        arrayList.Add(objArray[index]);
    }
    return arrayList;
  }

