    if (AVSPlugin.IArticleService != null)
      idDocByObjectIzd = AVSPlugin.IArticleService.FindMainDocumentID(objectIdIzd, AVSPlugin.IFiltrationService != null ? AVSPlugin.IFiltrationService.FiltrationServiceOwnerID : "", (object) sk.Session);
