  /// <param name="sk"></param>
  /// <returns></returns>
  public static long Get_ObjectIdDoc_by_ObjectIzd2(long objectIdIzd, SessionKeeper sk)
  {
    if (objectIdIzd == 0L || objectIdIzd == -1L || sk == null)
      return objectIdIzd;
    long idDocByObjectIzd2 = -1;
