  /// <summary> Получить Тип объекта, например, "Стандартное изделие" </summary>
  /// <param name="objectId"></param>
  /// <param name="sk"></param>
  /// <returns></returns>
  public static string Get_ObjectTypeName(long objectId, SessionKeeper sk)
  {
    if (objectId == 0L || objectId == -1L || sk == null)
      return "";
    IDBObject dbObject = sk.Session.GetObject(objectId, false);
    if (dbObject == null)
      return (string) null;
    AttributeValues[] attributesValues = dbObject.GetAttributesValues(GetAttributeValuesModes.IncludeObligatoryAttributes | GetAttributeValuesModes.IncludeDescriptions);
    for (int index = 0; index < attributesValues.Length; ++index)
    {
      string attributeTypeName = MetaDataHelper.GetAttributeTypeName(attributesValues[index].AttributeID);
      if (attributesValues[index].Values[0] != DBNull.Value)
      {
        attributesValues[index].Values[0].ToString();
        if (attributeTypeName == "Тип объекта")
          return attributesValues[index].Descriptions[0].ToString();
      }
    }
    return "";
  }

  public static string Get_NameRazdelVed(
    List<Vedomost_VB.OneRazdelVed> list_RazdelsVed,
    int razdelVed)
  {
    string nameRazdelVed = "";
    if (razdelVed < 1 || list_RazdelsVed == null || list_RazdelsVed.Count < 1)
      return nameRazdelVed;
    for (int index = 0; index < list_RazdelsVed.Count; ++index)
    {
      Vedomost_VB.OneRazdelVed oneRazdelVed = list_RazdelsVed[index];
      if (oneRazdelVed._razdelVed == razdelVed)
        nameRazdelVed = oneRazdelVed._name;
    }
    return nameRazdelVed;
  }

  /// <summary> Вывод XML с настройками в БАЗУ (по связи шаблоном) </summary>
  /// <param name="xmlDocument"></param>
  /// <param name="vedomostTemplateObjectGuid"></param>
  /// <returns></returns>
  public static string WriteXmlNastrToBase(XmlDocument xmlDocument, Guid vedomostTemplateObjectGuid)
  {
    if (xmlDocument == null || vedomostTemplateObjectGuid == Guid.Empty || vedomostTemplateObjectGuid.ToString() == "")
      return "Параметры сохранения настроек отсутствуют";
    int attributeTypeId = MetaDataHelper.GetAttributeTypeID(Vedomost_VB_Static.GuidNastrVed_Main);
    if (attributeTypeId == -10000)
      return "Не найден атрибут настроек (settingsAttributeID == -10000)";
    string str = "";
    long objectId;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      IDBObject dbObject = sessionKeeper.Session.GetObject(vedomostTemplateObjectGuid, false);
      if (dbObject == null)
        return "Не найден объект шаблона";
      long checkoutBy = dbObject.CheckoutBy;
      if (dbObject.CheckoutBy != 0L && dbObject.CheckoutBy != sessionKeeper.Session.UserID)
        return "";
      objectId = dbObject.ObjectID;
      if (dbObject.GetAttributeByID(attributeTypeId) == null)
      {
        bool flag = false;
        if (dbObject.CheckoutBy == 0L && dbObject.ObjectModifyMode == ObjectModifyModes.Checkout)
        {
          dbObject = dbObject.CheckOut();
          if (dbObject == null)
            return "Не найден объект шаблона";
          flag = true;
        }
        try
        {
          dbObject.Attributes.AddAttribute(attributeTypeId, false);
        }
        catch
        {
          return "Неопределенная ошибка сохранения настроек";
        }
        if (flag)
          dbObject.CheckIn();
      }
    }
    MemoryStream memoryStream = new MemoryStream();
    try
    {
      xmlDocument.Save((Stream) memoryStream);
      BlobInformation aBlobInformation = new BlobInformation(0L, 0L, DateTime.Now, string.Empty, ArcMethods.ZLibPacked, string.Empty);
      new BlobProcWriter(objectId, AttributableElements.Object, attributeTypeId, 0, 0, aBlobInformation, (Stream) memoryStream, (BlobProcCustomClass.ProgressEventHandler) null, (BlobProcCustomClass.ThreadFinishEventHandler) null).WriteData();
      str = "";
      memoryStream.Position = 0L;
    }
    finally
    {
      memoryStream.Close();
    }
    return str;
  }

  /// <summary> Сохранение списка соответствия документов Avs6_Ips </summary>
  /// <param name="xmlDocument"></param>
  /// <returns></returns>
  public static bool Write_List_Element_Accord_Avs6_Ips_ToBase(XmlDocument xmlDocument)
  {
    if (xmlDocument != null)
    {
      Guid guidAccordAvs6Ips = Vedomost_VB_Static.Guid_Accord_Avs6_Ips;
      if (!(Vedomost_VB_Static.Guid_Accord_Avs6_Ips.ToString() == ""))
      {
        int attributeTypeId = MetaDataHelper.GetAttributeTypeID(Vedomost_VB_Static.Guid_Accord_Avs6_IpsAttr);
        if (attributeTypeId == -10000)
          return false;
        long objectId;
        using (SessionKeeper sessionKeeper = new SessionKeeper())
        {
          IDBObject dbObject = sessionKeeper.Session.GetObject(Vedomost_VB_Static.Guid_Accord_Avs6_Ips, false);
          if (dbObject == null)
            return false;
          objectId = dbObject.ObjectID;
          if (dbObject.GetAttributeByID(attributeTypeId) == null)
          {
            bool flag = false;
            if (dbObject.CheckoutBy == 0L && dbObject.ObjectModifyMode == ObjectModifyModes.Checkout)
            {
              dbObject = dbObject.CheckOut();
              if (dbObject == null)
                return false;
              flag = true;
            }
            dbObject.Attributes.AddAttribute(attributeTypeId, false);
            if (flag)
              dbObject.CheckIn();
          }
        }
        MemoryStream memoryStream = new MemoryStream();
        try
        {
          xmlDocument.Save((Stream) memoryStream);
          BlobInformation aBlobInformation = new BlobInformation(0L, 0L, DateTime.Now, string.Empty, ArcMethods.ZLibPacked, string.Empty);
          new BlobProcWriter(objectId, AttributableElements.Object, attributeTypeId, 0, 0, aBlobInformation, (Stream) memoryStream, (BlobProcCustomClass.ProgressEventHandler) null, (BlobProcCustomClass.ThreadFinishEventHandler) null).WriteData();
          memoryStream.Position = 0L;
        }
        finally
        {
          memoryStream.Close();
        }
        return true;
      }
    }
    return false;
  }

  /// <summary> Чтение списка соответствия документов Avs6_Ips </summary>
  /// <returns></returns>
  public static XmlDocument Read_List_Element_Accord_Avs6_Ips_FromBase()
  {
    int attributeTypeId = MetaDataHelper.GetAttributeTypeID(Vedomost_VB_Static.Guid_Accord_Avs6_IpsAttr);
    if (attributeTypeId == -10000)
    {
      int num = (int) MessageBox.Show("В Конфигураторе базы данных\r\n\r\nНастроек соответствия документов Avs6 и Ips\r\n\r\nнет", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
      return (XmlDocument) null;
    }
    long objectId;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      IDBObject dbObject = sessionKeeper.Session.GetObject(Vedomost_VB_Static.Guid_Accord_Avs6_Ips, false);
      if (dbObject == null)
        return (XmlDocument) null;
      objectId = dbObject.ObjectID;
      if (dbObject.GetAttributeByID(attributeTypeId) == null)
        return (XmlDocument) null;
    }
    return Vedomost_VB_Static.Read_xmlDocument_FromBase_ByID(objectId, attributeTypeId);
  }

  /// <summary> Сохранение в базе xmlDocument </summary>
  /// <param name="xmlDocument"></param>
  /// <param name="guid_In_Configurator"></param>
  /// <param name="guid_xmlDocument"></param>
  /// <returns></returns>
  public static bool Write_xmlDocument_ToBase(
    XmlDocument xmlDocument,
    Guid guid_In_Configurator,
    Guid guid_xmlDocument)
  {
    if (!Vedomost_VB_Static.IsUse_New_System_ByOneNastr || Vedomost_VB_Static.is_Status_New_Nastr_Vetka != 1 || guid_In_Configurator == Guid.Empty || guid_xmlDocument == Guid.Empty)
      return false;
    int attributeTypeId = MetaDataHelper.GetAttributeTypeID(guid_In_Configurator);
    if (attributeTypeId == -10000)
      return false;
    long objectId;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      IDBObject dbObject = sessionKeeper.Session.GetObject(guid_xmlDocument, false);
      if (dbObject == null)
        return false;
      long checkoutBy = dbObject.CheckoutBy;
      if (dbObject.CheckoutBy != 0L && dbObject.CheckoutBy != sessionKeeper.Session.UserID)
        return false;
      objectId = dbObject.ObjectID;
      if (dbObject.GetAttributeByID(attributeTypeId) == null)
      {
        bool flag = false;
        if (dbObject.CheckoutBy == 0L && dbObject.ObjectModifyMode == ObjectModifyModes.Checkout)
        {
          dbObject = dbObject.CheckOut();
          if (dbObject == null)
            return false;
          flag = true;
        }
        dbObject.Attributes.AddAttribute(attributeTypeId, false);
        if (flag)
          dbObject.CheckIn();
      }
    }
    MemoryStream memoryStream = new MemoryStream();
    try
    {
      xmlDocument.Save((Stream) memoryStream);
      BlobInformation aBlobInformation = new BlobInformation(0L, 0L, DateTime.Now, string.Empty, ArcMethods.ZLibPacked, string.Empty);
      new BlobProcWriter(objectId, AttributableElements.Object, attributeTypeId, 0, 0, aBlobInformation, (Stream) memoryStream, (BlobProcCustomClass.ProgressEventHandler) null, (BlobProcCustomClass.ThreadFinishEventHandler) null).WriteData();
      memoryStream.Position = 0L;
    }
    finally
    {
      memoryStream.Close();
    }
    return true;
  }

