  public static void List_Ved_imsObjectType_Filled(bool refilled)
  {
    if (Vedomost_VB_Static._list_Ved_imsObjectType != null && !refilled)
      return;
    List<Guid> childrenGuidRecursive1 = MetaDataHelper.GetObjectTypeChildrenGuidRecursive(Vedomost_VB_Static.GuidConstructorskihVedomostei);
    if (Vedomost_VB_Static._list_Ved_imsObjectType == null)
      Vedomost_VB_Static._list_Ved_imsObjectType = new List<IMSObjectType>();
    else
      Vedomost_VB_Static._list_Ved_imsObjectType.Clear();
    for (int index = 0; index < childrenGuidRecursive1.Count; ++index)
    {
      Guid objTypeGuid = childrenGuidRecursive1[index];
