      {
        IMSObjectType objectType = MetaDataHelper.GetObjectType(objTypeGuid);
        Vedomost_VB_Static._list_Ved_imsObjectType.Add(objectType);
      }
    }
    List<Guid> childrenGuidRecursive2 = MetaDataHelper.GetObjectTypeChildrenGuidRecursive(Vedomost_VB_Static.GuidDocumentsExpluatac);
    for (int index = 0; index < childrenGuidRecursive2.Count; ++index)
    {
      Guid objTypeGuid = childrenGuidRecursive2[index];
      if (!(objTypeGuid == Vedomost_VB_Static.GuidDocumentsExpluatac))
      {
        IMSObjectType objectType = MetaDataHelper.GetObjectType(objTypeGuid);
        Vedomost_VB_Static._list_Ved_imsObjectType.Add(objectType);
      }
    }
    List<Guid> childrenGuidRecursive3 = MetaDataHelper.GetObjectTypeChildrenGuidRecursive(Vedomost_VB_Static.GuidPD);
    string ipsVersion = Vedomost_VB_Static.AssemblyAttributes.IPSVersion;
    if (ipsVersion.StartsWith("8") || ipsVersion.StartsWith("9") || Vedomost_VB_Static.isOnEspd)
    {
      for (int index = 0; index < childrenGuidRecursive3.Count; ++index)
