  /// <summary> ВС, ВП - В диалоге выбора ведомости на первое место </summary>
  private static void Sort_list_Ved_imsObjectType()
  {
    if (Vedomost_VB_Static._list_Ved_imsObjectType.Count < 2)
      return;
    string str = "";
    bool flag = true;
    while (flag)
    {
      flag = false;
      for (int index = 0; index < Vedomost_VB_Static._list_Ved_imsObjectType.Count - 1; ++index)
      {
        IMSObjectType imsObjectType1 = Vedomost_VB_Static._list_Ved_imsObjectType[index];
        IMSObjectType imsObjectType2 = Vedomost_VB_Static._list_Ved_imsObjectType[index + 1];
        if (string.Compare(imsObjectType1.ObjectTypeName, imsObjectType2.ObjectTypeName) > 0)
        {
          Vedomost_VB_Static._list_Ved_imsObjectType.Insert(index, imsObjectType2);
          Vedomost_VB_Static._list_Ved_imsObjectType.RemoveAt(index + 2);
          flag = true;
        }
      }
    }
    for (int index1 = 0; index1 < 3; ++index1)
    {
      if (index1 != 0)
      {
        if (index1 == 1)
          str = "ВП";
      }
      else
        str = "ВС";
      for (int index2 = index1; index2 < Vedomost_VB_Static._list_Ved_imsObjectType.Count; ++index2)
      {
        IMSObjectType imsObjectType = Vedomost_VB_Static._list_Ved_imsObjectType[index2];
        if (imsObjectType != null && imsObjectType.ObjectTypeID != 0 && imsObjectType.ObjectTypeID != -1 && Vedomost_VB_Static.Get_DocumentTypeSuffix_ForObjectTypeId(imsObjectType.ObjectTypeID) == str)
        {
          Vedomost_VB_Static._list_Ved_imsObjectType.RemoveAt(index2);
          Vedomost_VB_Static._list_Ved_imsObjectType.Insert(index1, imsObjectType);
        }
      }
    }
  }

