    {
      Vedomost_VB_Static.TypeVedOrTabl_Systems listTypeSystem = list_Type_Systems[index1];
      for (int index2 = list_arbeit_old.Count - 1; index2 >= 0; --index2)
      {
        One_ImsObjectType_With_One_Ved_Nastr typeWithOneVedNastr = list_arbeit_old[index2];
