        {
          typeWithOneVedNastrList.Add(typeWithOneVedNastr);
          list_arbeit_old.RemoveAt(index2);
          break;
        }
      }
    }
    int index3 = 0;
    while (index3 < list_arbeit_old.Count)
    {
      One_ImsObjectType_With_One_Ved_Nastr typeWithOneVedNastr = list_arbeit_old[index3];
      if (typeWithOneVedNastr.one_Ved_Nastr._algorithmToPrint == null || typeWithOneVedNastr.one_Ved_Nastr._algorithmToPrint._list_OneRazdelToPrint == null && typeWithOneVedNastr.one_Ved_Nastr._algorithmToPrint._oneRecordToPrint_Info == null)
      {
        ++index3;
      }
      else
      {
        typeWithOneVedNastrList.Add(typeWithOneVedNastr);
        list_arbeit_old.RemoveAt(index3);
      }
    }
    int index4 = 0;
    while (index4 < list_arbeit_old.Count)
    {
      One_ImsObjectType_With_One_Ved_Nastr typeWithOneVedNastr = list_arbeit_old[index4];
      typeWithOneVedNastrList.Add(typeWithOneVedNastr);
      list_arbeit_old.RemoveAt(index4);
    }
    return typeWithOneVedNastrList;
  }

