  /// <summary> Наименование раздела СПЕЦИФИКАЦИИ по его порядковому номеру </summary>
  /// <param name="razdelId"></param>
  /// <returns></returns>
  public static string FindRazdelCaptionByRazdelNum(int razdelNum)
  {
    if (!SpecificationSectionInfo.Cached)
    {
      using (SessionKeeper sessionKeeper = new SessionKeeper())
        SpecificationSectionInfo.UpdateCacheSpecSections(sessionKeeper.Session, (IList<long>) null);
    }
    if (razdelNum >= SpecificationSectionInfo.Sections.Count)
      return "";
    SpecificationSectionInfo section = SpecificationSectionInfo.Sections[razdelNum];
    return section == null ? "" : section.Caption;
  }

