  public static string TypeRecName_by_TypeRec_Avs(string typeRec)
  {
    if (typeRec == "")
      return "";
    string str = "Неопределенная";
    if (typeRec == "Info")
      return "Информационная";
    if (typeRec == "InfoVtor" || typeRec == "Vtor")
      return "По входимости";
    if (typeRec == "Itogo" || typeRec == "InfoItogo")
      return "Итого";
    switch (typeRec)
    {
      case "TitleS":
        return "Заголовок";
      case "TitleC":
        return "Заголовок ведомостей составных частей";
      case "TitleV":
        return "Переменные данные для исполнений";
