      case "RemarkShort":
        return "Запись примечание короткое";
      case "Additional1":
        return "Дополнительная 1";
      case "Additional2":
        return "Дополнительная 2";
      case "Additional3":
        return "Дополнительная 3";
      case "Additional4":
        return "Дополнительная 4";
      default:
        return str;
    }
  }

  /// <summary> Замена недопустимых символов </summary>
  /// <param name="textIn"></param>
  /// <param name="isMoznoDliaFile"> Для имени файла</param>
  /// <returns></returns>
  public static string Replace_Invalid_Char(string textIn, bool isEtoFileName)
  {
    if (string.IsNullOrEmpty(textIn))
      return "";
    string str = textIn.Replace("*", "_").Replace("?", "_").Replace("\"", "_").Replace("<", "_").Replace(">", "_").Replace("/", "_").Replace("|", "_").Replace(" ", "_");
    if (!isEtoFileName)
      str = str.Replace("/", "_").Replace("\\", "_").Replace(":", "_").Replace(".", "_").Replace(",", "_").Replace('(', '_').Replace(')', '_').Replace(' ', '_');
    return str;
  }

  /// <summary>Получение типа документа для объекта. Например "Ведомость покупных" </summary>
  /// <param name="objectId"></param>
  /// <returns></returns>
  public static string Get_DocumentTypeName_ForObjectId(long objectId)
  {
    string typeNameForObjectId = "";
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      IDocumentTypeSettingsService customService = (IDocumentTypeSettingsService) sessionKeeper.Session.GetCustomService(typeof (IDocumentTypeSettingsService));
      QuickObjectInfo objectInfo = sessionKeeper.Session.GetObjectInfo(objectId);
      Guid sessionGuid = sessionKeeper.Session.SessionGUID;
      int objectTypeId = objectInfo.ObjectTypeID;
      DocumentTypeSettings settings = customService.GetSettings(sessionGuid, objectTypeId);
      if (settings.DocumentNameInStamp)
        typeNameForObjectId = settings.DocumentTypeName;
    }
    return typeNameForObjectId;
  }

  /// <summary> Получение суффикса типа документа по типу объекта. Например "ВП" </summary>
  /// <param name="objectTypeId"></param>
  /// <returns></returns>
  public static string Get_DocumentTypeSuffix_ForObjectTypeId(int objectTypeId)
  {
    string suffixForObjectTypeId = "";
    if (objectTypeId == 0 || objectTypeId == -1)
      return suffixForObjectTypeId;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      DocumentTypeSettings settings = ((IDocumentTypeSettingsService) sessionKeeper.Session.GetCustomService(typeof (IDocumentTypeSettingsService))).GetSettings(sessionKeeper.Session.SessionGUID, objectTypeId);
      if (settings.DocumentTypeCodeInDesignation)
        suffixForObjectTypeId = settings.DocumentTypeCode;
    }
    return suffixForObjectTypeId;
  }

  /// <summary> Получение суффикса типа документа по ObjectId. Например "ВП" </summary>
  /// <param name="objecteId"></param>
  /// <returns></returns>
  public static string Get_DocumentTypeSuffix_ForObjectTypeId(long objectId)
  {
    string suffixForObjectTypeId = "";
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      IDocumentTypeSettingsService customService = (IDocumentTypeSettingsService) sessionKeeper.Session.GetCustomService(typeof (IDocumentTypeSettingsService));
      QuickObjectInfo objectInfo = sessionKeeper.Session.GetObjectInfo(objectId);
      Guid sessionGuid = sessionKeeper.Session.SessionGUID;
      int objectTypeId = objectInfo.ObjectTypeID;
      DocumentTypeSettings settings = customService.GetSettings(sessionGuid, objectTypeId);
      if (settings.DocumentTypeCodeInDesignation)
        suffixForObjectTypeId = settings.DocumentTypeCode;
    }
    return suffixForObjectTypeId;
  }

