  /// <summary> Формирование списка КАТАЛОГОВ Imbase </summary>
  /// <returns></returns>
  public static List<QuickObjectInfo> FindCatalogs()
  {
    long[] numArray = new long[0];
    List<QuickObjectInfo> catalogs1 = new List<QuickObjectInfo>();
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      if (!(sessionKeeper.Session.GetCustomService(typeof (IImbaseServer)) is IImbaseServer customService))
        return catalogs1;
      foreach (long catalogs2 in customService.GetCatalogsList(sessionKeeper.Session.SessionGUID))
      {
        QuickObjectInfo objectInfo = sessionKeeper.Session.GetObjectInfo(catalogs2);
        catalogs1.Add(objectInfo);
      }
      return catalogs1;
    }
  }

  /// <summary> Генерация  обозначения исполнения и CAPTION </summary>
  /// <param name="designationArt"></param>
  /// <param name="eskd"></param>
  /// <param name="i_ByloIspolneniy"></param>
  /// <param name="variable"></param>
  /// <param name="caption"></param>
  /// <returns></returns>
  public static bool Variable_Create(
    string designationArt,
    bool eskd,
    int i_ByloIspolneniy,
    out string variable,
    out string caption,
    out string errorText)
  {
    variable = "";
    caption = "";
    errorText = "";
    if (string.IsNullOrEmpty(designationArt))
    {
      errorText = "Нет обозначения изделия";
      return false;
    }
    if (i_ByloIspolneniy == 0)
    {
      variable = designationArt;
      caption = !eskd ? "1" : "-";
      return true;
    }
    if (eskd)
    {
      caption = Vedomost_VB_Static.Generated_Captions_I_Eskd(i_ByloIspolneniy, i_ByloIspolneniy);
      if (string.IsNullOrEmpty(caption))
      {
        errorText = "Пустой текст заголовка исполнения";
        return false;
      }
      variable = $"{designationArt}-{caption}";
    }
    return true;
  }

  /// <summary> Генерация заголовка номера исполнения по ТЕКСТУ исполнения </summary>
  /// <param name="variable"></param>
  /// <param name="i">Порядковый номер исполнения</param>
  /// <param name="designatinArt">Обозначение изделия</param>
  /// <param name="countVariables">Количество исполнений</param>
  /// <returns></returns>
  public static string Generated_Captions(
    string variable,
    int i,
    string designationArt,
    int countVariables)
  {
    if (string.IsNullOrEmpty(variable) || string.IsNullOrEmpty(designationArt))
      return Vedomost_VB_Static.Generated_Captions_I_Eskd(i, countVariables);
    if (variable == designationArt)
      return "-";
    if (variable.IndexOf(designationArt) != 0)
      return Vedomost_VB_Static.Generated_Captions_I_Eskd(i, countVariables);
    int length1 = designationArt.Length;
    if (variable[length1] != '-')
      return Vedomost_VB_Static.Generated_Captions_I_Eskd(i, countVariables);
    int length2 = variable.Length;
    return variable.Substring(length1 + 1, length2 - length1 - 1);
  }

  /// <summary> Генерация заголовка исполнения по ПОРЯДКОВОМУ НОМЕРУ исполнения (стиль ЕСКД) </summary>
  /// <param name="i">Порядковый номер исполнения</param>
  /// <param name="countVariables">Количество исполнений</param>
  /// <returns></returns>
  public static string Generated_Captions_I_Eskd(int i, int countVariables)
  {
    string str = "-";
    if (i == 0 || i <= 0)
      return str;
    str = i.ToString();
    if (i < 10)
      str = countVariables >= 100 ? "00" + str : "0" + str;
    else if (countVariables > 99)
      str = "0" + str;
    return str;
  }

  /// <summary> Создание файла XML </summary>
  /// <param name="document"></param>
  /// <param name="vedomost_VB_new"></param>
  /// <returns></returns>
  public static bool CreateXmlFile_FromDocument(
    ImDocument document,
    Vedomost_VB vedomost_VB_new,
    bool is_Extended_List_Names_Pages_ByTemplate)
  {
    document = AVSPlugin.Instance.ActiveImDocumentEditorForm.Document;
    if (document == null || document.NodesCount < 1)
      return false;
    Vedomost_VB.AlgorithmXml algorithmXml = vedomost_VB_new._one_Ved_Nastr_RazrabatyvaemoiVed._algorithmXml;
    if (algorithmXml == null)
      return false;
    string str;
    if (string.IsNullOrEmpty(algorithmXml._folderXmlIn) || !Directory.Exists(algorithmXml._folderXmlIn))
    {
      str = Environment.ExpandEnvironmentVariables(Vedomost_VB_Static.DirectoryDump);
      if (!Directory.Exists(str))
        str = (string) null;
      if (string.IsNullOrEmpty(str))
      {
        str = "%temp%\\IMClient.Debug";
        if (!Directory.Exists(str))
          Directory.CreateDirectory(str);
      }
    }
    else
      str = algorithmXml._folderXmlIn;
    string filename = Vedomost_VB_Static.Replace_Invalid_Char($"{str}\\{document.Designation}.xml", true);
    XmlDocument xmlDocument = new XmlDocument();
    XmlDeclaration xmlDeclaration = xmlDocument.CreateXmlDeclaration("1.0", "windows-1251", "yes");
    XmlElement documentElement = xmlDocument.DocumentElement;
    xmlDocument.InsertBefore((XmlNode) xmlDeclaration, (XmlNode) documentElement);
    XmlElement element = xmlDocument.CreateElement(string.Empty, "DOCUMENT", string.Empty);
    xmlDocument.AppendChild((XmlNode) element);
    bool flag = false;
    if (vedomost_VB_new._one_Ved_Nastr_RazrabatyvaemoiVed._algorithmXml._passportOut == 2)
      flag = true;
    else if (vedomost_VB_new._one_Ved_Nastr_RazrabatyvaemoiVed._algorithmXml._passportOut == 1 && MessageBox.Show("Выводить данные основной надписи (Паспорт)?", "Внимание!", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
      flag = true;
    int nVariables = 0;
    XmlElement obligatoryXml = Vedomost_VB_Static.CreateObligatoryXML(document, xmlDocument, vedomost_VB_new, out nVariables);
    if (obligatoryXml != null)
      element.AppendChild((XmlNode) obligatoryXml);
    XmlElement newChild = (XmlElement) null;
    if (flag && algorithmXml._oneRecordXmlPasport != null && algorithmXml._oneRecordXmlPasport._listOneFieldXml != null)
      newChild = Vedomost_VB_Static.CreatePassportXML(document, xmlDocument, algorithmXml, vedomost_VB_new);
    if (newChild != null)
      element.AppendChild((XmlNode) newChild);
    XmlElement dataXml = Vedomost_VB_Static.CreateDataXML(document, xmlDocument, algorithmXml, vedomost_VB_new, nVariables, is_Extended_List_Names_Pages_ByTemplate);
    if (dataXml != null)
      element.AppendChild((XmlNode) dataXml);
    xmlDocument.Save(filename);
    if (MessageBox.Show($"Создан файл\r\n\r\n{filename}\r\n\r\nОткрыть папку с этим файлом?", "Внимание!", MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) == DialogResult.Yes)
      Process.Start(str);
    return true;
  }

  /// <summary> Создание ОБЯЗАТЕЛЬНЫХ ОБЩИХ ДАННЫХ в XML </summary>
  /// <param name="document"></param>
  /// <param name="xmlDocument"></param>
  /// <param name="vedomost_VB_new"></param>
  /// <returns></returns>
  public static XmlElement CreateObligatoryXML(
    ImDocument document,
    XmlDocument xmlDocument,
    Vedomost_VB vedomost_VB_new,
    out int nVariables)
  {
    nVariables = 0;
    if (document == null || xmlDocument == null)
      return (XmlElement) null;
    string str1 = "";
    XmlElement element1 = xmlDocument.CreateElement(string.Empty, "OBLIGATORY", string.Empty);
    Dictionary<string, object> attributes = new Dictionary<string, object>();
    document.GetAttributes((IDictionary) attributes, false);
    foreach (KeyValuePair<string, object> keyValuePair in attributes)
    {
      string key = keyValuePair.Key;
      string str2 = Convert.ToString(keyValuePair.Value);
      switch (key)
      {
        case "GroupForm":
          string text1 = str2;
          str1 = str2;
          if (!string.IsNullOrEmpty(text1))
          {
            Vedomost_VB_Static.InsertToXml_Text(xmlDocument, element1, "GroupForm", text1);
            continue;
          }
          continue;
        case "_nameArticle":
          string text2 = str2;
          if (!string.IsNullOrEmpty(text2))
          {
            Vedomost_VB_Static.InsertToXml_Text(xmlDocument, element1, "DesignationArticle", text2);
            continue;
          }
          continue;
        case "_typeVed":
          string text3 = str2;
          if (!string.IsNullOrEmpty(text3))
          {
            Vedomost_VB_Static.InsertToXml_Text(xmlDocument, element1, "TypeVed", text3);
            continue;
          }
          continue;
        case "VariablesCount":
          string text4 = str2;
          if (!string.IsNullOrEmpty(text4))
          {
            Vedomost_VB_Static.InsertToXml_Text(xmlDocument, element1, "VariablesCount", text4);
            continue;
          }
          continue;
        default:
          continue;
      }
    }
    if (str1 == "B")
    {
      DocumentTreeNode firstNodeByName = document.FindFirstNodeByName("Номера исполнений");
      if (firstNodeByName != null)
      {
        XmlElement element2 = xmlDocument.CreateElement(string.Empty, "VARIABLES", string.Empty);
        nVariables = 0;
        for (int index = 0; index < firstNodeByName.NodesCount; ++index)
        {
          string text = ((TextData) firstNodeByName.Nodes[index]).Text;
          if (!string.IsNullOrEmpty(text))
          {
            XmlElement element3 = xmlDocument.CreateElement(string.Empty, "VARIABLE", string.Empty);
            Vedomost_VB_Static.InsertToXml_Text(xmlDocument, element3, "Variable", text);
            if (element3 != null)
              element2.AppendChild((XmlNode) element3);
            ++nVariables;
          }
          else
            break;
        }
        if (element2 != null)
          element1.AppendChild((XmlNode) element2);
      }
    }
    return element1;
  }

