  /// <summary>  Создание области даных (DATA) в XML </summary>
  /// <param name="document"></param>
  /// <param name="xmlDocument"></param>
  /// <param name="algorithmXml"></param>
  /// <returns></returns>
  public static XmlElement CreateDataXML(
    ImDocument document,
    XmlDocument xmlDocument,
    Vedomost_VB.AlgorithmXml algorithmXml,
    Vedomost_VB vedomost_VB_new,
    int nVariables,
    bool is_Extended_List_Names_Pages_ByTemplate)
  {
    if (document == null || xmlDocument == null || algorithmXml == null)
      return (XmlElement) null;
    XmlElement element = xmlDocument.CreateElement(string.Empty, "DATA", string.Empty);
    string text = "";
    for (int index1 = 0; index1 < document.NodesCount; ++index1)
    {
      PageData node1 = document.Nodes[index1] as PageData;
      if (!(node1.NodeClass != "Page") && !(node1.Id == "TL") && !(node1.Id == "Титульный лист") && !(node1.Name == "Титульный лист") && !(node1.Id == "LRI") && !(node1.Name == "Лист регистрации изменений"))
      {
        TableData firstNodeByName = (TableData) node1.FindFirstNodeByName("Главная таблица");
        if (firstNodeByName != null)
        {
          for (int index2 = 0; index2 < firstNodeByName.NodesCount; ++index2)
          {
            DocumentTreeNode node2 = firstNodeByName.Nodes[index2];
            if (node2 != null)
            {
              XmlElement oneRecordXml = Vedomost_VB_Static.CreateOneRecordXml(xmlDocument, node2, algorithmXml, vedomost_VB_new, nVariables);
              if (oneRecordXml != null)
              {
                if (is_Extended_List_Names_Pages_ByTemplate && (text == "" || text != node1.Name))
                {
                  text = node1.Name;
                  Vedomost_VB_Static.InsertToXml_Text(xmlDocument, oneRecordXml, "NewTypePage", text);
                }
                element.AppendChild((XmlNode) oneRecordXml);
              }
            }
          }
        }
      }
    }
    return element;
  }

  /// <summary> Создание записи XML </summary>
  /// <param name="xmlDocument"></param>
  /// <param name="docRow"></param>
  /// <param name="algorithmXml"></param>
