    Vedomost_VB.OneRecordXml onRecordXml = (Vedomost_VB.OneRecordXml) null;
    string attributeValue1 = docRow.GetAttributeValue("TypeRec", false);
    XmlElement xmlElement_Kuda = (XmlElement) null;
    switch (attributeValue1)
    {
      case "Additional1":
        onRecordXml = algorithmXml._oneRecordXmlAdditional1;
        break;
      case "Additional2":
        onRecordXml = algorithmXml._oneRecordXmlAdditional2;
        break;
      case "Additional3":
        onRecordXml = algorithmXml._oneRecordXmlAdditional3;
        break;
      case "Additional4":
