        break;
      case "Empty":
        onRecordXml = (Vedomost_VB.OneRecordXml) null;
        break;
      case "Included":
        onRecordXml = algorithmXml._oneRecordXmlIncluded;
        break;
      case "Info":
        onRecordXml = algorithmXml._oneRecordXml_Info;
        break;
      case "Main":
