    if (onRecordXml != null)
    {
      xmlElement_Kuda = xmlDocument.CreateElement(string.Empty, "RECORD", string.Empty);
      Vedomost_VB_Static.InsertToXml_Text(xmlDocument, xmlElement_Kuda, "TypeRec", attributeValue1);
      string attributeValue2 = docRow.GetAttributeValue("TypeRow", false);
      Vedomost_VB_Static.InsertToXml_Text(xmlDocument, xmlElement_Kuda, "TypeRow", attributeValue2);
      string attributeValue3 = docRow.GetAttributeValue("Variable", false);
      Vedomost_VB_Static.InsertToXml_Text(xmlDocument, xmlElement_Kuda, "Variable", attributeValue3);
      string attributeValue4 = docRow.GetAttributeValue("guid_RecB", false);
      Vedomost_VB_Static.InsertToXml_Text(xmlDocument, xmlElement_Kuda, "guid_RecB", attributeValue4);
      string attributeValue5 = docRow.GetAttributeValue("From", false);
      Vedomost_VB_Static.InsertToXml_Text(xmlDocument, xmlElement_Kuda, "From", attributeValue5);
      for (int index = 0; index < onRecordXml._listOneFieldXml.Count; ++index)
      {
        Vedomost_VB.OneFieldXml oneFieldXml = onRecordXml._listOneFieldXml[index];
        if (oneFieldXml._typeDataToXml == Vedomost_VB.TypeDataToXml.Field)
        {
          string dateFromTreeNode = Vedomost_VB_Static.Get_DateFrom_TreeNode(docRow, oneFieldXml._nameToFile);
          if (!string.IsNullOrEmpty(dateFromTreeNode))
            Vedomost_VB_Static.InsertToXml_Text(xmlDocument, xmlElement_Kuda, oneFieldXml._nameToXml, dateFromTreeNode);
        }
        if (oneFieldXml._typeDataToXml == Vedomost_VB.TypeDataToXml.Attribute)
        {
          Dictionary<string, object> attributes = new Dictionary<string, object>();
          docRow.GetAttributes((IDictionary) attributes, false);
