            string str = Convert.ToString(keyValuePair.Value);
            string nameToFile = oneFieldXml._nameToFile;
            if (key == nameToFile)
            {
              string text = str;
              if (!string.IsNullOrEmpty(text))
                Vedomost_VB_Static.InsertToXml_Text(xmlDocument, xmlElement_Kuda, oneFieldXml._nameToXml, text);
            }
          }
        }
      }
      DocumentTreeNode documentTreeNode = docRow.FindFirstNodeByName("Подтаблица Куда входит") ?? docRow.FindFirstChildNodeByName("Подтаблица Куда входит");
      if (documentTreeNode != null)
