      if ((attributeValue1 == "Info" || attributeValue1 == "Included") && nVariables > 0)
      {
        XmlElement element1 = xmlDocument.CreateElement(string.Empty, "VARIABLES", string.Empty);
        for (int index = 0; index < nVariables; ++index)
        {
          string str = "Количество " + index.ToString();
