          {
            string key = keyValuePair.Key;
            string str2 = Convert.ToString(keyValuePair.Value);
            string nameToFile = oneFieldXml._nameToFile;
            if (key == nameToFile)
            {
              string text = str2;
              if (!string.IsNullOrEmpty(text))
                Vedomost_VB_Static.InsertToXml_Text(xmlDocument, xmlElement_Kuda, oneFieldXml._nameToXml, text);
            }
          }
        }
      }
    }
    return xmlElement_Kuda;
  }

  /// <summary> В xmlElement_Kuda втавляется атрибут с именем name и текстом caption_curr </summary>
  /// <param name="xmlDocument"></param>
  /// <param name="xmlElement_Kuda"></param>
  /// <param name="name"></param>
  /// <param name="text"></param>
  public static void InsertToXml_Text(
    XmlDocument xmlDocument,
    XmlElement xmlElement_Kuda,
    string name,
    string text)
  {
    if (string.IsNullOrEmpty(text))
      return;
    string str = text;
    XmlAttribute attribute = xmlDocument.CreateAttribute(name);
    attribute.Value = str.ToString();
    xmlElement_Kuda.Attributes.Append(attribute);
  }

  /// <summary> Чтение файла XML </summary>
  /// <returns></returns>
  public static XmlDocument Read_File_XmlFile(string initialDirectory)
  {
    XmlDocument xmlDocument = (XmlDocument) null;
    string filename = "";
    try
    {
      using (OpenFileDialog openFileDialog = new OpenFileDialog())
      {
        openFileDialog.InitialDirectory = initialDirectory;
        openFileDialog.Filter = "xml files (*.xml)|*.xml";
        openFileDialog.FilterIndex = 1;
        openFileDialog.RestoreDirectory = true;
        if (openFileDialog.ShowDialog() == DialogResult.OK)
        {
          filename = openFileDialog.FileName;
          if (!string.IsNullOrEmpty(filename))
          {
            xmlDocument = new XmlDocument();
            xmlDocument.Load(filename);
          }
        }
      }
    }
    catch (Exception ex)
    {
      int num = (int) MessageBox.Show("Ошибка чтения файла\r\n\r\n" + filename, "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
      xmlDocument = (XmlDocument) null;
    }
    return xmlDocument;
  }

  /// <summary> Получение значение атрибута по его имени </summary>
  /// <param name="xmlNode"></param>
  /// <param name="name"></param>
  /// <returns></returns>
  public static string ReadValue_byName_From_xmlNode(XmlNode xmlNode, string name)
  {
    string str = "";
    for (int i = 0; i < xmlNode.Attributes.Count; ++i)
    {
      XmlAttribute attribute = xmlNode.Attributes[i];
      if (attribute.Name == name)
      {
        str = attribute.Value;
        break;
      }
    }
    return str;
  }

