  /// <summary> Анализ XML на наличие таких записей </summary>
  /// <param name="xmlDocument"></param>
  /// <param name="isTitle"></param>
  /// <param name="isRemark"></param>
  /// <param name="isAdditional"></param>
  /// <param name="isPasport"></param>
  public static bool Analiz_Xml(
    XmlDocument xmlDocument,
    out bool isTitle,
    out bool isRemark,
    out bool isAdditional,
    out bool isPasport)
  {
    isTitle = false;
    isRemark = false;
    isAdditional = false;
    isPasport = false;
    if (xmlDocument == null)
      return false;
    XmlNode nextSibling = xmlDocument.ChildNodes[0].NextSibling;
    if (nextSibling.ChildNodes.Count < 1)
    {
      int num = (int) MessageBox.Show("Файл XML пуст", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
      return false;
    }
    XmlNode childNode1 = nextSibling.ChildNodes[0];
    if (childNode1.Name != "OBLIGATORY")
    {
      int num = (int) MessageBox.Show("В файле XML отсутствует тэг (секция) \"OBLIGATORY\"\r\nФайл не IPS/Ведомости", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
      return false;
    }
    if (string.IsNullOrEmpty(Vedomost_VB_Static.ReadValue_byName_From_xmlNode(childNode1, "TypeVed")))
    {
      int num = (int) MessageBox.Show("В файле XML отсутствует параметр \"TypeVed\"\r\nФайл не IPS/Ведомости", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
      return false;
    }
    if (nextSibling.ChildNodes.Count < 2)
    {
      int num = (int) MessageBox.Show("В файле XML отсутствуют данные", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
      return false;
    }
    XmlNode childNode2 = nextSibling.ChildNodes[1];
    if (childNode2.Name == "PASSPORT")
    {
      isPasport = true;
      if (nextSibling.ChildNodes.Count <= 2)
        return true;
      childNode2 = nextSibling.ChildNodes[2];
    }
    if (childNode2.Name == "DATA")
    {
      for (int i = 0; i < childNode2.ChildNodes.Count; ++i)
      {
        XmlNode childNode3 = childNode2.ChildNodes[i];
        if (!(childNode3.Name != "RECORD"))
        {
          string str = Vedomost_VB_Static.ReadValue_byName_From_xmlNode(childNode3, "TypeRec");
          if (!string.IsNullOrEmpty(str))
          {
            switch (str)
            {
              case "Additional1":
              case "Additional2":
              case "Additional3":
              case "Additional4":
                isAdditional = true;
                break;
              case "Remark":
                isRemark = true;
                break;
              case "Title":
              case "Title2":
              case "TitleInclude":
              case "TitleIsp":
              case "TitlePart":
              case "TitlePodSection":
              case "TitleVar":
                isTitle = true;
                break;
            }
            if (isTitle & isRemark & isAdditional)
              break;
          }
        }
      }
    }
    return true;
  }

  /// <summary> Замена (ЗАПОЛНЕНИЕ) данных ОСНОВНОЙ НАДПИСИ, а точнее в ДОКУМЕНТЕ </summary>
