  /// <summary> Заполнение списка исполнений формы Б </summary>
  /// <param name="document"></param>
  /// <param name="xmlNodeObligatore"></param>
  /// <param name="designationArticle"></param>
  public static void Filled_Obligatory_From_XMlNode(
    ImDocument document,
    XmlNode xmlNodeObligatore,
    string designationArticle)
  {
    if (document == null || xmlNodeObligatore == null)
      return;
    List<string> stringList = new List<string>();
    XmlNode childNode1 = xmlNodeObligatore.ChildNodes[0];
    if (childNode1 != null && childNode1.Name == "VARIABLES" && childNode1.ChildNodes != null)
    {
      for (int i = 0; i < childNode1.ChildNodes.Count; ++i)
      {
        XmlNode childNode2 = childNode1.ChildNodes[i];
        if (childNode2 != null && childNode2.Name == "VARIABLE")
        {
          string str = Vedomost_VB_Static.ReadValue_byName_From_xmlNode(childNode2, "Variable");
          stringList.Add(str);
        }
      }
    }
    foreach (PageData pageData in (ImDocumentData) document)
    {
      if (pageData.FindFirstNodeByName("Заголовок таблицы исполнений") is TextData firstNodeByName1)
      {
        string str = firstNodeByName1.Text;
        if (string.IsNullOrEmpty(str))
          str = Vedomost_VB_Static.Kol_na_ispoln_Template;
        firstNodeByName1.AssignText(string.Format(str + " {0} -", (object) designationArticle), false, true, false, false, false);
      }
      if (pageData.FindFirstNodeByName("Номера исполнений") is TableData firstNodeByName2)
      {
        int index = 0;
        while (true)
        {
          if (index < stringList.Count && index < firstNodeByName2.Nodes.Count)
          {
            string str = stringList[index];
            (firstNodeByName2.Nodes[index] as TextData).AssignText(str, false, true, false, false, false);
            ++index;
          }
          else
            goto label_18;
        }
      }
      else
        continue;
label_18:;
    }
  }

  /// <summary> Заполнение ВСЕЙ ЗАПИСИ данными из XML </summary>
  /// <param name="document"></param>
  /// <param name="algorithmXml"></param>
  /// <param name="xmlNodeRec"></param>
  /// <returns></returns>
  public static TableData Create_docRow_By_Xml(
    ImDocument document,
    XmlNode xmlNodeRec,
    TableData stroka_IzShablona,
    Vedomost_VB.OneRecordXml oneRecordXml,
    Vedomost_VB.OneRecordToPrint oneRecordToPrint)
  {
    if (document == null || xmlNodeRec == null || stroka_IzShablona == null || oneRecordXml == null)
      return (TableData) null;
    bool flag = false;
    string attributeValue1 = Vedomost_VB_Static.ReadValue_byName_From_xmlNode(xmlNodeRec, "TypeRec");
    if (!(stroka_IzShablona.CloneFromTemplate() is TableData docRowNew))
      return (TableData) null;
    if (oneRecordXml == null)
      return (TableData) null;
    if (!string.IsNullOrEmpty(attributeValue1))
      docRowNew.SetAttributeValue("TypeRec", attributeValue1);
    string attributeValue2 = Vedomost_VB_Static.ReadValue_byName_From_xmlNode(xmlNodeRec, "TypeRow");
    if (!string.IsNullOrEmpty(attributeValue2))
      docRowNew.SetAttributeValue("TypeRow", attributeValue2);
    string attributeValue3 = Vedomost_VB_Static.ReadValue_byName_From_xmlNode(xmlNodeRec, "Variable");
    if (!string.IsNullOrEmpty(attributeValue3))
      docRowNew.SetAttributeValue("Variable", attributeValue3);
    string attributeValue4 = Vedomost_VB_Static.ReadValue_byName_From_xmlNode(xmlNodeRec, "guid_RecB");
    if (!string.IsNullOrEmpty(attributeValue4))
      docRowNew.SetAttributeValue("guid_RecB", attributeValue4);
    string attributeValue5 = Vedomost_VB_Static.ReadValue_byName_From_xmlNode(xmlNodeRec, "From");
    if (!string.IsNullOrEmpty(attributeValue5))
      docRowNew.SetAttributeValue("From", attributeValue5);
    for (int i = 0; i < xmlNodeRec.Attributes.Count; ++i)
    {
      XmlAttribute attribute = xmlNodeRec.Attributes[i];
      string name = attribute.Name;
      string fieldValue = attribute.Value;
      string fieldName = Vedomost_VB_Static.CellName_By_AttributeName(oneRecordXml, name);
      if (!string.IsNullOrEmpty(fieldName) && Vedomost_VB_Static.Set_dateToDocRow(docRowNew, fieldName, fieldValue))
        flag = true;
    }
    if ((attributeValue1 == "Info" || attributeValue1 == "Included") && xmlNodeRec.ChildNodes != null && xmlNodeRec.ChildNodes.Count == 1)
    {
      XmlNode childNode1 = xmlNodeRec.ChildNodes[0];
      if (childNode1.Name == "SUBTABLE" && oneRecordToPrint != null && oneRecordToPrint._isVtorOblast && oneRecordToPrint._tableVtorOblastId != "0" && !string.IsNullOrWhiteSpace(oneRecordToPrint._tableVtorOblastId.ToString()))
      {
        TableData node1 = stroka_IzShablona.FindNode("Строка Куда входит") as TableData;
        TableData node2 = stroka_IzShablona.FindNode("Строка Кол итого") as TableData;
        if (docRowNew.FindNode("Подтаблица Куда входит") is TableData node3)
        {
          for (int i = 0; i < childNode1.ChildNodes.Count; ++i)
          {
            XmlNode childNode2 = childNode1.ChildNodes[i];
            if (childNode2.Name == "SUBRECORD")
            {
              TableData tableData = node1.CloneFromTemplate() as TableData;
              if (Vedomost_VB_Static.Filled_docRowVtor_By_Xml(document, oneRecordToPrint, childNode2, tableData, oneRecordXml))
              {
                node3.AddChildNode((DocumentTreeNode) tableData, false, false);
                continue;
              }
            }
            if (childNode2.Name == "TOTAL")
            {
              TableData tableData = node2.CloneFromTemplate() as TableData;
              if (Vedomost_VB_Static.Filled_docRowVtor_By_Xml(document, oneRecordToPrint, childNode2, tableData, oneRecordXml))
                node3.AddChildNode((DocumentTreeNode) tableData, false, false);
            }
          }
        }
      }
      if (childNode1.Name == "VARIABLES" && childNode1.ChildNodes != null)
      {
        for (int i = 0; i < childNode1.ChildNodes.Count; ++i)
        {
          XmlNode childNode3 = childNode1.ChildNodes[i];
          if (childNode3 != null && childNode3.Name == "VARIABLE")
          {
            string fieldName = "Количество " + i.ToString();
            string name = "Count" + i.ToString();
            string fieldValue = Vedomost_VB_Static.ReadValue_byName_From_xmlNode(childNode3, name);
            Vedomost_VB_Static.Set_dateToDocRow(docRowNew, fieldName, fieldValue);
          }
        }
      }
    }
    return flag ? docRowNew : (TableData) null;
  }

  public static bool Filled_docRowVtor_By_Xml(
    ImDocument document,
    Vedomost_VB.OneRecordToPrint oneRecordToPrintParent,
    XmlNode xmlNodeRec,
    TableData docRowVtor,
    Vedomost_VB.OneRecordXml oneRecordXmlParent)
  {
    bool flag = false;
    Vedomost_VB.OneRecordXml oneRecordXml;
    switch (xmlNodeRec.Name)
    {
      case "SUBRECORD":
        Vedomost_VB.OneRecordToPrint recordToPrintVtor = oneRecordToPrintParent._oneRecordToPrint_Vtor;
        oneRecordXml = oneRecordXmlParent._oneRecordXml_Vtor;
        break;
      case "TOTAL":
        Vedomost_VB.OneRecordToPrint recordToPrintItogo = oneRecordToPrintParent._oneRecordToPrint_Itogo;
        oneRecordXml = oneRecordXmlParent._oneRecordXml_Itogo;
        break;
      default:
        return false;
    }
    for (int i = 0; i < xmlNodeRec.Attributes.Count; ++i)
    {
      XmlAttribute attribute = xmlNodeRec.Attributes[i];
      string name = attribute.Name;
      string fieldValue = attribute.Value;
      string fieldName = Vedomost_VB_Static.CellName_By_AttributeName(oneRecordXml, name);
      if (!string.IsNullOrEmpty(fieldName) && Vedomost_VB_Static.Set_dateToDocRow(docRowVtor, fieldName, fieldValue))
        flag = true;
    }
    return flag;
  }

