  public static Vedomost_VB_Static.OneXmlNode oneRecordNode_Xml_Create(
    Vedomost_VB.OneRecordXml oneRecordXml,
    Vedomost_VB_Static.OneXmlNode oneXmlNode_Parent,
    string typeRec)
  {
    if (oneRecordXml == null)
      return (Vedomost_VB_Static.OneXmlNode) null;
    string str1 = typeRec;
    Vedomost_VB_Static.OneXmlNode oneXmlNode = new Vedomost_VB_Static.OneXmlNode();
    oneXmlNode.Text = str1;
    Vedomost_VB_Static.OneXmlNode oneXmlNode_Parent1 = oneXmlNode;
    oneXmlNode_Parent1._oneXmlNode_Parent = oneXmlNode_Parent;
    oneXmlNode_Parent1._oneRecordXml = oneRecordXml;
    oneXmlNode_Parent1._typeNode = Vedomost_VB_Static.TypeNode_Tree.Record;
    string str2 = " ЯЧЕЙКА ШАБЛОНА";
    int lBases = str2.Length;
    for (int index = 0; index < oneRecordXml._listOneFieldXml.Count; ++index)
    {
      int length = oneRecordXml._listOneFieldXml[index]._nameToFile.Length;
      if (length > lBases)
        lBases = length;
    }
    int num = lBases - str2.Length + 3;
    for (int index = 0; index < num; ++index)
      str2 += " ";
    Vedomost_VB_Static.OneXmlNode node1 = new Vedomost_VB_Static.OneXmlNode();
    node1.Text = str2 + " ИМЯ Xml";
    node1.BackColor = Color.Aqua;
    oneXmlNode_Parent1._typeNode = Vedomost_VB_Static.TypeNode_Tree.Record;
    oneXmlNode_Parent1.Nodes.Add((TreeNode) node1);
    for (int index = 0; index < oneRecordXml._listOneFieldXml.Count; ++index)
    {
      Vedomost_VB.OneFieldXml oneFieldXml = oneRecordXml._listOneFieldXml[index];
      if (oneFieldXml._typeDataToXml != Vedomost_VB.TypeDataToXml.Attribute)
      {
        Vedomost_VB_Static.OneXmlNode node2 = Vedomost_VB_Static.oneFieldNode_Xml_Create(oneRecordXml, oneFieldXml, oneXmlNode_Parent1, lBases, index);
        oneXmlNode_Parent1.Nodes.Add((TreeNode) node2);
      }
    }
    if (oneRecordXml._oneRecordXml_Vtor != null)
    {
      string typeRec1 = "Запись: Куда входит.  Строка шаблона: " + oneRecordXml._oneRecordXml_Vtor._tableRowId;
      Vedomost_VB_Static.OneXmlNode node3 = Vedomost_VB_Static.oneRecordNode_Xml_Create(oneRecordXml._oneRecordXml_Vtor, oneXmlNode_Parent1, typeRec1);
      if (node3 != null)
      {
        oneXmlNode_Parent1.Nodes.Add((TreeNode) node3);
        node3.Expand();
      }
    }
    if (oneRecordXml._oneRecordXml_Itogo != null)
    {
      string typeRec2 = "Запись: Итого.  Строка шаблона: " + oneRecordXml._oneRecordXml_Itogo._tableRowId;
      Vedomost_VB_Static.OneXmlNode node4 = Vedomost_VB_Static.oneRecordNode_Xml_Create(oneRecordXml._oneRecordXml_Itogo, oneXmlNode_Parent1, typeRec2);
      if (node4 != null)
      {
        oneXmlNode_Parent1.Nodes.Add((TreeNode) node4);
        node4.Expand();
      }
    }
    oneXmlNode_Parent1.Expand();
    return oneXmlNode_Parent1;
  }

