  /// <summary> Проверка текста имени поля XML </summary>
  /// <param name="text"></param>
  /// <param name="errorMessage"></param>
  /// <returns></returns>
  public static bool name_Field_Xml_Check(string text, TextBox textBox)
  {
    string text1 = "";
    if (string.IsNullOrEmpty(text))
      return false;
    if (text1 == "" && text.Contains(" "))
      text1 = "Имя не может содержать пробелы";
    if (text1 == "" && char.IsNumber(text[0]))
      text1 = "Имя не может начинаться с цифры";
    if (text1 == "")
    {
      foreach (char ch in text)
      {
        if ((ch < 'a' || ch > 'z') && (ch < 'A' || ch > 'Z') && (ch < '0' || ch > '9') && ch != '_')
        {
          text1 = "Имя содержит недопустимые символы";
          break;
        }
      }
    }
    if (!(text1 != ""))
      return true;
    Color backColor = textBox.BackColor;
    textBox.BackColor = Color.Orange;
    textBox.Focus();
    int num = (int) MessageBox.Show(text1, "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
    textBox.BackColor = backColor;
    return false;
  }

  /// <summary> Проверка текста имени файла </summary>
  /// <param name="text"></param>
  /// <param name="errorMessage"></param>
  /// <returns></returns>
  public static bool check_Text_For_Filename(string text, TextBox textBox)
  {
    string text1 = "";
    foreach (char ch in text)
    {
      if (ch < ' ' || ch == '<' || ch == '>' || ch == '|' || ch == '?' || ch == '*')
      {
        text1 = "Имя папки содержит недопустимые символы";
        break;
      }
    }
    if (!(text1 != ""))
      return true;
    Color backColor = textBox.BackColor;
    textBox.BackColor = Color.Orange;
    textBox.Focus();
    int num = (int) MessageBox.Show(text1, "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
    textBox.BackColor = backColor;
    return false;
  }

  /// <summary> Проверка существования имени файла </summary>
  /// <param name="text"></param>
  /// <param name="errorMessage"></param>
  /// <returns></returns>
  public static bool check_Text_For_FilenameExists(string text, TextBox textBox)
  {
    if (string.IsNullOrEmpty(text))
      return true;
    string text1 = "";
