      return true;
    Color backColor = textBox.BackColor;
    textBox.BackColor = Color.Orange;
    textBox.Focus();
    int num = (int) MessageBox.Show(text1, "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
    textBox.BackColor = backColor;
    return false;
  }

  /// <summary> Получаем ТИП выделенного элемента </summary>
  /// <param name="tableElement"></param>
  /// <returns></returns>
  public static Vedomost_VB_Static.TypeNodeElement_Shablona Check_tableElement(
    DocumentTreeNode tableElement)
  {
    Vedomost_VB_Static.TypeNodeElement_Shablona typeNodeElement = Vedomost_VB_Static.TypeNodeElement_Shablona.Undefined;
    if (tableElement != null)
    {
      string nodeClass1 = tableElement.NodeClass;
      DocumentTreeNode parent1 = tableElement.Parent;
      string nodeClass2 = parent1.NodeClass;
      string name1 = tableElement.Name;
      string name2 = parent1.Name;
      if (tableElement.Parent != null)
      {
        DocumentTreeNode parent2 = tableElement.Parent;
        if (parent2 != null)
        {
          string nodeClass3 = parent2.NodeClass;
          string name3 = parent2.Name;
          DocumentTreeNode parent3 = parent2.Parent;
          if (parent3 != null)
          {
            string nodeClass4 = parent3.NodeClass;
            string name4 = parent3.Name;
            DocumentTreeNode parent4 = parent3.Parent;
            if (parent4 != null)
            {
              string nodeClass5 = parent4.NodeClass;
              string name5 = parent4.Name;
            }
          }
        }
      }
      if (nodeClass1 == "TextBoxElement")
        typeNodeElement = Vedomost_VB_Static.TypeNodeElement_Shablona.Cell;
      else if (tableElement.NodeTypeCaption == "Таблица")
      {
        switch (name2)
        {
          case "Главная таблица":
            typeNodeElement = Vedomost_VB_Static.TypeNodeElement_Shablona.RecordMain;
            break;
          case "Подтаблица Куда входит":
            typeNodeElement = Vedomost_VB_Static.TypeNodeElement_Shablona.RecordVtor;
            break;
          default:
            if (name1 == "Подтаблица Куда входит")
            {
              typeNodeElement = Vedomost_VB_Static.TypeNodeElement_Shablona.Podtable;
              break;
            }
            if (name1 == "Подтаблица Куда входит")
            {
              typeNodeElement = Vedomost_VB_Static.TypeNodeElement_Shablona.MainTable;
              break;
            }
            if (name1 == "Основная надпись")
            {
              typeNodeElement = Vedomost_VB_Static.TypeNodeElement_Shablona.Pasport;
              break;
            }
            break;
        }
      }
    }
    Vedomost_VB_Static.description_TypeNodeElement(typeNodeElement);
    return typeNodeElement;
  }

  public static Vedomost_VB_Static.TypeNodeElement_Shablona Check_tableElement_Parent(
    DocumentTreeNode tableElement)
  {
    Vedomost_VB_Static.TypeNodeElement_Shablona nodeElementShablona = Vedomost_VB_Static.TypeNodeElement_Shablona.Undefined;
    int num = 0;
    if (tableElement.NodeClass == "TextBoxElement")
    {
      DocumentTreeNode documentTreeNode = tableElement.Parent;
      DocumentTreeNode parent;
      for (; documentTreeNode != null; documentTreeNode = parent)
      {
        ++num;
        parent = documentTreeNode.Parent;
        if (parent != null)
        {
          if (parent.Name == "Главная таблица")
          {
            nodeElementShablona = Vedomost_VB_Static.TypeNodeElement_Shablona.RecordMain;
            break;
          }
          if (parent.Name.StartsWith("Подтаблица"))
          {
            nodeElementShablona = Vedomost_VB_Static.TypeNodeElement_Shablona.RecordVtor;
            break;
          }
          if (parent.Name.StartsWith("Основная надпись"))
          {
            nodeElementShablona = Vedomost_VB_Static.TypeNodeElement_Shablona.Pasport;
            break;
          }
          if (parent.NodeTypeCaption == "Страница")
          {
            nodeElementShablona = Vedomost_VB_Static.TypeNodeElement_Shablona.Page;
            break;
          }
        }
        else
          break;
      }
    }
    return nodeElementShablona;
  }

