  /// <summary> Контроль Что такое поле имли имя есть </summary>
  /// <returns></returns>
  public static bool control_Douplication(
    Vedomost_VB.OneRecordXml oneRecordXml,
    Vedomost_VB.OneFieldXml oneFieldXml,
    string name,
    string tableRowId,
    bool check_tableRowId)
  {
    if (oneRecordXml == null || oneRecordXml._listOneFieldXml == null)
      return false;
    string text = "";
    bool flag1 = false;
    bool flag2 = false;
    for (int index = 0; index < oneRecordXml._listOneFieldXml.Count; ++index)
    {
      Vedomost_VB.OneFieldXml oneFieldXml1 = oneRecordXml._listOneFieldXml[index];
      if (oneFieldXml != oneFieldXml1)
      {
        if (oneFieldXml1._nameToFile == tableRowId)
          flag1 = true;
        if (oneFieldXml1._nameToXml == name)
          flag2 = true;
        if (flag1 & flag2)
          break;
      }
    }
    if (check_tableRowId && !string.IsNullOrEmpty(tableRowId) & flag1)
      text = $"Ячейка\r\n\"{tableRowId}\"\r\nуже используется в этой записи";
