    }
    if (string.IsNullOrEmpty(text))
      return true;
    int num = (int) MessageBox.Show(text, "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
    return false;
  }

  /// <summary> Занесение данных из файла AVS6 в СУЩЕСТВУЮЩИЙ doc_Template </summary>
  /// <param name="document"></param>
  /// <param name="vedomost_VB_new"></param>
  /// <param name="aVS6File"></param>
  /// <returns></returns>
  public static bool Filled_Data_From_Avs6File_To_Document(
    ImDocument document,
    Vedomost_VB _vedomost_VB_new,
    AVS6_File aVS6File)
  {
    if (document == null || aVS6File == null || _vedomost_VB_new == null || _vedomost_VB_new == null || _vedomost_VB_new._one_Ved_Nastr_RazrabatyvaemoiVed == null || _vedomost_VB_new._one_Ved_Nastr_RazrabatyvaemoiVed._algorithm_Avs6_To_Ips == null || Vedomost_VB_Static.Get_GuidTypeVed_ByObjTypeVed(document.DBObjectType) == Guid.Empty)
      return false;
    string attributeValue = document.GetAttributeValue("GroupForm", false);
    string str1 = "";
    string str2 = "Групповая форма документа IPS и файла AVS не совпадают\r\n\r\n";
    if (attributeValue == "B" && aVS6File.GroupForm != AVSDocumentForm.B)
    {
      str1 = str2 + "Документ IPS является групповым формы Б" + "\r\n";
      if (aVS6File.GroupForm == AVSDocumentForm.Single)
        str1 += "Документ AVS - единичный";
      if (aVS6File.GroupForm == AVSDocumentForm.A)
        str1 += "Документ AVS является групповым формы А";
    }
    if (attributeValue == "A" && aVS6File.GroupForm != AVSDocumentForm.A)
    {
      str1 = str2 + "Документ IPS является групповым формы А" + "\r\n";
      if (aVS6File.GroupForm == AVSDocumentForm.Single)
        str1 += "Документ AVS - единичный";
      if (aVS6File.GroupForm == AVSDocumentForm.A)
