  /// <summary> Для формы Б заполнение номеров исполнений </summary>
  /// <param name="document"></param>
  public static void FillProductHeadersOnPages(ImDocument document, AVS6_File aVS6File)
  {
    int index1 = 0;
    foreach (PageData pageData in (ImDocumentData) document)
    {
      DocumentTreeNode node1 = document.Nodes[index1];
      ++index1;
      string attributeValue = document.GetAttributeValue("_nameArticle", false);
      string nodeName1 = "Заголовок таблицы исполнений";
      if (pageData.FindFirstNodeByName(nodeName1) is TextData firstNodeByName1)
      {
        string str = firstNodeByName1.Text;
        if (string.IsNullOrEmpty(str))
          str = Vedomost_VB_Static.Kol_na_ispoln_Template;
        firstNodeByName1.AssignText(string.Format(str + " {0} -", (object) attributeValue), false, true, false, false, false);
      }
      string nodeName2 = "Номера исполнений";
      if (pageData.FindFirstNodeByName(nodeName2) is TableData firstNodeByName2)
      {
        int num = 0;
        if (aVS6File._pasport._listR2 != null)
          num = aVS6File._pasport._listR2.Count;
        if (num > 10)
          num = 10;
        for (int index2 = 0; index2 < num; ++index2)
        {
          if (firstNodeByName2.Nodes[index2] is TextData node2)
          {
            string str = aVS6File._pasport._listR2[index2].FieldSByType((byte) 22);
            node2.AssignText(str, false, true, false, false, false);
          }
        }
        pageData.UpdateLayout(true);
      }
    }
  }

