    string attributeValue5 = recordNew.FieldSByType((byte) 4);
    if (!string.IsNullOrEmpty(attributeValue5))
      docRowNew.SetAttributeValue("DesignationAvs6", attributeValue5);
    string attributeValue6 = recordNew.FieldSByType((byte) 5);
    if (!string.IsNullOrEmpty(attributeValue6))
