    if (!string.IsNullOrEmpty(recordNew.FieldSByType((byte) 105)) && recordNew._listR2 != null && recordNew._listR2.Count > 1 || recordNew._listR2 == null)
    {
      Vedomost_VB.OneRecord_Avs6_To_Ips recordAvs6ToIpsItogo = ipsByRecordNew._oneRecord_Avs6_To_Ips_Itogo;
