  /// <summary> Поиск соответствующего ObjctId среди объектов IPS</summary>
  /// <param name="recordNew"></param>
  /// <param name="Name_Required">Наименование обязательно</param>
  /// <param name="isImbase">В т.ч. Imbase</param>
  /// <returns></returns>
  public static long FindArticleID_By_RecordNew(
    RecordNew recordNew,
    bool Name_Required,
    bool isImbase)
  {
    if (recordNew == null)
      return -1;
    long articleIdByRecordNew = recordNew._articleID;
    switch (articleIdByRecordNew)
    {
      case -1:
      case 0:
        if (recordNew._recordType_Avs6 != 'I')
          return 0;
        if (!(ServicesManager.GetService(typeof (IArticleService)) is IArticleService))
          throw new Exception("Недоступен сервис ArticleService");
        string name = recordNew.FieldSByType((byte) 5);
        if (string.IsNullOrEmpty(name) & Name_Required)
          return -1;
        string designation = recordNew.FieldSByType((byte) 4);
        if (string.IsNullOrEmpty(designation))
          designation = recordNew.FieldSByType((byte) 100);
        string document = recordNew.FieldSByType((byte) 109);
        if (isImbase)
          articleIdByRecordNew = Vedomost_VB_Static.Create_ObjectId_By_Imbase(name, document, designation, Name_Required);
        return articleIdByRecordNew;
      default:
        return articleIdByRecordNew;
    }
  }

  /// <summary> Поиск существующего объекта </summary>
  /// <param name="name"> Наимнование </param>
  /// <param name="document">обозначение ДОКУМЕНТА отдельное, например "ГОСТ ХХХХХ"</param>
  /// <param name="designation">Обозначение</param>
  /// <param name="Name_Required"></param>
  /// <param name="isImbase">Искать В т.ч. Imbase (пока не используется)</param>
  /// <returns></returns>
  public static long Find_ObjectId_By_Name(
    string name,
    string document,
    string designation,
    bool Name_Required,
    bool isImbase)
  {
    if (string.IsNullOrEmpty(name) & Name_Required)
      return -1;
    if (Vedomost_VB_Static.artService == null)
    {
      Vedomost_VB_Static.artService = ServicesManager.GetService(typeof (IArticleService)) as IArticleService;
      if (Vedomost_VB_Static.artService == null)
        throw new Exception("Недоступен сервис ArticleService");
    }
    if (!string.IsNullOrEmpty(document) && document != designation && name.IndexOf(document) == -1)
      name = string.IsNullOrEmpty(name) ? document : $"{name} {document}";
    using (SessionKeeper sessionKeeper = new SessionKeeper())
      return Vedomost_VB_Static.artService.FindArticleID(designation, "", name, "", (object) sessionKeeper.Session);
  }

  /// <summary> Создание Объекта IPS по наименованию из IMBASE </summary>
  /// <param name="name"></param>
  /// <param name="document">обозначение ДОКУМЕНТА отдельное, например "ГОСТ ХХХХХ"</param>
  /// <param name="designation"></param>
  /// <param name="Name_Required">Наличие Наименования обязательно или нет </param>
  /// <returns></returns>
  public static long Create_ObjectId_By_Imbase(
    string name,
    string document,
    string designation,
    bool Name_Required)
  {
    if (string.IsNullOrEmpty(name) & Name_Required)
      return -1;
    long objectIdByName = Vedomost_VB_Static.Find_ObjectId_By_Name(name, document, designation, Name_Required, true);
    switch (objectIdByName)
    {
      case -1:
      case 0:
        if (!string.IsNullOrEmpty(document) && document != designation && name.IndexOf(document) == -1)
          name = $"{name} {document}";
        if (Vedomost_VB_Static.naimAttrId == 0 || Vedomost_VB_Static.naimAttrId == -1)
          Vedomost_VB_Static.naimAttrId = MetaDataHelper.GetAttributeTypeID("cad00020-306c-11d8-b4e9-00304f19f545");
        if (!string.IsNullOrEmpty(name))
        {
          using (SessionKeeper sessionKeeper = new SessionKeeper())
          {
            if (!(sessionKeeper.Session.GetCustomService(typeof (IImbaseIndexingService)) is IImbaseIndexingService customService1))
              throw new Exception("Недоступен сервис ImbaseIndexingService");
            DataTable dataTable = customService1.Search(sessionKeeper.Session.SessionGUID, (List<long>) null, Vedomost_VB_Static.naimAttrId, new string[2]
            {
              IndexesField.F_LINK_ID,
              IndexesField.F_TABKEY
            }, name, SearchesAccuracy.Exact);
            if (dataTable == null || dataTable.Rows.Count == 0)
            {
              dataTable = customService1.Search(sessionKeeper.Session.SessionGUID, (List<long>) null, Vedomost_VB_Static.naimAttrId, new string[2]
              {
                IndexesField.F_LINK_ID,
                IndexesField.F_TABKEY
              }, name, SearchesAccuracy.Start);
              if (dataTable == null || dataTable.Rows.Count == 0)
                dataTable = customService1.Search(sessionKeeper.Session.SessionGUID, (List<long>) null, Vedomost_VB_Static.naimAttrId, new string[2]
                {
                  IndexesField.F_LINK_ID,
                  IndexesField.F_TABKEY
                }, name, SearchesAccuracy.Сontain);
            }
            if (dataTable == null || dataTable.Rows.Count == 0)
              return objectIdByName;
            long int64_1 = Convert.ToInt64(dataTable.Rows[0][0]);
            long int64_2 = Convert.ToInt64(dataTable.Rows[0][1]);
            long int64_3 = Convert.ToInt64(dataTable.Rows[0][2]);
            if (!(sessionKeeper.Session.GetCustomService(typeof (IImbaseServer)) is IImbaseServer customService2))
              throw new Exception("Сервис не найден!");
            objectIdByName = customService2.CreateObject(sessionKeeper.Session.SessionGUID, int64_3, int64_1, int64_2, true, -1);
          }
        }
        return objectIdByName;
      default:
        return objectIdByName;
    }
  }

  /// <summary> Заполнение одной ГРАФЫ </summary>
  /// <param name="docRowNew"></param>
  /// <param name="oneGrafa_Avs6_To_Ips"></param>
  /// <param name="recordNew"></param>
  /// <returns></returns>
  public static bool Filled_OneGrafa_Avs6_To_Ips(
    TableData docRowNew,
    Vedomost_VB.OneGrafa_Avs6_To_Ips oneGrafa_Avs6_To_Ips,
    RecordNew recordNew)
  {
    if (docRowNew == null || oneGrafa_Avs6_To_Ips == null || recordNew == null)
      return false;
    string fieldName = oneGrafa_Avs6_To_Ips._cell_ID;
    if (string.IsNullOrEmpty(fieldName))
      return false;
    string fieldValue = "";
    bool ips = false;
    if (oneGrafa_Avs6_To_Ips._cell_ID == "Количество 0" && recordNew._listR2 != null && recordNew._listR2.Count > 0)
    {
      for (int index = 0; index < 10 && index < recordNew._listR2.Count; ++index)
      {
        fieldValue = recordNew._listR2[index].FieldSByType((byte) 6);
        if (!string.IsNullOrEmpty(fieldValue))
        {
          fieldName = "Количество " + index.ToString();
          if (Vedomost_VB_Static.Set_dateToDocRow(docRowNew, fieldName, fieldValue))
            ips = true;
        }
      }
    }
    else
    {
      Vedomost_VB.OneDataField_Avs6_To_Ips dataFieldAvs6ToIps = (Vedomost_VB.OneDataField_Avs6_To_Ips) null;
      for (int index = 0; index < oneGrafa_Avs6_To_Ips._listOneDataField_Avs6_To_Ips.Count; ++index)
      {
        dataFieldAvs6ToIps = oneGrafa_Avs6_To_Ips._listOneDataField_Avs6_To_Ips[index];
        string str = recordNew.FieldSByType((byte) dataFieldAvs6ToIps._objectType);
        if (!string.IsNullOrEmpty(str))
        {
          if (fieldValue != "")
            fieldValue += dataFieldAvs6ToIps._symbolRazd;
          fieldValue += str;
        }
      }
      if (string.IsNullOrEmpty(fieldValue) && recordNew._listR2 != null && recordNew._listR2.Count == 1)
      {
        string str = recordNew._listR2[0].FieldSByType((byte) dataFieldAvs6ToIps._objectType);
        if (!string.IsNullOrEmpty(str))
          fieldValue = str;
      }
    }
    if (!string.IsNullOrEmpty(fieldValue) && Vedomost_VB_Static.Set_dateToDocRow(docRowNew, fieldName, fieldValue))
      ips = true;
    return ips;
  }

