  /// <summary> Чтение основных данных из ДОКУМЕНТА, например "Обозначение изделия", "Наименование документа"</summary>
  /// <param name="document"></param>
  /// <param name="fieldName"></param>
  /// <returns></returns>
  public static string Get_DateFromDocument(ImDocument document, string fieldName)
  {
    string dateFromDocument = "";
    DocumentTreeNode firstNodeByName = (document.Nodes[0] as PageData).FindFirstNodeByName(fieldName);
    if (firstNodeByName != null && firstNodeByName.TypeNameForXml == "TextBoxElement")
    {
      TextBoxElement textBoxElement = (TextBoxElement) firstNodeByName;
      if (textBoxElement != null)
        dateFromDocument = textBoxElement.Text;
    }
    return dateFromDocument;
  }

  /// <summary> Поиск, например, в СТРОКЕ </summary>
  /// <param name="treeNodeIn"></param>
  /// <param name="fieldName"></param>
  /// <returns></returns>
  public static string Get_DateFrom_TreeNode(DocumentTreeNode treeNodeIn, string fieldName)
  {
    string dateFromTreeNode = "";
    treeNodeIn.FindFirstNodeByName(fieldName);
    TextBoxElement firstNodeByName = (TextBoxElement) treeNodeIn.FindFirstNodeByName(fieldName);
    if (firstNodeByName != null)
      dateFromTreeNode = firstNodeByName.Text;
    return dateFromTreeNode;
  }

  /// <summary> Занесение ОДНОГО ПОЛЯ (ГРАФЫ) в запись </summary>
  /// <param name="docRowNew"></param>
  /// <param name="fieldName">Имя ЯЧЕЙКИ</param>
  /// <param name="fieldValue"></param>
  /// <returns></returns>
  public static bool Set_dateToDocRow(TableData docRowNew, string fieldName, string fieldValue)
  {
    TextData firstNodeByName = (TextData) docRowNew.FindFirstNodeByName(fieldName);
    if (firstNodeByName == null)
      return false;
    firstNodeByName.AssignText(fieldValue, false, false, false);
    return true;
  }

  /// <summary> Замена одного ПОЛЯ в ДОКУМЕНТЕ </summary>
  /// <param name="document"></param>
  /// <param name="fieldName"></param>
  /// <param name="fieldValue"></param>
  public static void Set_dateToDocument(ImDocument document, string fieldName, string fieldValue)
  {
    DocumentTreeNode firstNodeByName = (document.Nodes[0] as PageData).FindFirstNodeByName(fieldName);
    if (firstNodeByName == null || !(firstNodeByName.TypeNameForXml == "TextBoxElement"))
