  /// <summary> Конвертация Единичной в А </summary>
  /// <param name="document"></param>
  public static void Convert_Ed_A(ImDocument document)
  {
    if (document == null || document.NodesCount < 1)
      return;
    document.SetAttributeValue("GroupForm", "A");
    document.SetAttributeValue("VariablesCount", "1");
  }

  /// <summary> Конвертация формы А в Единичную </summary>
  /// <param name="document"></param>
  public static void Convert_A_Ed(ImDocument document)
  {
    if (document == null || document.NodesCount < 1)
      return;
    string str = "";
    string s = document.GetAttributeValue("VariablesCount", true);
    if (s == "")
      s = "0";
    int num = int.Parse(s);
    document.SetAttributeValue("GroupForm", "Ed");
    for (int index = 0; index < num; ++index)
    {
      string attributeName1 = "Variable_" + index.ToString();
      if (index == 0)
        str = document.GetAttributeValue(attributeName1, false);
      document.RemoveAttribute(attributeName1, false, false);
      string attributeName2 = "ProductInfoID_" + index.ToString();
      document.RemoveAttribute(attributeName2, false, false);
      string attributeName3 = "Caption_" + index.ToString();
      document.RemoveAttribute(attributeName3, false, false);
    }
    document.RemoveAttribute("VariablesCount", false, false);
    int index1 = document.NodesCount - 1;
    while (index1 >= 0 && index1 < document.NodesCount)
    {
      DocumentTreeNode node1 = document.Nodes[index1];
      if (node1.NodeClass != "Page")
        --index1;
      else if (node1.Id == "LRI" || node1.Id == "Лист регистрации изменений")
      {
        --index1;
      }
      else
      {
        string nodeTemplateId = "Главная таблица";
        if (index1 > 0)
          nodeTemplateId += " 2";
        if (!(node1.FindFirstNodeFromTemplate_Recursive(nodeTemplateId) is TableData templateRecursive) || templateRecursive.NodesCount < 1)
          return;
        int index2 = templateRecursive.NodesCount - 1;
        while (index2 >= 0 && index2 < templateRecursive.NodesCount)
        {
          if (!(templateRecursive.Nodes[index2].NodeClass != "TableElement"))
          {
            TableData node2 = (TableData) templateRecursive.Nodes[index2];
            string attributeValue1 = node2.GetAttributeValue("TypeRec", false);
            string attributeValue2 = node2.GetAttributeValue("Variable", false);
            string attributeValue3 = node2.GetAttributeValue("TypeRow", false);
            if (attributeValue1 == "TitleVar" || attributeValue1 == "TitleIsp" || attributeValue1 == "RemarkShort")
            {
              node2.Remove(false, false);
              --index2;
            }
            else if (attributeValue3 == "TitleVar" || attributeValue3 == "TitleIsp" || attributeValue3 == "RemarkShort")
            {
              node2.Remove(false, false);
              --index2;
            }
            else if (string.IsNullOrEmpty(attributeValue2))
              --index2;
            else if (attributeValue2 == str)
            {
              node2.RemoveAttribute(attributeValue2, false, false);
              node2.RemoveAttribute("Variable", false, false);
              --index2;
            }
            else
            {
              node2.Remove(false, false);
              --index2;
            }
          }
        }
        --index1;
      }
    }
    document.UpdateLayout(true);
  }

  /// <summary> Конвертация Единичной в Б </summary>
  /// <param name="document"></param>
  public static void Convert_Ed_B(ImDocument document, bool quet = false)
  {
    if (document == null || document.NodesCount < 1)
      return;
    Guid objectTypeGuid = MetaDataHelper.GetObjectTypeGuid(AVSPlugin.Instance.ActiveImDocumentEditorForm.DocumentType);
    if (objectTypeGuid == Guid.Empty)
      return;
    Guid vedomostyByObjTypeVed = Vedomost_VB_Static.Get_GuidTemplateVedomosty_ByObjTypeVed(AVSPlugin.Instance.ActiveImDocumentEditorForm.DocumentType, "B");
    if (vedomostyByObjTypeVed == Guid.Empty)
      return;
    Vedomost_VB vedomostVb = Vedomost_VB_Static.ReBuilding_vedomost_VB(document, vedomostyByObjTypeVed, objectTypeGuid, false, false);
    if (vedomostVb == null)
      return;
    vedomostVb._listAll_IspolneniySp_prodInfo = new List<ProductInfo>();
    if (vedomostVb._prodInfo != null)
      vedomostVb._listAll_IspolneniySp_prodInfo.Add(vedomostVb._prodInfo);
    vedomostVb.List_For_Isp = new List<Vedomost_VB.RecordForVed_For_Isp>();
    vedomostVb.List_For_Isp.Add(new Vedomost_VB.RecordForVed_For_Isp()
    {
      Ispolnenie = vedomostVb._prodInfo == null || string.IsNullOrEmpty(vedomostVb._prodInfo.Designation) ? vedomostVb.DesignationArticle : vedomostVb._prodInfo.Designation,
      Ispolnenie_Zagol = "-"
    });
    vedomostVb.ConvertGrAToGrB(false);
    vedomostVb._groupForm = Vedomost_VB.FormaGroup.B;
    vedomostVb._guidTemplateDoc = vedomostyByObjTypeVed;
    vedomostVb._one_Ved_Nastr_RazrabatyvaemoiVed = Vedomost_VB_Static.Read_One_Ved_Nastr_byDocTemplateGuid(vedomostyByObjTypeVed, objectTypeGuid, Vedomost_VB.TypeDoc.Ved);
    vedomostVb.ListCommonId_Filled(vedomostVb.listCommonId);
    vedomostVb.Create_Ved_Zagol_PoPriznaku();
    if (quet)
      return;
    vedomostVb.CreateAndOpenNewDocument(true, false, true);
  }

  /// <summary> Конвертация А в Б </summary>
  /// <param name="document"></param>
  public static void Convert_A_B(ImDocument document)
  {
    if (document == null || document.NodesCount < 1)
      return;
    Guid objectTypeGuid = MetaDataHelper.GetObjectTypeGuid(AVSPlugin.Instance.ActiveImDocumentEditorForm.DocumentType);
    Guid vedomostyByObjTypeVed = Vedomost_VB_Static.Get_GuidTemplateVedomosty_ByObjTypeVed(AVSPlugin.Instance.ActiveImDocumentEditorForm.DocumentType, "B");
    if (vedomostyByObjTypeVed == Guid.Empty)
      return;
    Vedomost_VB vedomostVb = Vedomost_VB_Static.ReBuilding_vedomost_VB(document, vedomostyByObjTypeVed, objectTypeGuid, true, false);
    if (vedomostVb == null)
      return;
    vedomostVb._listAll_IspolneniySp_prodInfo = new List<ProductInfo>();
    vedomostVb._listAll_IspolneniySp_prodInfo.Add(vedomostVb._prodInfo);
    Vedomost_VB.Variables_Coordination variables_Coordination = (Vedomost_VB.Variables_Coordination) null;
    Vedomost_VB_Static.Create_Variables_Coordination_From_Document(document, out variables_Coordination);
    if (variables_Coordination == null)
      return;
    vedomostVb.List_For_Isp = new List<Vedomost_VB.RecordForVed_For_Isp>();
    for (int index = 0; index < variables_Coordination.list_Variables.Count; ++index)
      vedomostVb.List_For_Isp.Add(new Vedomost_VB.RecordForVed_For_Isp()
      {
        Ispolnenie = variables_Coordination.list_Variables[index],
        Ispolnenie_Zagol = variables_Coordination.list_Captions[index]
      });
    vedomostVb.ConvertGrAToGrB(false);
    vedomostVb._groupForm = Vedomost_VB.FormaGroup.B;
    vedomostVb._guidTemplateDoc = vedomostyByObjTypeVed;
    vedomostVb._one_Ved_Nastr_RazrabatyvaemoiVed = Vedomost_VB_Static.Read_One_Ved_Nastr_byDocTemplateGuid(vedomostyByObjTypeVed, objectTypeGuid, Vedomost_VB.TypeDoc.Ved);
    vedomostVb.ListCommonId_Filled(vedomostVb.listCommonId);
    vedomostVb.Create_Ved_Zagol_PoPriznaku();
    vedomostVb.CreateAndOpenNewDocument(true, true, true);
  }

