  /// <summary>  Получить техт из графы с именем nameGrafa //</summary>
  /// <param name="docRow"></param>
  /// <param name="nameGrafa"></param>
  /// <returns></returns>
  public static string Get_Text_From_Grafa(TableData docRow, string nameGrafa)
  {
    if (docRow == null)
      return "";
    for (int index = 0; index < docRow.NodesCount; ++index)
    {
      DocumentTreeNode node = docRow.Nodes[index];
      if (node.NodeClass == "TextBoxElement")
      {
        TextData textData = (TextData) node;
        if (textData == null)
          return "";
        if (textData.Name == nameGrafa)
          return textData.Text;
      }
    }
    return "";
  }

  /// <summary> Заполнение записи, если она состоит из одног поля </summary>
  /// <param name="document"></param>
  /// <param name="oneRecordToPrint"></param>
  /// <param name="text">Текст этого единственного поля</param>
  /// <param name="typeRow">Тип строки</param>
  /// <param name="variable">Исполнение (для формы А)</param>
  /// <returns></returns>
  public static TableData Create_DocRow(
    ImDocument document,
    Vedomost_VB.OneRecordToPrint oneRecordToPrint,
    string text,
    string typeRow,
    string variable)
  {
    if (document == null || oneRecordToPrint == null || string.IsNullOrEmpty(text) || string.IsNullOrEmpty(typeRow))
      return (TableData) null;
    if (oneRecordToPrint._listOneGrafaToPrint == null || oneRecordToPrint._listOneGrafaToPrint.Count != 1)
      return (TableData) null;
    Vedomost_VB.OneGrafaToPrint oneGrafaToPrint = oneRecordToPrint._listOneGrafaToPrint[0];
    TableData docRow = (TableData) null;
    TableData node1 = (document.DocumentTemplate as ImDocument).FindNode(oneRecordToPrint._tableRowId.ToString()) as TableData;
    TextData textData = (TextData) null;
    if (node1 != null)
    {
      docRow = node1.CloneFromTemplate() as TableData;
      for (int index = 0; index < docRow.NodesCount; ++index)
      {
        DocumentTreeNode node2 = docRow.Nodes[index];
        if (node2.Id == oneGrafaToPrint._cell_ID)
        {
          textData = (TextData) node2;
          break;
        }
      }
      textData?.AssignText(text, false, false, false);
      docRow.SetAttributeValue("TypeRow", typeRow);
      docRow.SetAttributeValue("TypeRec", typeRow);
      docRow.SetAttributeValue("From", "Edit");
      if (!string.IsNullOrEmpty(variable))
        docRow.SetAttributeValue("Variable", variable);
    }
    return docRow;
  }

