  /// <summary> Создание коллекции строк - шаблонов из какого то исполнения </summary>
  /// <param name="document"></param>
  /// <param name="variable_old"></param>
  /// <param name="variable_new"></param>
  /// <returns></returns>
  public static List<TableData> Copy_Variable_A(
    ImDocument document,
    string variable_old,
    string variable_new)
  {
    if (document == null)
      return (List<TableData>) null;
    if (string.IsNullOrEmpty(variable_new))
      return (List<TableData>) null;
    List<TableData> tableDataList = new List<TableData>();
    for (int index1 = 0; index1 < document.NodesCount; ++index1)
    {
      TableData firstNodeByName = (TableData) (document.Nodes[index1] as PageData).FindFirstNodeByName("Главная таблица");
      if (firstNodeByName != null)
      {
        for (int index2 = 0; index2 < firstNodeByName.NodesCount; ++index2)
        {
          DocumentTreeNode node = firstNodeByName.Nodes[index2];
          if (node != null)
          {
            string attributeValue1 = node.GetAttributeValue("TypeRow", true);
            if (!string.IsNullOrEmpty(attributeValue1) && !(attributeValue1 == "TitleIsp") && !(attributeValue1 == "TitleVar"))
            {
              string attributeValue2 = node.GetAttributeValue("Variable", true);
              if ((string.IsNullOrEmpty(variable_old) && string.IsNullOrEmpty(attributeValue2) || variable_old == attributeValue2) && node.Clone(true, true) is TableData tableData)
              {
                tableData.SetAttributeValue("Variable", variable_new);
                tableDataList.Add(tableData);
              }
            }
          }
        }
      }
    }
    return tableDataList;
  }

  /// <summary> Возвращает для формы Б список по страницам НОМЕР первого исполнения и Номер последнего на странице </summary>
  /// <param name="document"></param>
  /// <returns></returns>
  public static List<Vedomost_VB_Static.Trio_Int> list_onePage_VariablesB_Create(
    ImDocument document,
    Vedomost_VB vedomost_VB,
    One_Ved_Nastr one_Ved_Nastr_RazrabatyvaemoiVed)
  {
    List<Vedomost_VB_Static.Trio_Int> trioIntList = new List<Vedomost_VB_Static.Trio_Int>();
    if (document == null)
      return trioIntList;
    int index = -1;
    int num1 = 0;
    Math.Ceiling((double) vedomost_VB._variables_Coordination.list_Variables.Count / (double) one_Ved_Nastr_RazrabatyvaemoiVed._algorithmToPrint_B._kolGraf);
    foreach (PageData pageData in (ImDocumentData) document)
    {
      ++index;
      PageData node1 = document.Nodes[index] as PageData;
      if (!(node1.NodeClass != "Page") && !(node1.Id == "LRI") && !(node1.Id == "Лист регистрации изменений"))
      {
        string nodeName = "Номера исполнений";
        if (pageData.FindFirstNodeByName(nodeName) is TableData firstNodeByName)
        {
          Vedomost_VB_Static.Trio_Int trioInt = new Vedomost_VB_Static.Trio_Int();
          trioInt._cikl = num1;
          string caption = "";
          int num2 = 0;
          foreach (TextData node2 in firstNodeByName.Nodes)
          {
            string text = node2.Text;
            if (num2 == 0 && !string.IsNullOrEmpty(text))
            {
              num1 = vedomost_VB._variables_Coordination.I_Variable_By_Caption(text) / one_Ved_Nastr_RazrabatyvaemoiVed._algorithmToPrint_B._kolGraf;
              trioInt._cikl = num1;
              trioInt._Caption_Begin = text;
              trioInt._i_Begin = vedomost_VB._variables_Coordination.I_Variable_By_Caption(text);
            }
            if (num2 == one_Ved_Nastr_RazrabatyvaemoiVed._algorithmToPrint_B._kolGraf - 1 && !string.IsNullOrEmpty(text))
            {
              num1 = vedomost_VB._variables_Coordination.I_Variable_By_Caption(text) / one_Ved_Nastr_RazrabatyvaemoiVed._algorithmToPrint_B._kolGraf;
              trioInt._Caption_End = text;
              trioInt._i_End = vedomost_VB._variables_Coordination.I_Variable_By_Caption(text);
              break;
            }
            if (string.IsNullOrEmpty(text))
            {
              if (num2 != 0)
              {
                trioInt._Caption_End = caption;
                trioInt._i_End = vedomost_VB._variables_Coordination.I_Variable_By_Caption(caption);
                break;
              }
              break;
            }
            caption = text;
            ++num2;
          }
          if (trioInt._i_Begin > -1)
            trioIntList.Add(trioInt);
        }
      }
    }
    return trioIntList;
  }

  /// <summary> Получить номер цикла по странице </summary>
  /// <param name="pageData"></param>
  /// <param name="_variables_Coordination"></param>
  /// <param name="one_Ved_Nastr_RazrabatyvaemoiVed"></param>
  /// <returns></returns>
  public static int I_CiklB_By_Page(
    PageData pageData,
    Vedomost_VB.Variables_Coordination _variables_Coordination,
    One_Ved_Nastr one_Ved_Nastr_RazrabatyvaemoiVed)
  {
    string nodeName = "Номера исполнений";
    if (!(pageData.FindFirstNodeByName(nodeName) is TableData firstNodeByName))
      return -1;
    string text = ((TextData) firstNodeByName.Nodes[0]).Text;
    return _variables_Coordination.I_Variable_By_Caption(text) / one_Ved_Nastr_RazrabatyvaemoiVed._algorithmToPrint_B._kolGraf;
  }

  /// <summary> Занесение в ДОКУМЕНТ исполнения </summary>
  /// <param name="document"></param>
  /// <param name="variables_Coordination"></param>
  public static void SetAttributeValue_Variable(
    ImDocument document,
    Vedomost_VB.Variables_Coordination variables_Coordination)
  {
    if (document == null || variables_Coordination == null || variables_Coordination.list_Variables == null || variables_Coordination.list_Variables.Count == 0)
      return;
    int count = variables_Coordination.list_Variables.Count;
    string listVariable = variables_Coordination.list_Variables[count - 1];
    string listCaption = variables_Coordination.list_Captions[count - 1];
    document.SetAttributeValue("VariablesCount", count.ToString());
    document.SetAttributeValue("Variable_" + (count - 1).ToString(), listVariable);
    document.SetAttributeValue("Caption_" + (count - 1).ToString(), listCaption);
  }

  /// <summary> Обработка после диалога "Список исполнений" (Форма А) </summary>
  /// <param name="document"></param>
  /// <param name="variables_Coordination"></param>
  /// <param name="variables"></param>
  public static void Processing_Group_A(
    ImDocument document,
    Vedomost_VB.Variables_Coordination variables_Coordination,
    Vedomost_VB.Variables_for_VariableDialog variables,
    Vedomost_VB vedomost_VB_new,
    ImDocument docTemplate,
    string name_Page_Current)
  {
    if (document == null || variables_Coordination == null || variables == null || variables_Coordination.list_Variables == null || variables_Coordination.list_Variables.Count == 0 || variables_Coordination.list_Captions == null || variables_Coordination.list_Captions.Count == 0 || variables_Coordination.list_Variables.Count != variables_Coordination.list_Captions.Count || variables.list_Variables == null || variables.list_Variables.Count == 0)
      return;
    Vedomost_VB_Static.All_Variable_Delete_A(document, variables_Coordination, variables);
    Vedomost_VB_Static.All_Variable_Rename_A(document, variables_Coordination, variables);
    Vedomost_VB_Static.All_Variable_Add_A(document, variables_Coordination, variables, vedomost_VB_new, docTemplate, name_Page_Current);
  }

  /// <summary> УДАЛЕНИЕ ИСПОЛНЕНИЙ, помеченных для удаления </summary>
  /// <param name="document"></param>
  /// <param name="variables_Coordination"></param>
  /// <param name="variables"></param>
  /// <returns></returns>
  public static bool All_Variable_Delete_A(
    ImDocument document,
    Vedomost_VB.Variables_Coordination variables_Coordination,
    Vedomost_VB.Variables_for_VariableDialog variables)
  {
    if (document == null || variables_Coordination == null || variables_Coordination.list_Variables == null || variables_Coordination.list_Variables.Count == 0 || variables_Coordination.list_Captions == null || variables_Coordination.list_Captions.Count == 0 || variables_Coordination.list_Variables.Count != variables_Coordination.list_Captions.Count)
      return false;
    for (int index1 = variables.list_Variables.Count - 1; index1 >= 0; --index1)
    {
      Vedomost_VB.One_Variable_for_VariableDialog listVariable = variables.list_Variables[index1];
      if (listVariable._isDeleted)
      {
        string variable = listVariable._variable;
        if (Vedomost_VB_Static.One_Variable_Delete_A(document, variables_Coordination, variable))
        {
          for (int index2 = variables_Coordination.list_Variables.Count - 1; index2 >= 0; --index2)
          {
            if (variables_Coordination.list_Variables[index2] == variable)
            {
              string attributeName1 = "Variable_" + index1.ToString();
              document.RemoveAttribute(attributeName1, false, false);
              string attributeName2 = "ProductInfoID_" + index1.ToString();
              document.RemoveAttribute(attributeName2, false, false);
              string attributeName3 = "Caption_" + index1.ToString();
              document.RemoveAttribute(attributeName3, false, false);
              variables_Coordination.list_Variables.RemoveAt(index2);
              variables_Coordination.list_Captions.RemoveAt(index2);
            }
