  public static bool One_Variable_Delete_A(
    ImDocument document,
    Vedomost_VB.Variables_Coordination variables_Coordination,
    string variable_delete)
  {
    if (document == null || variables_Coordination == null || string.IsNullOrEmpty(variable_delete) || variables_Coordination.list_Variables == null || variables_Coordination.list_Variables.Count == 0 || variables_Coordination.list_Captions == null || variables_Coordination.list_Captions.Count == 0 || variables_Coordination.list_Variables.Count != variables_Coordination.list_Captions.Count)
      return false;
    int index1 = document.NodesCount - 1;
    while (index1 >= 0)
    {
      DocumentTreeNode node1 = document.Nodes[index1];
      if (node1.NodeClass != "Page")
        --index1;
      else if (node1.Id == "LRI" || node1.Id == "Лист регистрации изменений")
      {
        --index1;
      }
      else
      {
        string nodeTemplateId = "Главная таблица";
        if (index1 > 0)
          nodeTemplateId += " 2";
        if (!(node1.FindFirstNodeFromTemplate_Recursive(nodeTemplateId) is TableData templateRecursive))
        {
          --index1;
