        else
        {
          int index2 = templateRecursive.NodesCount - 1;
          while (index2 >= 0 && index2 < templateRecursive.Nodes.Count)
          {
            if (templateRecursive.Nodes[index2].NodeClass != "TableElement")
            {
              --index2;
            }
            else
            {
              TableData node2 = (TableData) templateRecursive.Nodes[index2];
