  /// <summary> Добавление исполнений </summary>
  /// <param name="document"></param>
  /// <param name="variables_Coordination"></param>
  /// <param name="variables"></param>
  /// <returns></returns>
  public static bool All_Variable_Add_A(
    ImDocument document,
    Vedomost_VB.Variables_Coordination variables_Coordination,
    Vedomost_VB.Variables_for_VariableDialog variables,
    Vedomost_VB vedomost_VB_new,
    ImDocument docTemplate,
    string name_Page_Current)
  {
    if (document == null || variables_Coordination == null || variables_Coordination.list_Variables == null || variables_Coordination.list_Variables.Count == 0 || variables_Coordination.list_Captions == null || variables_Coordination.list_Captions.Count == 0 || variables_Coordination.list_Variables.Count != variables_Coordination.list_Captions.Count)
      return false;
    bool update = false;
    int num = 0;
    for (int index = variables.list_Variables.Count - 1; index >= 0; --index)
    {
      if (variables.list_Variables[index]._isNew)
      {
        num = index;
        break;
      }
    }
    for (int index = 0; index < variables.list_Variables.Count; ++index)
    {
      Vedomost_VB.One_Variable_for_VariableDialog listVariable = variables.list_Variables[index];
      if (listVariable._isNew)
      {
        if (index == num)
          update = true;
        Vedomost_VB.One_Variable_for_VariableDialog variable_New = listVariable;
        if (Vedomost_VB_Static.One_Variable_Add_A(document, variables_Coordination, variable_New, vedomost_VB_new, docTemplate, update, name_Page_Current))
        {
          string attributeName1 = "Variable_" + index.ToString();
          string variable = variable_New._variable;
          document.SetAttributeValue(attributeName1, variable);
          string attributeName2 = "Caption_" + index.ToString();
          string caption = variable_New._caption;
          document.SetAttributeValue(attributeName2, caption);
        }
      }
    }
    int count = variables_Coordination.list_Variables.Count;
    document.SetAttributeValue("VariablesCount", variables_Coordination.list_Variables.Count.ToString());
    return true;
  }

  /// <summary> Добавление одного исполнения в форме А </summary>
  /// <param name="document"></param>
  /// <param name="variables_Coordination"></param>
  /// <param name="variable_New"></param>
  /// <param name="vedomost_VB_new"></param>
  /// <param name="docTemplate"></param>
  /// <param name="update"></param>
  /// <returns></returns>
  public static bool One_Variable_Add_A(
    ImDocument document,
    Vedomost_VB.Variables_Coordination variables_Coordination,
    Vedomost_VB.One_Variable_for_VariableDialog variable_New,
    Vedomost_VB vedomost_VB_new,
    ImDocument docTemplate,
    bool update,
    string name_Page_Current)
  {
    if (document == null || variables_Coordination == null || variable_New == null || variables_Coordination.list_Variables == null || variables_Coordination.list_Variables.Count == 0 || variables_Coordination.list_Captions == null || variables_Coordination.list_Captions.Count == 0 || variables_Coordination.list_Variables.Count != variables_Coordination.list_Captions.Count)
      return false;
    string listVariable = variables_Coordination.list_Variables[variables_Coordination.list_Variables.Count - 1];
    DocumentTreeNode endInfoPage = Vedomost_VB_Static.FindEndInfoPage(document);
    if (endInfoPage == null)
      return true;
    TableData endMainTable1 = Vedomost_VB_Static.FindEndMainTable(document);
    string name = endInfoPage.Name;
    if (endMainTable1 != null)
    {
      TableData docRow = Vedomost_VB_Static.Create_DocRow(document, vedomost_VB_new._one_Ved_Nastr_RazrabatyvaemoiVed._algorithmToPrint._oneRecordToPrintTitleIsp, variable_New._variable, "TitleIsp", variable_New._variable);
      if (docRow != null)
      {
        TableData docRowEmpty = vedomost_VB_new.Create_DocRow_Empty(docTemplate, listVariable, name);
        endMainTable1.AddChildNode((DocumentTreeNode) docRowEmpty, false, false);
        if (update && variable_New.one_Variable_For_VariableDialog_Template == null)
          endMainTable1.AddChildNode((DocumentTreeNode) docRow, true, true);
        else
          endMainTable1.AddChildNode((DocumentTreeNode) docRow, false, false);
        variables_Coordination.Add_Variable_WithCaption(variable_New._variable, variable_New._caption);
        Vedomost_VB_Static.SetAttributeValue_Variable(document, variables_Coordination);
        if (variable_New.one_Variable_For_VariableDialog_Template != null && !string.IsNullOrEmpty(variable_New.one_Variable_For_VariableDialog_Template._variable))
        {
          List<TableData> tableDataList = Vedomost_VB_Static.Copy_Variable_A(document, variable_New.one_Variable_For_VariableDialog_Template._variable, variable_New._variable);
          if (tableDataList != null)
          {
            TableData endMainTable2 = Vedomost_VB_Static.FindEndMainTable(document);
            for (int index = 0; index < tableDataList.Count; ++index)
            {
              TableData child = tableDataList[index];
              if (index == tableDataList.Count - 1)
                endMainTable2.AddChildNode((DocumentTreeNode) child, update, update);
              else
                endMainTable2.AddChildNode((DocumentTreeNode) child, false, false);
            }
          }
        }
        if (update)
          document.documentControl.SetSelection((DocumentTreeNode) docRow, true, false);
      }
    }
    return true;
  }

