  /// <summary> Получить Главную таблицу на странице pageNumber </summary>
  /// <param name="document"></param>
  /// <param name="pageNumber"></param>
  /// <returns></returns>
  public static TableData Get_MainTable_From_PageNumber(ImDocument document, int pageNumber)
  {
    if (document == null)
      return (TableData) null;
    if (pageNumber < 0 || pageNumber >= document.NodesCount)
      return (TableData) null;
    DocumentTreeNode node = document.Nodes[pageNumber];
    if (node.NodeClass != "Page")
      return (TableData) null;
    string nodeName = "Главная таблица";
    return node.FindFirstNodeByName(nodeName) as TableData;
  }

  /// <summary> Получить docRow с номером iRow на странице pageNumber </summary>
  /// <param name="document"></param>
  /// <param name="pageNumber"></param>
  /// <param name="iRow"></param>
  /// <returns></returns>
  public static TableData Get_DocRow_From_PageNumber(ImDocument document, int pageNumber, int iRow)
  {
    if (document == null)
      return (TableData) null;
    if (pageNumber < 0 || pageNumber >= document.NodesCount)
      return (TableData) null;
    if (iRow < 0)
      return (TableData) null;
    TableData tableFromPageNumber = Vedomost_VB_Static.Get_MainTable_From_PageNumber(document, pageNumber);
    if (tableFromPageNumber == null || tableFromPageNumber.NodesCount == 0)
      return (TableData) null;
    return iRow >= tableFromPageNumber.NodesCount ? (TableData) null : tableFromPageNumber.Nodes[iRow] as TableData;
  }

