  /// <summary> Занесение Атрибута в запись </summary>
  /// <param name="docRow"></param>
  /// <param name="nameAttribut"></param>
  /// <param name="text_New"></param>
  public static void Change_In_DocRow_Attribute(
    TableData docRow,
    string nameAttribut,
    string text_New)
  {
    docRow.RemoveAttribute(nameAttribut, false, false);
    docRow.SetAttributeValue(nameAttribut, text_New, false);
  }

  /// <summary> Замена Атрибутов в записи </summary>
  /// <param name="docRow"></param>
  /// <param name="text_Old"></param>
  /// <param name="text_New"></param>
  public static void Change_In_DocRow_AttributeS(
    TableData docRow,
    string text_Old,
    string text_New)
  {
    Dictionary<string, object> attributes = new Dictionary<string, object>();
    docRow.GetAttributes((IDictionary) attributes, false);
    foreach (KeyValuePair<string, object> keyValuePair in attributes)
    {
      string key = keyValuePair.Key;
      if (Convert.ToString(keyValuePair.Value) == text_Old)
        docRow.SetAttributeValue(key, text_New, false);
    }
  }

  /// <summary> Замена Атрибутов в ДОКУМЕНТЕ </summary>
  /// <param name="document"></param>
  /// <param name="text_Old"></param>
  /// <param name="text_New"></param>
  public static void Change_In_Document_AttributeS(
    ImDocument document,
    string text_Old,
    string text_New)
  {
    Dictionary<string, object> attributes = new Dictionary<string, object>();
    document.GetAttributes((IDictionary) attributes, false);
    foreach (KeyValuePair<string, object> keyValuePair in attributes)
    {
      string key = keyValuePair.Key;
      if (Convert.ToString(keyValuePair.Value) == text_Old)
        document.SetAttributeValue(key, text_New, false);
    }
  }

  /// <summary> Замена в графе записи документа </summary>
  /// <param name="docRow"></param>
  /// <param name="text_Old"></param>
  /// <param name="text_New"></param>
  public static void Change_In_DocRow_Field(TableData docRow, string text_Old, string text_New)
  {
    for (int index = 0; index < docRow.NodesCount; ++index)
    {
      DocumentTreeNode node = docRow.Nodes[index];
