  /// <summary> Вывод расположения исполнений формы Б </summary>
  /// <param name="document"></param>
  public static void FilledNumbersIspolneniyFormaB(ImDocument document)
  {
    if (document == null)
      return;
    string attributeValue1 = document.GetAttributeValue("GroupForm", true);
    if (string.IsNullOrEmpty(attributeValue1) || attributeValue1 != "B")
      return;
    string attributeValue2 = document.GetAttributeValue("VariablesCount", true);
    if (string.IsNullOrEmpty(attributeValue2) || int.Parse(attributeValue2) <= 10 || document.NodesCount < 2)
      return;
    DocumentTreeNode node = document.Nodes[0];
    if (node.NodeClass != "Page" && document.NodesCount > 1)
    {
      node = document.Nodes[1];
      if (node.NodeClass != "Page")
        return;
    }
    if (!(node.FindFirstNodeByName("Размещение исполнений") is TextData firstNodeByName))
      return;
    List<ElementSpiskaListov> elementSpiskaListov1 = Vedomost_VB_Static.Create_List_elementSpiskaListov(document);
    if (elementSpiskaListov1 == null || elementSpiskaListov1.Count <= 1)
      return;
    firstNodeByName.SetVisible(true, false, false, false, false, false);
    string str1 = "";
    for (int index = 1; index < elementSpiskaListov1.Count; ++index)
    {
      ElementSpiskaListov elementSpiskaListov2 = elementSpiskaListov1[index];
      string str2;
      if (elementSpiskaListov2.nIspoln == 1)
      {
        str2 = $"{(index != 1 ? "                     " : "Исполнение")} {elementSpiskaListov2.captionFirstIsp}";
      }
      else
      {
        string str3 = index != 1 ? "                     " : "Исполнения";
        if (elementSpiskaListov2.nIspoln == 2)
          str2 = $"{str3} {elementSpiskaListov2.captionFirstIsp}, {elementSpiskaListov2.captionLastIsp}";
        else
          str2 = $"{str3} {elementSpiskaListov2.captionFirstIsp}...{elementSpiskaListov2.captionLastIsp}";
      }
      string str4 = elementSpiskaListov2.nListov != 1 ? (elementSpiskaListov2.nListov != 2 ? $"{str2} - см. листы {elementSpiskaListov2.nFirstList}...{elementSpiskaListov2.nFirstList}" : $"{str2} - см. листы {elementSpiskaListov2.nFirstList}, {elementSpiskaListov2.nLastList}") : $"{str2} - см. лист {elementSpiskaListov2.nFirstList}";
      str1 = $"{str1}{str4}\r\n";
    }
    firstNodeByName.AssignText(str1, false, true, false, true, true);
  }

  /// <summary> Создание списка расположения исполнений формы Б </summary>
  /// <param name="document"></param>
  public static List<ElementSpiskaListov> Create_List_elementSpiskaListov(ImDocument document)
  {
    if (document == null)
      return (List<ElementSpiskaListov>) null;
    string attributeValue1 = document.GetAttributeValue("GroupForm", true);
    if (string.IsNullOrEmpty(attributeValue1))
      return (List<ElementSpiskaListov>) null;
    if (attributeValue1 != "B")
      return (List<ElementSpiskaListov>) null;
    string attributeValue2 = document.GetAttributeValue("VariablesCount", true);
    if (string.IsNullOrEmpty(attributeValue2))
      return (List<ElementSpiskaListov>) null;
    if (int.Parse(attributeValue2) <= 10)
      return (List<ElementSpiskaListov>) null;
    int nodesCount = document.NodesCount;
    if (nodesCount < 2)
      return (List<ElementSpiskaListov>) null;
    List<ElementSpiskaListov> elementSpiskaListov1 = new List<ElementSpiskaListov>();
    int index1 = 0;
    string str1 = "";
    string str2 = "";
    string str3 = "";
    ElementSpiskaListov elementSpiskaListov2 = new ElementSpiskaListov();
    elementSpiskaListov2.nIspoln = 10;
    elementSpiskaListov2.nListov = 1;
    while (index1 < nodesCount)
    {
      DocumentTreeNode node1 = document.Nodes[index1];
      if (node1.NodeClass != "Page")
      {
        ++index1;
      }
      else
      {
        if (node1.Id == "LRI" || node1.Id == "Лист регистрации изменений")
        {
          elementSpiskaListov1.Add(elementSpiskaListov2);
          break;
        }
        str1 = "";
        str2 = "";
        TableData firstNodeByName = node1.FindFirstNodeByName("Номера исполнений") as TableData;
        TextBoxElement node2 = firstNodeByName.Nodes[0] as TextBoxElement;
        if (firstNodeByName != null)
        {
          string text1 = node2.Text;
          if (str3 == "")
          {
            elementSpiskaListov2.nFirstList = index1 + 1;
            elementSpiskaListov2.captionFirstIsp = text1;
            str3 = text1;
            elementSpiskaListov2.nLastList = index1 + 1;
          }
          else
          {
            if (str3 == text1)
            {
              elementSpiskaListov2.nLastList = index1 + 1;
              ++elementSpiskaListov2.nListov;
              ++index1;
              if (index1 == nodesCount)
              {
                elementSpiskaListov1.Add(elementSpiskaListov2);
                break;
              }
              continue;
            }
            elementSpiskaListov1.Add(elementSpiskaListov2);
            elementSpiskaListov2 = new ElementSpiskaListov();
            elementSpiskaListov2.nIspoln = 10;
            elementSpiskaListov2.nListov = 1;
            elementSpiskaListov2.nFirstList = index1 + 1;
            elementSpiskaListov2.captionFirstIsp = text1;
            str3 = text1;
            elementSpiskaListov2.nLastList = index1 + 1;
          }
          for (int index2 = firstNodeByName.NodesCount - 1; index2 > 0; --index2)
          {
            string text2 = (firstNodeByName.Nodes[index2] as TextBoxElement).Text;
            if (!string.IsNullOrEmpty(text2))
            {
              elementSpiskaListov2.captionLastIsp = text2;
              break;
            }
            --elementSpiskaListov2.nIspoln;
          }
        }
        ++index1;
        if (index1 == nodesCount)
        {
          elementSpiskaListov1.Add(elementSpiskaListov2);
          break;
        }
      }
    }
    return elementSpiskaListov1;
  }

  /// <summary>  Очистка ВСЕХ информационных страниц документа /// </summary>
  /// <param name="document"></param>
  public static void Clean_Document(ImDocument document)
  {
    if (document == null)
      return;
    int numberEndInfoPage = Vedomost_VB_Static.FindNumberEndInfoPage(document);
    int numberFirstInfoPage = Vedomost_VB_Static.FindNumberFirstInfoPage(document);
    for (int index = numberEndInfoPage; index > numberFirstInfoPage; --index)
      document.Nodes.RemoveAt(index);
    Vedomost_VB_Static.Get_MainTable_From_PageNumber(document, numberFirstInfoPage).Clear(false, false);
  }

  /// <summary> Количество подстрок в строке </summary>
  /// <param name="sourceString"></param>
  /// <param name="substring"></param>
  /// <returns></returns>
  public static int Count_Substr_in_String(string sourceString, string substring)
  {
    return string.IsNullOrEmpty(sourceString) || string.IsNullOrEmpty(substring) ? 0 : (sourceString.Length - sourceString.Replace(substring, "").Length) / substring.Length;
  }

