  /// <param name="fileName_Nastr"></param>
  /// <returns></returns>
  public static string FileName_Template_For_FileName_Nastr(string fileName_Nastr)
  {
    if (string.IsNullOrEmpty(fileName_Nastr))
      return "";
    fileName_Nastr = fileName_Nastr.ToUpper();
    string str1 = Path.GetExtension(fileName_Nastr);
    if (string.IsNullOrEmpty(str1) || str1 != ".XML")
      return "";
    string str2 = "";
    if (fileName_Nastr.Contains("ONE_VED_NASTR"))
      str2 = fileName_Nastr.Replace("ONE_VED_NASTR", "ШАБЛОН").Replace(".XML", ".IMDX");
    return str2;
  }

  /// <summary> Чтение шаблона </summary>
  /// <param name="templateObjectGuid"></param>
  /// <returns></returns>
  public static ImDocument Get_Template_By_TemplateObjectGuid(Guid templateObjectGuid)
  {
    if (templateObjectGuid == Guid.Empty)
      return (ImDocument) null;
    long templateID = 0;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      IDBObject dbObject = sessionKeeper.Session.GetObject(templateObjectGuid, false);
      if (dbObject != null)
        templateID = dbObject.ObjectID;
    }
    ImDocument templateObjectGuid1 = (ImDocument) null;
    if (templateID != 0L && templateID != -1L)
      templateObjectGuid1 = Vedomost_VB_Static.Get_Template_By_TemplateID(templateID);
    return templateObjectGuid1;
  }

  /// <summary> Чтение шаблона </summary>
  /// <param name="templateID"></param>
  /// <returns></returns>
  public static ImDocument Get_Template_By_TemplateID(long templateID)
  {
    if (templateID == 0L && templateID == -1L)
      return (ImDocument) null;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      if (sessionKeeper.Session.GetObject(templateID, false) == null)
        return (ImDocument) null;
    }
    ImDocument templateByTemplateId = (ImDocument) null;
    MemoryStream aDestStream = new MemoryStream();
    try
    {
      new BlobProcReader(templateID, AttributableElements.Object, Vedomost_VB_Static.fileAttrId, 0, 0, (Stream) aDestStream, (BlobProcCustomClass.ProgressEventHandler) null, (BlobProcCustomClass.ThreadFinishEventHandler) null).ReadData();
      aDestStream.Position = 0L;
      if (aDestStream.Length != 0L)
      {
        templateByTemplateId = ImDocument.LoadFromStream((Stream) aDestStream, true, false, true);
      }
      else
      {
        templateByTemplateId = new ImDocument(true);
        templateByTemplateId.Modified = false;
      }
    }
    finally
    {
      aDestStream.Close();
    }
    return templateByTemplateId;
  }

  /// <summary> Подсчет количества строк на 1 и 2 страницах шаблона </summary>
  /// <param name="template"></param>
  /// <returns>Возвращает КОРТЕЖ int, int</returns>
  public static (int, int) GetLines_InPages(ImDocument template)
  {
    (int, int) linesInPages = (0, 0);
    int num = 0;
    int index1 = 0;
    if (!(template.Nodes[index1] is PageData node1))
      return linesInPages;
    TableData firstNodeByName1 = (TableData) node1.FindFirstNodeByName("Главная таблица");
    int index2;
    if (firstNodeByName1 == null)
    {
      index2 = index1 + 1;
      if (template.NodesCount > 1)
      {
        if (!(template.Nodes[index2] is PageData node2))
          return linesInPages;
        firstNodeByName1 = (TableData) node2.FindFirstNodeByName("Главная таблица");
      }
    }
    else
      index2 = index1 + 1;
    float? heightForUser;
    if (firstNodeByName1 != null)
    {
      heightForUser = firstNodeByName1.HeightForUser;
      num = (int) ((double) heightForUser.Value / (double) firstNodeByName1.DefaultRowSize);
    }
    linesInPages.Item1 = num;
    if (template.NodesCount > index2 + 1)
    {
      TableData firstNodeByName2 = (TableData) (template.Nodes[index2] as PageData).FindFirstNodeByName("Главная таблица");
      if (firstNodeByName2 != null)
      {
        heightForUser = firstNodeByName2.HeightForUser;
        num = (int) ((double) heightForUser.Value / (double) firstNodeByName2.DefaultRowSize);
      }
      linesInPages.Item2 = num;
    }
    return linesInPages;
  }

  /// <summary> Список ГРАФ шаблона </summary>
