  public static List<string> Get_List_Names_Grafa_Temlate(ImDocument template)
  {
    List<string> namesGrafaTemlate = new List<string>();
    for (int index1 = 0; index1 < template.NodesCount; ++index1)
    {
      TableData firstNodeByName1 = (TableData) (template.Nodes[index1] as PageData).FindFirstNodeByName("Главная таблица");
      if (firstNodeByName1 != null)
      {
        DocumentTreeNode firstNodeByName2 = firstNodeByName1.FindFirstNodeByName("Основная строка");
        if (firstNodeByName2 != null)
        {
          for (int index2 = 0; index2 < firstNodeByName2.NodesCount; ++index2)
          {
            DocumentTreeNode node = firstNodeByName2.Nodes[index2];
            namesGrafaTemlate.Add(node.Name);
          }
        }
      }
    }
    return namesGrafaTemlate;
  }

