  /// <summary> Удаление из list_Names_Pages_Temlate недопустимых для вставки </summary>
  /// <param name="name_Page_Current"></param>
  public static void Removal_Excess(List<string> list_Names_Pages_Temlate, string name_Page_Current)
  {
    if (string.IsNullOrEmpty(name_Page_Current))
      return;
    bool flag = false;
    for (int index = list_Names_Pages_Temlate.Count - 1; index > -1; --index)
    {
      string str = list_Names_Pages_Temlate[index];
      if (str == "Титульный лист")
        list_Names_Pages_Temlate.RemoveAt(index);
      else if (name_Page_Current == str)
      {
        flag = true;
        int num = str == "Заглавный лист" ? 1 : 0;
        list_Names_Pages_Temlate.RemoveAt(index);
      }
      else if (flag)
        list_Names_Pages_Temlate.RemoveAt(index);
    }
  }

