  public static string Name_Page_for_Razdel(
    DocumentTreeNode doc_Template,
    One_Ved_Nastr one_Ved_Nastr,
    long razdel_Ved)
  {
    if (doc_Template == null || !Vedomost_VB_Static.Is_Extended_List_Names_Pages_ByTemplate(doc_Template))
      return "";
    string str = "";
    if (one_Ved_Nastr._algorithmToPrint == null)
      return "";
    Vedomost_VB.OneRecordToPrint oneRecordToPrint = (Vedomost_VB.OneRecordToPrint) null;
    if (razdel_Ved < 1L)
      return "";
    if (one_Ved_Nastr._algorithmToPrint._oneRecordToPrint_Info != null)
    {
      Vedomost_VB.OneRecordToPrint recordToPrintInfo1 = one_Ved_Nastr._algorithmToPrint._oneRecordToPrint_Info;
    }
    else if (one_Ved_Nastr._algorithmToPrint._list_OneRazdelToPrint != null && one_Ved_Nastr._algorithmToPrint._list_OneRazdelToPrint.Count > 0)
    {
      Vedomost_VB.OneRecordToPrint recordToPrintInfo2 = one_Ved_Nastr._algorithmToPrint._list_OneRazdelToPrint[0]._oneRecordToPrint_Info;
      for (int index = 0; index < one_Ved_Nastr._algorithmToPrint._list_OneRazdelToPrint.Count; ++index)
      {
        Vedomost_VB.OneRazdelToPrint oneRazdelToPrint = one_Ved_Nastr._algorithmToPrint._list_OneRazdelToPrint[index];
        if ((long) oneRazdelToPrint._razdelVed == razdel_Ved)
        {
          oneRecordToPrint = oneRazdelToPrint._oneRecordToPrint_Info;
          break;
        }
      }
      if (oneRecordToPrint == null)
        return "";
      for (int index = 0; index < doc_Template.NodesCount; ++index)
      {
        DocumentTreeNode node = doc_Template.Nodes[index];
        if (!(node.NodeClass != "Page") && !(node.Id == "TL") && !(node.Id == "Титульный лист") && !(node.Id == "LRI"))
        {
          int num = node.Name == "Лист регистрации изменений" ? 1 : 0;
        }
      }
    }
    return str;
  }

  public static bool Create_Document_From_Avs6File()
  {
    List_Element_Accord_Avs6_Ips.Begin();
    if (List_Element_Accord_Avs6_Ips.list_Element_Accord_Avs6_Ips == null || List_Element_Accord_Avs6_Ips.list_Element_Accord_Avs6_Ips.Count == 0)
      return false;
    string str = "";
    ElDocList elDocList2 = (ElDocList) null;
    Element_Accord_Avs6_Ips element_Accord_Avs6_Ips2 = (Element_Accord_Avs6_Ips) null;
    AVS6_File aVS6File = (AVS6_File) null;
    Vedomost_VB _vedomost_VB_new = (Vedomost_VB) null;
    try
    {
      using (OpenFileDialog openFileDialog = new OpenFileDialog())
      {
        openFileDialog.InitialDirectory = "D:\\IM\\IMWORK";
        openFileDialog.Filter = "Файлы AVS6 (*.*)|*.*";
        openFileDialog.FilterIndex = 1;
        openFileDialog.RestoreDirectory = true;
        if (openFileDialog.ShowDialog() != DialogResult.OK)
          return false;
        str = openFileDialog.FileName;
        if (!string.IsNullOrEmpty(str))
        {
          aVS6File = new AVS6_File();
          if (aVS6File == null || !aVS6File.Read(str))
            return false;
          elDocList2 = aVS6File.Classification_By_Avs6Main();
          if (elDocList2 == null)
          {
            int num = (int) MessageBox.Show(!(Path.GetExtension(str).ToUpper() == "SP") ? $"Файл\r\n\r\n{str}\r\n\r\nне найден в списке конвертируемых из AVS6 в IPS" : $"Файл\r\n\r\n{str}\r\n\r\nэто спецификация\r\nСпецификации - не конвертируются из AVS6 в IPS", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
            return false;
          }
          element_Accord_Avs6_Ips2 = aVS6File.Classification_By_list_Element_Accord_Avs6_Ips();
          if (element_Accord_Avs6_Ips2 == null)
          {
            int num = (int) MessageBox.Show($"Для файла\r\n\r\n{str}\r\n\r\nне найдена настройка в списке конвертации", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
            return false;
          }
          aVS6File.Synchronization_With_IPS();
        }
      }
    }
    catch (Exception ex)
    {
      int num = (int) MessageBox.Show("Ошибка чтения файла\r\n\r\n" + str, "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
      return false;
    }
    using (new SessionKeeper())
    {
      long objectWithDesignation = (ServicesManager.GetService(typeof (IPDMSpecificationsService)) as IPDMSpecificationsService).GetObjectWithDesignation(AvsIDCache.ObjType_Document, aVS6File._designation);
      switch (objectWithDesignation)
      {
        case -1:
        case 0:
          if (objectWithDesignation != 0L)
          {
            if (objectWithDesignation != -1L)
            {
              if (MessageBox.Show($"Документ\r\n\r\n{aVS6File._designation}\r\n\r\nуже существует!\r\nСоздать заново?", "Внимание!", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
                return false;
              if (objectWithDesignation > 0L)
              {
                int num = (int) MessageBox.Show($"Документ\r\n\r\n{aVS6File._designation}\r\n\r\nЗакрыт для редактирования.\r\nЕго необходимо предварительно взять на редактирование", "Внимание!", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                return false;
              }
              break;
            }
            break;
          }
          break;
        default:
          if (string.IsNullOrEmpty(Vedomost_VB_Static.Get_DocumentTypeSuffix_ForObjectTypeId(objectWithDesignation)))
          {
            int num = (int) MessageBox.Show("В конфигураторе базы данных для документа данного типа\r\n\r\n" + "не настроен \"Код типа документа\", например \"ДП\"" + "\r\nи Код должен входить в обозначение", "Ошибка!", MessageBoxButtons.OK, MessageBoxIcon.Hand);
            return false;
          }
          goto case -1;
      }
    }
    if (aVS6File.GroupForm == AVSDocumentForm.B)
    {
      Vedomost_VB documentFromAvs6File = Vedomost_VB_Static.Create_Document_From_Avs6File(aVS6File, elDocList2, element_Accord_Avs6_Ips2);
      documentFromAvs6File.CreateAndOpenNewDocument(true, true, false);
      ImDocument document = AVSPlugin.Instance.ActiveImDocumentEditorForm.Document;
      if (document != null)
        Vedomost_VB_Static.Filled_Data_From_Avs6File_To_Document(document, documentFromAvs6File, aVS6File);
    }
    else
    {
      if (_vedomost_VB_new == null)
        _vedomost_VB_new = new Vedomost_VB();
      DocumentEditorPlugin.Instance.OpenDocumentImDocumentObject(Vedomost_VB_Static.Create_Document_From_Avs6File(aVS6File, elDocList2, element_Accord_Avs6_Ips2, _vedomost_VB_new), false, true, new DocumentWindowCreatorDelegate(VedomostEditorWindow.VedomostEditorWindowCreator));
      ImDocument document = AVSPlugin.Instance.ActiveImDocumentEditorForm.Document;
      Vedomost_VB_Static.Cleaning_Document(document);
      if (document != null)
        Vedomost_VB_Static.Filled_Data_From_Avs6File_To_Document(document, _vedomost_VB_new, aVS6File);
    }
    return true;
  }

  /// <summary> Создание списка описания List_Conformity_Template_Nastr_... из list_Arbeit_ImsObjectType_With_One_Ved_Nastr </summary>
  /// <param name="list_Arbeit_ImsObjectType_With_One_Ved_Nastr"></param>
  /// <param name="list_Conformity_Template_Nastr"></param>
  /// <param name="typeDoc"></param>
  public static void List_Conformity_Template_Nastr_Filled(
    List<One_ImsObjectType_With_One_Ved_Nastr> list_Arbeit_ImsObjectType_With_One_Ved_Nastr,
    List<Vedomost_VB_Static.One_Conformity_Template_Nastr> list_Conformity_Template_Nastr,
    Vedomost_VB.TypeDoc typeDoc)
  {
    if (!Vedomost_VB_Static.IsUse_New_System_ByOneNastrMain || typeDoc != Vedomost_VB.TypeDoc.Ved && typeDoc != Vedomost_VB.TypeDoc.Tabl)
      return;
