    {
      Vedomost_VB_Static.One_Conformity_Template_Nastr conformityTemplateNastr = new Vedomost_VB_Static.One_Conformity_Template_Nastr();
      for (int i = 0; i < childNode.Attributes.Count; ++i)
      {
        XmlAttribute attribute = childNode.Attributes[i];
        string name = attribute.Name;
        string g = attribute.Value.ToString();
        switch (name)
        {
          case "guid_One_Ved_Nastr":
            conformityTemplateNastr._guid_One_Ved_Nastr = new Guid(g);
            break;
          case "guid_Template":
            conformityTemplateNastr._guid_Template = new Guid(g);
            break;
          case "guid_TypeVed":
            conformityTemplateNastr._guid_TypeVed = new Guid(g);
            break;
          case "name_One_Ved_Nastr":
            conformityTemplateNastr._name_One_Ved_Nastr = g;
            break;
          case "name_Template":
            conformityTemplateNastr._name_Template = g;
            break;
          case "name_Ved":
