          case "typeDoc":
            switch (g)
            {
              case "Ved":
                conformityTemplateNastr._typeDoc = Vedomost_VB.TypeDoc.Ved;
                continue;
              case "Tabl":
                conformityTemplateNastr._typeDoc = Vedomost_VB.TypeDoc.Tabl;
