      switch (objectTypeId)
      {
        case -1:
        case 0:
          Vedomost_VB_Static.is_Status_New_Nastr_Vetka = -1;
          break;
        default:
          int attributeId = MetaDataHelper.GetAttributeID((object) Vedomost_VB_Static.Guid_AttributeNastr_InConfigurator);
          switch (attributeId)
