                            Vedomost_VB_Static.Conformity_From_XmlDocument(xmlDocument, Vedomost_VB_Static.List_Conformity_Template_Nastr_Tabl);
                            continue;
                          default:
                            continue;
                        }
                      }
                      else
                      {
                        One_Ved_Nastr oneVedNastr = new One_Ved_Nastr();
                        if (oneVedNastr.Filled_One_Ved_Nastr_FromXml(xmlDocument))
                          list_One_Ved_Nastr.Add(oneVedNastr);
                      }
                    }
                  }
                }
              }
              if (list_One_Ved_Nastr == null || list_One_Ved_Nastr.Count <= 0)
                return;
              bool flag1 = false;
              if (Vedomost_VB_Static.List_Conformity_Template_Nastr_Ved != null && Vedomost_VB_Static.List_Conformity_Template_Nastr_Ved.Count > 0)
                flag1 = Vedomost_VB_Static.One_Ved_Nastr_To_Conformity(list_One_Ved_Nastr, Vedomost_VB_Static.List_Conformity_Template_Nastr_Ved);
              bool flag2 = false;
