                flag2 = Vedomost_VB_Static.One_Ved_Nastr_To_Conformity(list_One_Ved_Nastr, Vedomost_VB_Static.List_Conformity_Template_Nastr_Tabl);
              if (!(flag1 | flag2) || !Vedomost_VB_Static.IsUse_New_System_ByOneNastrMain)
                return;
              Vedomost_VB_Static.IsUse_New_System_ByOneNastr = true;
              return;
            default:
              Vedomost_VB_Static.is_Status_New_Nastr_Vetka = 1;
              goto case -1;
          }
      }
    }
  }

