  /// <summary> Получение списка программ с датами и версиями для DUMP </summary>
  /// <returns></returns>
  public static List<string> GelVersion_AVS()
  {
    List<string> stringList = new List<string>();
    string ipsServicePack = Vedomost_VB_Static.AssemblyAttributes.IPSServicePack;
    string s1 = Vedomost_VB_Static.AssemblyAttributes.IPSBuildDate;
    string s2 = Vedomost_VB_Static.AssemblyAttributes.IPSBuildTime;
    DateTime result;
    if (DateTime.TryParse(s1, out result))
    {
      result = result.ToLocalTime();
      s1 = result.ToShortDateString();
    }
    if (DateTime.TryParse(s2, out result))
    {
      result = result.ToLocalTime();
      s2 = result.ToShortTimeString();
    }
    stringList.Add("Дата : " + s1);
    stringList.Add("Время : " + s2);
    FileInfo fileInfo = new FileInfo(typeof (XMLSettingsStorage).Assembly.Location);
    object[] customAttributes = typeof (XMLSettingsStorage).Assembly.GetCustomAttributes(typeof (AssemblyBuildDate), true);
    if (customAttributes != null && customAttributes.Length != 0)
    {
      object obj = customAttributes[0];
    }
    foreach (IPlugin plugin in (IEnumerable<IPlugin>) (ServicesManager.GetService(typeof (IPluginManager)) as IPluginManager).Plugins)
    {
      foreach (IPackage package in (IEnumerable<IPackage>) plugin.Packages)
      {
        string location = plugin.Location;
        string str = package.GetType().Assembly.GetName().Version.ToString();
        stringList.Add($"{location} : {str}");
      }
    }
    return stringList;
  }

  /// <summary> Чтение данных из выбранной строки таблицы IMBASE </summary>
