  public static List<Vedomost_VB_Static.AttributeValuesVed> Get_List_AttributeValuesVed_FromImbase(
    long ObjId)
  {
    List<Vedomost_VB_Static.AttributeValuesVed> valuesVedFromImbase = (List<Vedomost_VB_Static.AttributeValuesVed>) null;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      if (!(sessionKeeper.Session.GetCustomService(typeof (IImbaseServer)) is IImbaseServer customService))
        return valuesVedFromImbase;
      long objectId = 0;
      int num = 0;
      IDBObject dbObject1 = sessionKeeper.Session.GetObject(ObjId, false);
      if (dbObject1 == null)
        return valuesVedFromImbase;
      IDBObject dbObject2 = dbObject1;
      IDBAttribute attributeById1 = dbObject2.GetAttributeByID(Intermech.Imbase.Consts.ImbaseObjectRefAttID);
      IDBAttribute attributeById2 = dbObject2.GetAttributeByID(Intermech.Imbase.Consts.ImbaseInternalOldKeyAttID);
      if (attributeById1 != null && attributeById1.Values[0] != null && attributeById1.Values[0] != DBNull.Value)
      {
        objectId = Convert.ToInt64(attributeById1.Values[0]);
        if (attributeById2 != null && attributeById2.Values[0] != null)
          num = Convert.ToInt32(attributeById2.Values[0]);
      }
      string filter = $"[-2]={num}";
      DataTable recordsTable = (DataTable) null;
      AttributeTypeProperties[] columnsAttributes = (AttributeTypeProperties[]) null;
      ImbaseKeyInfo keyInfo = new ImbaseKeyInfo(-1L);
      customService.LoadRecords(sessionKeeper.Session.SessionGUID, objectId, filter, Thread.CurrentThread.CurrentCulture.NumberFormat.NumberDecimalSeparator, out recordsTable, out columnsAttributes, out keyInfo);
      return Vedomost_VB_Static.Create_List_AttributeValuesVed_FromImbase(recordsTable.Rows[0], columnsAttributes);
    }
  }

