  /// <summary> Возвращает ОДИН атрибут из строки таблицы Imbase </summary>
  /// <param name="attType">Описание атрибута. В т.ч. attType.AttributeID</param>
  /// <param name="attValue">Значение атрибута  например "Размеры и параметры"[""] attId=1102, type=ftString</param>
  /// <param name="isEmpty"> Если False, то при пустом value возвращает null</param>
  /// <returns></returns>
  public static Vedomost_VB_Static.AttributeValuesVed Get_AttributeValuesVed(
    AttributeTypeProperties attType,
    object attValue,
    bool isEmpty)
  {
    if (attValue == null)
      return (Vedomost_VB_Static.AttributeValuesVed) null;
    if (attType.AttributeID == 0 || attType.AttributeID == -1)
      return (Vedomost_VB_Static.AttributeValuesVed) null;
    Vedomost_VB_Static.AttributeValuesVed attributeValuesVed = new Vedomost_VB_Static.AttributeValuesVed(attType.AttributeID, attType.Name);
    bool flag = true;
    switch (attType.FieldType)
    {
      case FieldTypes.ftInteger:
      case FieldTypes.ftDouble:
      case FieldTypes.ftMeasured:
      case FieldTypes.ftAutoInc:
        flag = false;
        break;
    }
    if (TableLoadHelper.IsNull(attValue))
    {
      if (!isEmpty)
        return (Vedomost_VB_Static.AttributeValuesVed) null;
      string str = !flag ? "0" : string.Empty;
      attributeValuesVed.value = str;
      return attributeValuesVed;
    }
    string str1 = attValue.ToString();
    if (attType.FieldType == FieldTypes.ftMeasured && attValue is MeasuredValue mValue)
    {
      if (MeasureHelper.FindDescriptor(mValue.MeasureID).PhysicalQuantityID == Intermech.Imbase.Consts.MeasureLengthID)
        mValue = MeasureHelper.ConvertToMeasuredValue(mValue, Intermech.Imbase.Consts.mmUnitID);
      str1 = mValue.MeasureID != 0L ? mValue.Value.ToString() : mValue.Caption;
    }
    if (!flag)
      str1 = str1.Replace(',', '.');
    attributeValuesVed.value = str1;
    return attributeValuesVed;
  }

