  /// <summary> Из строки таблицы возвращает List строк типа "Имя атрибута=значение" например "Применяемость=+" Пока не используется </summary>
  /// <param name="dataRow"></param>
  /// <param name="atts">список строк типа NameAttr AttrId, TypeId например "Размеры и параметры"[""] attId=1102, type=ftString</param>
  /// <param name="shortNames"></param>
  /// <param name="quotes"></param>
  /// <returns></returns>
  internal static List<Vedomost_VB_Static.Para_String> CreateList(
    DataRow dataRow,
    AttributeTypeProperties[] atts,
    bool shortNames,
    bool quotes)
  {
    int length = atts.Length;
    List<Vedomost_VB_Static.Para_String> list = new List<Vedomost_VB_Static.Para_String>(length);
    for (int index = 0; index < length; ++index)
    {
      DataColumn column = dataRow.Table.Columns[atts[index].AttributeID.ToString()];
      string name;
      string str;
      if (column != null && Vedomost_VB_Static.Get_AttributeValuesVed(atts[index], dataRow[column], out name, out str) && !string.IsNullOrEmpty(str))
        list.Add(new Vedomost_VB_Static.Para_String()
        {
          name = name,
          value = str
        });
    }
    return list;
  }

  /// <summary> Возвращает строку "Имя атрибута=значение" например "Применяемость=+" (Пока не применяется) </summary>
  /// <param name="attType"></param>
  /// <param name="attValue"> например "Размеры и параметры"[""] attId=1102, type=ftString</param>
  /// <param name="name"> Возвращает имя атрибута</param>
  /// <param name="value"> Возвращает значение атрибута в виде строки</param>
  /// <param name="shortName"></param>
  /// <param name="quotes"></param>
  /// <returns></returns>
  private static bool Get_AttributeValuesVed(
    AttributeTypeProperties attType,
    object attValue,
    out string name,
    out string value)
  {
    name = attType.Name;
    bool flag = true;
    switch (attType.FieldType)
    {
      case FieldTypes.ftInteger:
      case FieldTypes.ftDouble:
      case FieldTypes.ftMeasured:
      case FieldTypes.ftAutoInc:
        flag = false;
        break;
    }
    if (TableLoadHelper.IsNull(attValue))
    {
      value = !flag ? "0" : string.Empty;
      return true;
    }
    value = attValue.ToString();
    if (attType.FieldType == FieldTypes.ftMeasured && attValue is MeasuredValue mValue)
    {
      if (MeasureHelper.FindDescriptor(mValue.MeasureID).PhysicalQuantityID == Intermech.Imbase.Consts.MeasureLengthID)
        mValue = MeasureHelper.ConvertToMeasuredValue(mValue, Intermech.Imbase.Consts.mmUnitID);
      value = mValue.MeasureID != 0L ? mValue.Value.ToString() : mValue.Caption;
    }
    value = !flag ? value.Replace(',', '.') : $"\"{value}\"";
    return true;
  }

