  /// <summary> Проверка - есть ли строки СПИСКА заголовков /// </summary>
  /// <param name="Document"></param>
  /// <returns></returns>
  public static bool CheckListZagolovki(ImDocument document)
  {
    for (int index1 = 0; index1 < document.NodesCount; ++index1)
    {
      PageData node1 = document.Nodes[index1] as PageData;
      if (!(node1.NodeClass != "Page") && !(node1.Id == "TL") && !(node1.Id == "Титульный лист") && !(node1.Name == "Титульный лист") && !(node1.Id == "LRI") && !(node1.Name == "Лист регистрации изменений"))
      {
        TableData firstNodeByName = (TableData) node1.FindFirstNodeByName("Главная таблица");
        if (firstNodeByName != null)
        {
          for (int index2 = 0; index2 < firstNodeByName.NodesCount; ++index2)
          {
            DocumentTreeNode node2 = firstNodeByName.Nodes[index2];
            if (node2 != null)
            {
              switch (node2.GetAttributeValue("TypeRec", true))
              {
                case "Oglavlenie":
                  return true;
                case "Title":
                case "Info":
                  return false;
                default:
                  continue;
              }
            }
          }
        }
      }
    }
    return false;
  }

  /// <summary> Для формы Б заполнение номеров исполнений </summary>
  /// <param name="document"></param>
  public static void FillProductHeadersOnPages(
    ImDocument document,
    string designationArticle,
    Vedomost_VB.Variables_Coordination variables_Coordination)
  {
    int index1 = 0;
    int num1 = 0;
    foreach (PageData pageData in (ImDocumentData) document)
    {
      string attributeValue = (document.Nodes[index1] as PageData).GetAttributeValue("iCikl", true);
      if (!string.IsNullOrEmpty(attributeValue))
        num1 = int.Parse(attributeValue) * 10;
      ++index1;
      if (pageData.FindFirstNodeByName("Заголовок таблицы исполнений") is TextData firstNodeByName1)
      {
        string str = firstNodeByName1.Text;
        if (string.IsNullOrEmpty(str))
          str = Vedomost_VB_Static.Kol_na_ispoln_Template;
        firstNodeByName1.AssignText(string.Format(str + " {0} -", (object) designationArticle), false, true, false, false, false);
      }
      if (pageData.FindFirstNodeByName("Номера исполнений") is TableData firstNodeByName2)
      {
        int count = variables_Coordination.list_Variables.Count;
        int num2 = num1 + 10;
        if (variables_Coordination != null && variables_Coordination.list_Variables.Count <= count)
        {
          int index2 = -1;
          int index3 = num1;
          while (true)
          {
            if (index3 < num2 && index3 < variables_Coordination.list_Variables.Count)
            {
              ++index2;
              if (firstNodeByName2.Nodes[index2] is TextData node)
              {
                string listVariable = variables_Coordination.list_Variables[index3];
                string listCaption = variables_Coordination.list_Captions[index3];
                node.AssignText(listCaption, false, true, false, false, false);
              }
              ++index3;
            }
            else
              goto label_21;
          }
        }
        else
        {
          int index4 = 0;
          while (true)
          {
            if (index4 < variables_Coordination.list_Captions.Count && index4 < firstNodeByName2.Nodes.Count)
            {
              if (firstNodeByName2.Nodes[index4] is TextData node)
              {
                string listCaption = variables_Coordination.list_Captions[index4];
                if (!string.IsNullOrEmpty(listCaption))
                  node.AssignText(listCaption, false, true, false, false, false);
                else
                  goto label_21;
              }
              ++index4;
            }
            else
              goto label_21;
          }
        }
      }
      else
        continue;
label_21:;
    }
  }

  /// <summary> Присвоение или отмена всем текстовым ячейкам параметра ReadOnly </summary>
  /// <param name="docRow"></param>
  /// <param name="set_readOnly">ReadOnly</param>
  /// <param name="only_Filled">Только заполненным ячейкам</param>
  public static void DocRow_ReadOnly(DocumentTreeNode docRow, bool set_readOnly, bool only_Filled)
  {
    for (int index = 0; index < docRow.NodesCount; ++index)
    {
      DocumentTreeNode node = docRow.Nodes[index];
      if (node.NodeClass != "TextBoxElement")
      {
        Vedomost_VB_Static.DocRow_ReadOnly(node, set_readOnly, false);
      }
      else
      {
        TextData textData = node as TextData;
        if (!set_readOnly)
          textData.ReadOnly = false;
        else if (!only_Filled)
          textData.ReadOnly = true;
        else if (!string.IsNullOrEmpty(textData.Text))
          textData.ReadOnly = true;
      }
    }
    if (set_readOnly)
      docRow.SetAttributeValue("ReadOnly", "ReadOnly");
    else
      docRow.RemoveAttribute("ReadOnly", false, false);
  }

  /// <summary> Всем Главным таблицам присвоить ReadOny </summary>
  /// <param name="document"></param>
  /// <param name="set_readOnly">true or false</param>
  /// <param name="only_Filled">Только заполненным полям</param>
  public static void MainTables_ReadOnly(
    DocumentTreeNode document,
    bool set_readOnly,
    bool only_Filled)
  {
    for (int index = 0; index < document.NodesCount; ++index)
    {
      PageData node = document.Nodes[index] as PageData;
      if (!(node.NodeClass != "Page") && !(node.Id == "TL") && !(node.Id == "Титульный лист") && !(node.Name == "Титульный лист") && !(node.Id == "LRI") && !(node.Name == "Лист регистрации изменений"))
      {
        TableData firstNodeByName = (TableData) node.FindFirstNodeByName("Главная таблица");
        if (firstNodeByName != null)
        {
          Vedomost_VB_Static.DocRow_ReadOnly((DocumentTreeNode) firstNodeByName, true, false);
          int num1 = firstNodeByName.ReadOnlyStructure ? 1 : 0;
          int num2 = firstNodeByName.ReadOnlyNow ? 1 : 0;
          firstNodeByName.SetReadOnly(true, true);
          firstNodeByName.ReadOnly = true;
          int num3 = firstNodeByName.ReadOnlyStructure ? 1 : 0;
          int num4 = firstNodeByName.ReadOnlyNow ? 1 : 0;
        }
      }
    }
    if (set_readOnly)
      document.SetAttributeValue("ReadOnly", "ReadOnly");
    else
      document.RemoveAttribute("ReadOnly", true, false);
  }

