  /// <summary> Вставка на Титульный лист в TextData с именем fieldName строки text </summary>
  /// <param name="document"></param>
  /// <param name="text"></param>
  /// <param name="fieldName"></param>
  public static void Add_LU_ToTitList(ImDocument document, string text, string fieldName)
  {
    DocumentTreeNode node1 = document.Nodes[0];
    if (node1.NodeClass != "Page" || node1.Name != "Титульный лист" || !(node1.FindNode(fieldName) is TextData node2))
      return;
    node2.AssignText(text, false, false, false);
  }

  /// <summary> Проверка на Титульном листе в TextData с именем fieldName есть ли текст </summary>
  /// <param name="document"></param>
  /// <param name="fieldName"></param>
  /// <returns></returns>
  public static bool Is_LU_InTitList(ImDocument document, string fieldName)
  {
    DocumentTreeNode node1 = document.Nodes[0];
    return !(node1.NodeClass != "Page") && !(node1.Name != "Титульный лист") && node1.FindNode(fieldName) is TextData node2 && !string.IsNullOrEmpty(node2.Text);
  }

  /// <summary> Есть ли Лист утверждения для ДОКУМЕНТА </summary>
  /// <param name="document"></param>
