  /// <summary> Есть ли ДОКУМЕНТ с таким обозначением </summary>
  /// <param name="designation"></param>
  /// <returns></returns>
  public static long Check_Doc_By_Designation(string designation)
  {
    if (string.IsNullOrEmpty(designation))
      return 0;
    using (new SessionKeeper())
    {
      long objectIdByDesignation = Vedomost_VB_Static.Get_ObjectID_By_Designation(designation);
      return !objectIdByDesignation.IsUndefinedId() ? objectIdByDesignation : 0L;
    }
  }

  /// <summary> Получить ObjectID по Обозначению </summary>
  /// <param name="designation"></param>
  /// <returns></returns>
  public static long Get_ObjectID_By_Designation(string designation)
  {
    if (string.IsNullOrEmpty(designation))
      return -1;
    using (new SessionKeeper())
    {
      long objectWithDesignation = (ServicesManager.GetService(typeof (IPDMSpecificationsService)) as IPDMSpecificationsService).GetObjectWithDesignation(AvsIDCache.ObjType_Document, designation);
      return !objectWithDesignation.IsUndefinedId() ? objectWithDesignation : -1L;
    }
  }

  /// <summary> Получить из БАЗЫ ОБОЗНАЧЕНИЕ объекта </summary>
  /// <param name="objectID"></param>
  /// <returns></returns>
  public static string Get_Designation_By_ObjectId(long objectID)
  {
    if (objectID.IsUndefinedId())
      return "";
    IDBObject dbObject = (IDBObject) null;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      dbObject = sessionKeeper.Session.GetObject(objectID, false);
      if (dbObject == null)
        return (string) null;
    }
    AttributeValues[] attributesValues = dbObject.GetAttributesValues(GetAttributeValuesModes.IncludeObligatoryAttributes | GetAttributeValuesModes.IncludeDescriptions);
    for (int index = 0; index < attributesValues.Length; ++index)
    {
      MetaDataHelper.GetAttributeTypeName(attributesValues[index].AttributeID);
      if (attributesValues[index].Values[0] != DBNull.Value)
      {
        string designationByObjectId = attributesValues[index].Values[0].ToString();
        if (attributesValues[index].AttributeID == AvsIDCache.Attr_Designation)
          return designationByObjectId;
      }
    }
    return "";
  }

  /// <summary> Получить из БАЗЫ значение атрибута для объекта </summary>
  /// <param name="objectID"></param>
  /// <param name="attrId"></param>
  /// <returns></returns>
  public static string Get_Value_By_ObjectId_AttrId(long objectID, int attrId)
  {
    if (objectID.IsUndefinedId())
      return "";
    IDBObject dbObject = (IDBObject) null;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      dbObject = sessionKeeper.Session.GetObject(objectID, false);
      if (dbObject == null)
        return (string) null;
    }
    AttributeValues[] attributesValues = dbObject.GetAttributesValues(GetAttributeValuesModes.IncludeObligatoryAttributes | GetAttributeValuesModes.IncludeDescriptions);
    for (int index = 0; index < attributesValues.Length; ++index)
    {
      MetaDataHelper.GetAttributeTypeName(attributesValues[index].AttributeID);
      if (attributesValues[index].Values[0] != DBNull.Value)
      {
        string byObjectIdAttrId = attributesValues[index].Values[0].ToString();
        if (attributesValues[index].AttributeID == attrId)
          return byObjectIdAttrId;
      }
    }
    return "";
  }

