  /// <summary> Создать Лист утверждения по ОБОЗНАЧЕНИЮ </summary>
  /// <param name="designationDoc"></param>
  /// <returns></returns>
  public static ImDocument GenerateImDocument_LU(string designationDoc)
  {
    if (string.IsNullOrEmpty(designationDoc))
      return (ImDocument) null;
    string str = designationDoc + "-ЛУ";
    long objectIdByDesignation = Vedomost_VB_Static.Get_ObjectID_By_Designation(designationDoc);
    if (objectIdByDesignation.IsUndefinedId())
      return (ImDocument) null;
    IDBObject dbObject = (IDBObject) null;
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      dbObject = sessionKeeper.Session.GetObject(objectIdByDesignation, false);
      if (dbObject == null)
        return (ImDocument) null;
    }
    AttributeValues[] attributesValues = dbObject.GetAttributesValues(GetAttributeValuesModes.IncludeObligatoryAttributes | GetAttributeValuesModes.IncludeDescriptions);
    for (int index = 0; index < attributesValues.Length; ++index)
    {
      MetaDataHelper.GetAttributeTypeName(attributesValues[index].AttributeID);
      if (attributesValues[index].Values[0] != DBNull.Value)
        attributesValues[index].Values[0].ToString();
    }
    ImDocument documentByObjectId = Vedomost_VB_Static.GetDocument_By_objectID(objectIdByDesignation);
    if (documentByObjectId == null)
      return (ImDocument) null;
    string name = documentByObjectId.Name;
    return (ImDocument) null;
  }

  /// <summary> Из docRow получить значение по attrId </summary>
  /// <param name="docRow"></param>
  /// <param name="attrId"></param>
  /// <returns></returns>
  public static string GetValue_From_docRow(TableData docRow, int attrId)
  {
    string valueFromDocRow = "";
    StringCollection attributeNames = docRow.GetAttributeNames(false);
    for (int index = 0; index < attributeNames.Count; ++index)
    {
      string attributeName = attributeNames[index];
      string attributeValue = docRow.GetAttributeValue(attributeName, true);
      if (attributeName.StartsWith("OneDataVed"))
      {
        int length = attributeValue.IndexOf('=');
        if (length > 1)
        {
          int num = int.Parse(attributeValue.Substring(0, length));
          if (attrId == num)
          {
            valueFromDocRow = attributeValue.Substring(length + 1);
            break;
          }
        }
      }
    }
    return valueFromDocRow;
  }

  /// <summary> Получение Razdel_Ved (если attrId==0) Если attrId == Attr_FuncGroup то ЭТО </summary>
  /// <param name="docRow"></param>
  /// <param name="objectVedZagol"></param>
  /// <returns></returns>
  public static string GetRazdel(TableData docRow, int objectVedZagol)
  {
    if (docRow == null)
      return "";
    string razdel = "";
    if (objectVedZagol == 1 || objectVedZagol == 0)
      return docRow.GetAttributeValue("Razdel_Ved", true);
    if (objectVedZagol == AvsIDCache.Attr_FuncGroup)
      razdel = Vedomost_VB_Static.GetValue_From_docRow(docRow, AvsIDCache.Attr_FuncGroup);
    if (razdel == "")
      razdel = docRow.GetAttributeValue("Razdel_Ved", true);
    return razdel;
  }

  /// <summary> "Razdel_Ved" в строкею Иначе = 1 </summary>
  /// <param name="docRow"></param>
  /// <returns></returns>
  public static long GetRazdel(TableData docRow)
  {
    long razdel = 1;
    string attributeValue = docRow.GetAttributeValue("Razdel_Ved", true);
    if (!string.IsNullOrEmpty(attributeValue))
    {
      try
      {
        razdel = long.Parse(attributeValue);
      }
      catch (FormatException ex)
      {
        razdel = 1L;
      }
    }
    return razdel;
  }

  public static int Compare_StrongOrInt(string s1, string s2, Vedomost_VB.TypeCompare typeCompare)
  {
    if (s1 == s2)
      return 0;
    int num = 0;
    if (typeCompare == Vedomost_VB.TypeCompare.Symbol)
      return string.Compare(s1, s2, StringComparison.Ordinal);
    try
    {
      return int.Parse(s1) - int.Parse(s2);
    }
    catch
    {
      return num;
    }
  }

  /// <summary> Добавление в окно сообщений ПРОСТОГО текста </summary>
  /// <param name="message"></param>
  public static void ListError_Add(ListError_OneError listError_OneError, string message)
  {
    if (string.IsNullOrEmpty(message))
      return;
    OneError oneError = new OneError();
    oneError._message_kurc = message;
    oneError.Message();
    if (listError_OneError == null)
      listError_OneError = new ListError_OneError();
    listError_OneError._list.Add(oneError);
    if (!message.StartsWith("В шаблоне не найден"))
      return;
    Vedomost_VB_Static.ListError_Add(listError_OneError, "Вероятно шаблон устарел и требуется его доработка");
  }

  /// <summary> Сравнение (контрооль, проверка) шаблона и настроек </summary>
  /// <param name="listError_OneError"></param>
  /// <param name="algorithmToPrint"></param>
  /// <param name="docTemplate"></param>
  public static void Checking_Template_And_Nastr(
    ListError_OneError listError_OneError,
    Vedomost_VB.AlgorithmToPrint algorithmToPrint,
    ImDocument docTemplate)
  {
    List<string> stringList1 = Vedomost_VB_Static.Filled_list_tableRowId_ForVyvod(algorithmToPrint);
    List<string> stringList2 = Vedomost_VB_Static.Filled_list_tableRowId_Template(docTemplate);
    bool flag1 = false;
    for (int index1 = 0; index1 < stringList1.Count; ++index1)
    {
      string str1 = stringList1[index1];
      if ((algorithmToPrint._additional1 != 0 || !(str1 == "Дополнительная 1")) && (algorithmToPrint._additional2 != 0 || !(str1 == "Дополнительная 2")) && (algorithmToPrint._additional3 != 0 || !(str1 == "Дополнительная 3")) && (algorithmToPrint._additional4 != 0 || !(str1 == "Дополнительная 4")))
      {
        bool flag2 = false;
        for (int index2 = 0; index2 < stringList2.Count; ++index2)
        {
          string str2 = stringList2[index2];
          if (str1 == str2)
          {
            flag2 = true;
            break;
          }
        }
        if (!flag2)
        {
          Vedomost_VB_Static.ListError_Add(listError_OneError, "  Тип строки: " + str1);
          flag1 = true;
        }
      }
    }
    List<Vedomost_VB_Static.Para_String> paraStringList = Vedomost_VB_Static.Filled_list_Names_ForVyvod(algorithmToPrint);
    if (paraStringList == null)
      return;
    List<string> stringList3 = Vedomost_VB_Static.Filled_list_Graf_IDs(docTemplate);
    if (stringList3 == null)
      return;
    for (int index3 = 0; index3 < paraStringList.Count; ++index3)
    {
      Vedomost_VB_Static.Para_String paraString = paraStringList[index3];
      string name = paraString.name;
      bool flag3 = false;
      for (int index4 = 0; index4 < stringList3.Count; ++index4)
      {
        string str = stringList3[index4];
        if (name == str)
        {
          flag3 = true;
          break;
        }
      }
      if (!flag3)
      {
        Vedomost_VB_Static.ListError_Add(listError_OneError, $" Ячейка \"{name}\": {paraString.value}");
        flag1 = true;
      }
    }
    if (((listError_OneError == null || listError_OneError._list == null ? 0 : (listError_OneError._list.Count > 0 ? 1 : 0)) & (flag1 ? 1 : 0)) == 0)
      return;
    Vedomost_VB_Static.ListError_Add(listError_OneError, "   В ШАБЛОНЕ НЕ НАЙДЕНЫ:");
  }

  /// <summary> Получаем список ВСЕХ НЕОБХОДИМЫХ текстовых полей для вывода </summary>
  /// <param name="algorithmToPrint"></param>
  /// <returns></returns>
  public static List<Vedomost_VB_Static.Para_String> Filled_list_Names_ForVyvod(
    Vedomost_VB.AlgorithmToPrint algorithmToPrint)
  {
    if (algorithmToPrint == null)
      return (List<Vedomost_VB_Static.Para_String>) null;
    List<Vedomost_VB_Static.Para_String> paraStringList = new List<Vedomost_VB_Static.Para_String>();
    Vedomost_VB.OneRecordToPrint oneRecordToPrint1 = (Vedomost_VB.OneRecordToPrint) null;
    Vedomost_VB.OneRecordToPrint oneRecordToPrint2 = (Vedomost_VB.OneRecordToPrint) null;
    bool flag = false;
    int num = 0;
    while (!flag)
    {
      switch (num)
      {
        case 0:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrint_Info;
          oneRecordToPrint2 = oneRecordToPrint1;
          break;
        case 1:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintIncluded;
          break;
        case 2:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintTitleIncluded;
          break;
        case 3:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintTitleVar;
          break;
        case 4:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintTitleIsp;
          break;
        case 5:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintTitle;
          break;
        case 6:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintRemark;
          break;
        case 7:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintRemarkShort;
          break;
        case 9:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintEmpty;
          break;
        case 10:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintAdditional1;
          break;
        case 11:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintAdditional2;
          break;
        case 12:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintAdditional3;
          break;
        case 13:
          oneRecordToPrint1 = algorithmToPrint._oneRecordToPrintAdditional4;
          flag = true;
          break;
      }
      if (algorithmToPrint._additional1 == 0 && oneRecordToPrint1 == algorithmToPrint._oneRecordToPrintAdditional1)
        ++num;
      else if (algorithmToPrint._additional2 == 0 && oneRecordToPrint1 == algorithmToPrint._oneRecordToPrintAdditional2)
        ++num;
      else if (algorithmToPrint._additional3 == 0 && oneRecordToPrint1 == algorithmToPrint._oneRecordToPrintAdditional3)
        ++num;
      else if (algorithmToPrint._additional4 == 0 && oneRecordToPrint1 == algorithmToPrint._oneRecordToPrintAdditional4)
      {
        ++num;
      }
      else
      {
        if (oneRecordToPrint1 != null && oneRecordToPrint1._listOneGrafaToPrint != null)
        {
          for (int index = 0; index < oneRecordToPrint1._listOneGrafaToPrint.Count; ++index)
          {
            Vedomost_VB.OneGrafaToPrint oneGrafaToPrint = oneRecordToPrint1._listOneGrafaToPrint[index];
            paraStringList.Add(new Vedomost_VB_Static.Para_String()
            {
              name = oneGrafaToPrint._cell_ID.ToString(),
              value = $"В строке \"{oneRecordToPrint1._tableRowId}\""
            });
          }
        }
        ++num;
      }
    }
    if (algorithmToPrint._list_OneRazdelToPrint != null)
    {
      for (int index1 = 0; index1 < algorithmToPrint._list_OneRazdelToPrint.Count; ++index1)
      {
        Vedomost_VB.OneRecordToPrint recordToPrintInfo = algorithmToPrint._list_OneRazdelToPrint[index1]._oneRecordToPrint_Info;
        if (recordToPrintInfo != null && recordToPrintInfo._listOneGrafaToPrint != null)
        {
          for (int index2 = 0; index2 < recordToPrintInfo._listOneGrafaToPrint.Count; ++index2)
          {
            Vedomost_VB.OneGrafaToPrint oneGrafaToPrint = recordToPrintInfo._listOneGrafaToPrint[index2];
            paraStringList.Add(new Vedomost_VB_Static.Para_String()
            {
              name = oneGrafaToPrint._cell_ID.ToString(),
              value = $"В строке \"{recordToPrintInfo._tableRowId}\""
            });
          }
        }
        if (oneRecordToPrint2 == null && index1 == 0)
          oneRecordToPrint2 = recordToPrintInfo;
      }
    }
    if (oneRecordToPrint2 != null && oneRecordToPrint2._isVtorOblast)
    {
      Vedomost_VB.OneRecordToPrint recordToPrintVtor = oneRecordToPrint2._oneRecordToPrint_Vtor;
      if (recordToPrintVtor != null && recordToPrintVtor._listOneGrafaToPrint != null)
      {
        for (int index = 0; index < recordToPrintVtor._listOneGrafaToPrint.Count; ++index)
        {
          Vedomost_VB.OneGrafaToPrint oneGrafaToPrint = recordToPrintVtor._listOneGrafaToPrint[index];
          paraStringList.Add(new Vedomost_VB_Static.Para_String()
          {
            name = oneGrafaToPrint._cell_ID.ToString(),
            value = $"Во вторичной строке \"{recordToPrintVtor._tableRowId}\""
          });
        }
      }
      Vedomost_VB.OneRecordToPrint recordToPrintItogo = oneRecordToPrint2._oneRecordToPrint_Itogo;
      if (recordToPrintItogo != null && recordToPrintItogo._listOneGrafaToPrint != null)
      {
        for (int index = 0; index < recordToPrintItogo._listOneGrafaToPrint.Count; ++index)
        {
          Vedomost_VB.OneGrafaToPrint oneGrafaToPrint = recordToPrintItogo._listOneGrafaToPrint[index];
          paraStringList.Add(new Vedomost_VB_Static.Para_String()
          {
            name = oneGrafaToPrint._cell_ID.ToString(),
            value = $"Во вторичной строке \"{recordToPrintItogo._tableRowId}\""
          });
        }
      }
    }
    return paraStringList;
  }

  /// <summary> Получаем список ID всех TextBox ШАБЛОНА </summary>
  /// <param name="docTemplate"></param>
  /// <returns></returns>
  public static List<string> Filled_list_Graf_IDs(ImDocument docTemplate)
  {
    if (docTemplate == null)
      return (List<string>) null;
    List<string> stringList = new List<string>();
    for (int index = 0; index < docTemplate.NodesCount; ++index)
    {
      DocumentTreeNode node = docTemplate.Nodes[index];
      if (!(node.Id == "TL") && !(node.Id == "Титульный лист") && !(node.Id == "LRI") && !(node.Id == "Лист регистрации изменений") && !(node.NodeClass != "Page"))
      {
        DocumentTreeNode firstChildNodeByName = node.FindFirstChildNodeByName("Главная таблица");
        if (firstChildNodeByName != null)
          Vedomost_VB_Static.Filled_One_Grafa_IDs(firstChildNodeByName, stringList);
      }
    }
    stringList.Sort();
    return stringList.Union<string>((IEnumerable<string>) stringList).ToList<string>();
  }

  /// <summary> Добавление в list ВСЕХ ID с "нырянием ниже" </summary>
  /// <param name="documentTreeNode"></param>
  /// <param name="list"></param>
  public static void Filled_One_Grafa_IDs(DocumentTreeNode documentTreeNode, List<string> list)
  {
    if (documentTreeNode == null || list == null)
      return;
    for (int index = 0; index < documentTreeNode.NodesCount; ++index)
    {
      DocumentTreeNode node = documentTreeNode.Nodes[index];
      if (node.NodeClass == "TextBoxElement")
      {
        string id = node.Id;
        if (!string.IsNullOrEmpty(id))
          list.Add(id);
      }
      else if (node.NodeClass == "TableElement" && node.Nodes != null)
        Vedomost_VB_Static.Filled_One_Grafa_IDs(node, list);
    }
  }

