  /// <summary> Привязать ведомость (ВЕРСИЮ) к изделию (и добавить её в СП) </summary>
  /// <param name="dbDocumentObjectVed"></param>
  public static DBRelationsEventArgs Create_Relation(long objectID_Owner, long objectID_Add)
  {
    using (SessionKeeper sessionKeeper = new SessionKeeper())
    {
      List<long> relationIDs = new List<long>();
      List<long> projIDs = new List<long>();
      List<int> intList1 = new List<int>();
      List<int> relTypeIDs = new List<int>();
      List<long> longList1 = new List<long>();
      List<long> longList2 = new List<long>();
      List<int> intList2 = new List<int>();
      List<int> intList3 = new List<int>();
      IDBRelation dbRelation = sessionKeeper.Session.GetRelationCollection(AvsIDCache.Relation_Document).Create(objectID_Owner, objectID_Add);
      relationIDs.Add(dbRelation.RelationID);
      projIDs.Add(dbRelation.ProjID);
      int objectTypeId = sessionKeeper.Session.GetObjectInfo(dbRelation.ProjID).ObjectTypeID;
      intList1.Add(objectTypeId);
      long sectionId = SpecificationSectionInfo.FindSectionById(SpecificationSectionInfo.ComplectSectionGuid).SectionID;
      dbRelation.SetAttributesValues(new AttributeValues[1]
      {
        new AttributeValues(AvsIDCache.Attr_SpecificationSection, (object) sectionId)
      });
      relTypeIDs.Add(dbRelation.RelationType);
      return new DBRelationsEventArgs("RelationsCreated", (IList<long>) relationIDs, (IList<long>) projIDs, (IList<int>) null, (IList<int>) relTypeIDs);
    }
  }

  /// <summary> Инициализация для ведомости с таким Guid </summary>
  /// <param name="guidVed"></param>
  /// <returns></returns>
  public static One_Ved_Nastr Ved_Nastr_Init(Guid guidVed, Guid guidTemplateVed, bool isWrite)
  {
    if (guidVed == Guid.Empty && guidTemplateVed == Guid.Empty)
      return (One_Ved_Nastr) null;
    One_Ved_Nastr ved_Nastr = new One_Ved_Nastr();
    if (guidVed == Guid.Empty)
      guidVed = Vedomost_VB_Static.Get_GuidVedomost_ByTemplateGuid(guidTemplateVed);
    if (guidVed == Guid.Empty)
      return (One_Ved_Nastr) null;
    ved_Nastr._guidTypeVed = guidVed;
    ved_Nastr._imsObjectType = MetaDataHelper.GetObjectType(ved_Nastr._guidTypeVed);
    if (ved_Nastr._imsObjectType == null)
      return (One_Ved_Nastr) null;
    ved_Nastr._idTypeVed = MetaDataHelper.GetObjectTypeID(ved_Nastr._guidTypeVed);
    ved_Nastr._typeDoc = Vedomost_VB.TypeDoc.Ved;
    bool flag = false;
    if (ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidVS)
    {
      Vedomost_VB_Static.VS_Nastr_Init(ved_Nastr);
      flag = true;
    }
    if (!flag && ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidVP)
    {
      Vedomost_VB_Static.VP_Nastr_Init(ved_Nastr);
      flag = true;
    }
    if (!flag && ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidRS)
    {
      Vedomost_VB_Static.RS_Nastr_Init(ved_Nastr);
      flag = true;
    }
    if (!flag && ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidVSI)
    {
      Vedomost_VB_Static.VSI_Nastr_Init(ved_Nastr);
      flag = true;
    }
    if (!flag && ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidVD)
    {
      Vedomost_VB_Static.VD_Nastr_Init(ved_Nastr);
      flag = true;
      if (string.IsNullOrEmpty(ved_Nastr._nameVed))
        ved_Nastr._nameVed = "Ведомость ссылочных документов";
    }
    if (!flag && ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidVDE)
    {
      Vedomost_VB_Static.VDE_Nastr_Init(ved_Nastr);
      flag = true;
    }
    if (!flag && ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidDP)
    {
      Vedomost_VB_Static.DP_Nastr_Init(ved_Nastr);
      flag = true;
    }
    if (!flag && ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidDPE)
    {
      Vedomost_VB_Static.DPE_Nastr_Init(ved_Nastr);
      flag = true;
    }
    if (!flag && ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidZI)
    {
      Vedomost_VB_Static.ZI_Nastr_Init(ved_Nastr);
      flag = true;
    }
    if (!flag && (ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidED || ved_Nastr._imsObjectType.Guid == new Guid("cadd9b7e-306c-11d8-b4e9-00304f19f545")))
    {
      Vedomost_VB_Static.ED_Nastr_Init(ved_Nastr);
      flag = true;
    }
    if (ved_Nastr._imsObjectType.Guid == Vedomost_VB_Static.GuidSPESPD)
    {
      Espd_Static.ESPD_Nastr_Init(ved_Nastr);
      ved_Nastr._typeDoc = Vedomost_VB.TypeDoc.Espd;
      flag = true;
    }
    if (flag)
    {
      Guid vedomosyByGuidTypeVed = Vedomost_VB_Static.Get_GuidTemplateVedomosy_ByGuidTypeVed(ved_Nastr._imsObjectType.Guid);
      if (vedomosyByGuidTypeVed != Guid.Empty)
