  /// <summary> Дополнение файла настройки если что-то новое не загрузилось </summary>
  /// <param name="One_Ved_Nastr"></param>
  /// <returns></returns>
  public static bool Ved_Nastr_Dopolnenie(One_Ved_Nastr One_Ved_Nastr, Vedomost_VB.TypeDoc typeDoc)
  {
    if (One_Ved_Nastr == null)
      return false;
    Guid guidTypeVed = One_Ved_Nastr._guidTypeVed;
    if (One_Ved_Nastr._bases_Options_Ved == null || !One_Ved_Nastr._bases_Options_Ved._isReadOrInit_isMain)
    {
      switch (typeDoc)
      {
        case Vedomost_VB.TypeDoc.Tabl:
          One_Ved_Nastr._bases_Options_Ved = Tabl_Static.Based_Options_Tabl_Init(guidTypeVed);
          break;
        case Vedomost_VB.TypeDoc.Espd:
          One_Ved_Nastr._bases_Options_Ved = Vedomost_VB_Static.Bases_Options_Ved_Init(guidTypeVed);
          break;
      }
      if (One_Ved_Nastr._bases_Options_Ved == null)
        One_Ved_Nastr._bases_Options_Ved = new Vedomost_VB.Bases_Options_Ved();
    }
    if (One_Ved_Nastr._bases_Options_Ved._list_quickObjectInfo == null)
      One_Ved_Nastr._bases_Options_Ved._list_quickObjectInfo = new List<QuickObjectInfo>();
    if (One_Ved_Nastr._dopoln_Options_Ved == null && typeDoc != Vedomost_VB.TypeDoc.Tabl)
      One_Ved_Nastr._dopoln_Options_Ved = Vedomost_VB_Static.Dopoln_Options_Ved_Init(guidTypeVed);
    if (One_Ved_Nastr._algorithmXml == null)
      One_Ved_Nastr._algorithmXml = typeDoc != Vedomost_VB.TypeDoc.Tabl ? Vedomost_VB_Static.AlgorithmXml_Init_By_GuidVed(guidTypeVed) : Tabl_Static.AlgorithmXml_Init_By_GuidTabl(guidTypeVed);
    if (One_Ved_Nastr._algorithm_Avs6_To_Ips == null)
    {
      if (typeDoc == Vedomost_VB.TypeDoc.Tabl)
      {
        One_Ved_Nastr._algorithm_Avs6_To_Ips = Tabl_Static.Algorithm_Avs6_To_Ips_Init_By_GuidTabl(guidTypeVed);
        if (One_Ved_Nastr._algorithm_Avs6_To_Ips == null)
          One_Ved_Nastr._algorithm_Avs6_To_Ips = Tabl_Static.Algorithm_Avs6_To_Ips_Tabl_Soed_Init();
      }
      else
      {
        One_Ved_Nastr._algorithm_Avs6_To_Ips = Vedomost_VB_Static.Algorithm_Avs6_To_Ips_Init_By_GuidVed(guidTypeVed);
        if (One_Ved_Nastr._algorithm_Avs6_To_Ips == null)
          One_Ved_Nastr._algorithm_Avs6_To_Ips = Vedomost_VB_Static.Algorithm_Avs6_To_Ips_RS_Init();
      }
    }
    if (One_Ved_Nastr._algorithm_Avs6_To_Ips_B == null && typeDoc != Vedomost_VB.TypeDoc.Tabl)
      One_Ved_Nastr._algorithm_Avs6_To_Ips_B = Vedomost_VB_Static.Algorithm_Avs6_To_Ips_B_Init_By_GuidVed(guidTypeVed);
    if (One_Ved_Nastr._accessLevel == 3)
      One_Ved_Nastr._accessLevel = 2;
    return true;
  }

