  private static void VSI_Nastr_Init(One_Ved_Nastr ved_Nastr)
  {
    ved_Nastr._nameVed = "Ведомость структуры изделия";
    Guid vedomosyByGuidTypeVed = Vedomost_VB_Static.Get_GuidTemplateVedomosy_ByGuidTypeVed(Vedomost_VB_Static.GuidVSI);
    ved_Nastr._vedomostTemplateObjectGuid = !(vedomosyByGuidTypeVed == Guid.Empty) ? vedomosyByGuidTypeVed : Vedomost_VB_Static.GuidTemplateVSI;
    ved_Nastr._typeVed = Vedomost_VB.TypeVed.VSI;
    ved_Nastr._guidParent = Guid.Empty;
    ved_Nastr._typeCreate = Vedomost_VB.TypeCreate.System;
