  /// <summary> Специальная обработка Ведомости ЗИП </summary>
  /// <param name="listRecordsVed_New"></param>
  /// <param name="one_Ved_Nastr_RazrabatyvaemoiVed"></param>
  public static void ZI_Processing_Razd(
    List<Vedomost_VB.RecordForVed_New> listRecordsVed_New,
    One_Ved_Nastr one_Ved_Nastr_RazrabatyvaemoiVed,
    Vedomost_VB vedomost_VB_General)
  {
    if (listRecordsVed_New == null || listRecordsVed_New.Count == 0 || one_Ved_Nastr_RazrabatyvaemoiVed == null || one_Ved_Nastr_RazrabatyvaemoiVed._typeVed != Vedomost_VB.TypeVed.ZI)
      return;
    for (int index1 = 0; index1 < listRecordsVed_New.Count; ++index1)
    {
      Vedomost_VB.RecordForVed_New recordForVedNew = listRecordsVed_New[index1];
      recordForVedNew.Get_Name();
      if ((double) recordForVedNew.Count_Summ != 0.0 || (double) recordForVedNew.Count_in_Sp != 0.0)
      {
        long objectId = recordForVedNew.Get_ObjectID();
        for (int index2 = 0; index2 < vedomost_VB_General._listRecordsVed_New.Count; ++index2)
        {
          if (vedomost_VB_General._listRecordsVed_New[index2].Get_ObjectID() == objectId && recordForVedNew.Razdel_Ved != 4L)
            recordForVedNew.Razdel_Ved = 1L;
        }
      }
    }
  }

  /// <summary> Заносим Кол в изделии из vedomost_VB_General </summary>
  /// <param name="listRecordsVed_New"></param>
  /// <param name="one_Ved_Nastr_RazrabatyvaemoiVed"></param>
  /// <param name="vedomost_VB_General"></param>
  public static void ZI_Processing_Count(
    List<Vedomost_VB.RecordForVed_New> listRecordsVed_New,
    One_Ved_Nastr one_Ved_Nastr_RazrabatyvaemoiVed,
    Vedomost_VB vedomost_VB_General)
  {
    if (listRecordsVed_New == null || listRecordsVed_New.Count == 0 || one_Ved_Nastr_RazrabatyvaemoiVed == null || one_Ved_Nastr_RazrabatyvaemoiVed._typeVed != Vedomost_VB.TypeVed.ZI)
      return;
    for (int index1 = 0; index1 < listRecordsVed_New.Count; ++index1)
    {
      Vedomost_VB.RecordForVed_New recordForVedNew1 = listRecordsVed_New[index1];
      recordForVedNew1.Get_Name();
      if ((double) recordForVedNew1.Count_Summ != 0.0)
      {
        long objectId = recordForVedNew1.Get_ObjectID();
        recordForVedNew1.Count_in_SpKompl = recordForVedNew1.Count_Summ;
        for (int index2 = 0; index2 < vedomost_VB_General._listRecordsVed_New.Count; ++index2)
        {
          Vedomost_VB.RecordForVed_New recordForVedNew2 = vedomost_VB_General._listRecordsVed_New[index2];
          if (recordForVedNew2.Get_ObjectID() == objectId && recordForVedNew1.Razdel_Ved == 1L)
            recordForVedNew1.Count_in_Izdelie = recordForVedNew2.Count_Summ;
        }
      }
    }
  }

